1	use std::cell::RefCell;
2	use std::collections::{BTreeMap, BTreeSet};
3	use std::path::{Path, PathBuf};
4	use std::sync::Arc;
5	
6	use callisto_manifests::{Manifest, OpenContext};
7	#[cfg(test)]
8	use callisto_model::ReleaseTrigger;
9	use callisto_model::{
10	    CommandRunner, DepEdge, DepSpec, Diagnostic, DiagnosticCode, DiagnosticSeverity, Ecosystem, ManifestDecl,
11	    ManifestFormat, ManifestRole, Package, PackageId, PublishTarget,
12	};
13	
14	use crate::config::resolve::{resolve_package_config, rule_applies};
15	use crate::config::ResolvedConfig;
16	use crate::error::GraphError;
17	use crate::identity::IdentityIndex;
18	use crate::locate::ProjectLocator;
19	use crate::manifest_cache::open_cached;
20	
21	fn relative_workspace_target(root: &Path, declaring_manifest: &Path, relative: &str) -> Option<PathBuf> {
22	    let root = root.canonicalize().ok()?;
23	    let source = root.join(declaring_manifest).parent()?.canonicalize().ok()?;
24	    let target = source.join(relative).canonicalize().ok()?;
25	    if !target.starts_with(&root) {
26	        return None;
27	    }
28	    Some(target)
29	}
30	#[allow(unused_imports)]
31	use crate::resolver::{DependencyResolver, ManifestWalkResolver};
32	
33	/// Returns (name-scoped claiming-ecosystem set, complete unfiltered native-key list)
34	/// for one path's own `list` of (ecosystem, declared-id) pairs. The first is filtered
35	/// to entries whose declared name equals `primary_id.name()`; the second is not filtered.
36	fn compute_claiming_ecosystems_and_native_keys(
37	    list: &[(Ecosystem, PackageId)],
38	    primary_id: &PackageId,
39	) -> (BTreeSet<Ecosystem>, Vec<(Ecosystem, String)>) {
40	    let claiming = list
41	        .iter()
42	        .filter(|(_, id)| id.name() == primary_id.name())
43	        .map(|(eco, _)| *eco)
44	        .collect();
45	    let native_keys = list.iter().map(|(eco, id)| (*eco, id.name().to_string())).collect();
46	    (claiming, native_keys)
47	}
48	
49	/// Disjointness test for two paths' name-scoped claiming-ecosystem sets --
50	/// {Cargo,Npm} and {Npm} are unequal but not disjoint. Kept for the
51	/// `is_promoted_bare_name` unit tests below; actual duplicate detection is
52	/// `native_owner` in `build`, keyed by every declared (ecosystem, name), not
53	/// just each path's primary name.
54	#[cfg(test)]
55	fn claiming_sets_disjoint(a: &BTreeSet<Ecosystem>, b: &BTreeSet<Ecosystem>) -> bool {
56	    a.is_disjoint(b)
57	}
58	
59	/// Returns true iff `paths.len() > 1` AND every distinct pair of paths in `paths`
60	/// has disjoint claiming-ecosystem sets in `claiming_ecosystems`.
61	///
62	/// Overlapping claiming sets indicate a true duplicate package error (handled
63	/// separately during graph construction), NOT a valid multi-ecosystem promotion.
64	#[cfg(test)]
65	fn is_promoted_bare_name(paths: &[PathBuf], claiming_ecosystems: &BTreeMap<PathBuf, BTreeSet<Ecosystem>>) -> bool {
66	    if paths.len() <= 1 {
67	        return false;
68	    }
69	    let mut seen = BTreeSet::new();
70	    for path in paths {
71	        if let Some(ecos) = claiming_ecosystems.get(path) {
72	            for eco in ecos {
73	                if !seen.insert(*eco) {
74	                    return false;
75	                }
76	            }
77	        }
78	    }
79	    true
80	}
81	
82	impl ManifestWalkResolver {
83	    pub fn build<L: ProjectLocator, R: CommandRunner>(
84	        root: &Path,
85	        locator: &L,
86	        _runner: &R,
87	        cfg: &ResolvedConfig,
88	        manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
89	    ) -> Result<Self, GraphError> {
90	        let ctx = OpenContext::for_workspace_root(root);
91	        let mut diagnostics = Vec::new();
92	
93	        let discovered = discover(root, locator, manifest_cache, &ctx, &mut diagnostics)?;
94	        let Identified {
95	            package_manifest_decls,
96	            index,
97	            promoted_siblings,
98	        } = assign_identities(discovered, manifest_cache, &ctx)?;
99	
100	        let cfg = cfg.with_promoted_siblings(promoted_siblings);
101	
102	        let packages = resolve_packages(package_manifest_decls, &cfg, manifest_cache, &ctx, &mut diagnostics)?;
103	
104	        let (edges, out_index, in_index) = build_edges(root, &packages, &index, manifest_cache, &ctx, &mut diagnostics);
105	
106	        Ok(ManifestWalkResolver {
107	            packages,
108	            edges,
109	            out_index,
110	            in_index,
111	            index,
112	            diagnostics,
113	        })
114	    }
115	}
116	
117	/// What the locator found: every project's identities by directory, and the npm platform packages attached to an
118	/// owner directory instead of standing as packages of their own.
119	struct Discovered {
120	    by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>>,
121	    attached_platforms: BTreeMap<PathBuf, (PathBuf, String, ManifestRole)>,
122	}
123	
124	/// Each package's manifests under its final identity, and the index that resolves every name to that identity.
125	struct Identified {
126	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
127	    index: IdentityIndex,
128	    /// An output of identity assignment: the sibling ids a bare name was promoted into.
129	    promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
130	}
131	
132	fn discover<L: ProjectLocator>(
133	    root: &Path,
134	    locator: &L,
135	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
136	    ctx: &OpenContext<'_>,
137	    diagnostics: &mut Vec<Diagnostic>,
138	) -> Result<Discovered, GraphError> {
139	    let (projects, platform_candidates) = locator.projects_and_platform_candidates()?;
140	
141	    // The locator already parsed each manifest, so reuse `proj.id`.
142	    let mut by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>> = BTreeMap::new();
143	    for proj in &projects {
144	        by_path
145	            .entry(proj.path.clone())
146	            .or_default()
147	            .push((proj.ecosystem, proj.id.clone()));
148	    }
149	
150	    let attached_platforms = platform_owners(root, &by_path, &platform_candidates, manifest_cache, ctx, diagnostics);
151	    Ok(Discovered {
152	        by_path,
153	        attached_platforms,
154	    })
155	}
156	
157	fn assign_identities(
158	    discovered: Discovered,
159	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
160	    ctx: &OpenContext<'_>,
161	) -> Result<Identified, GraphError> {
162	    let Discovered {
163	        by_path,
164	        attached_platforms,
165	    } = discovered;
166	    let mut assigner = IdentityAssigner::new(manifest_cache, ctx);
167	    for (rel_path, list) in by_path {
168	        if attached_platforms.contains_key(&rel_path) {
169	            continue;
170	        }
171	        assigner.assign(rel_path, list)?;
172	    }
173	    assigner.attach_platforms(attached_platforms);
174	    Ok(assigner.finish())
175	}
176	
177	/// The order-dependent identity assignment: whether a path's identity is bare or ecosystem-prefixed depends on the
178	/// names seen in earlier paths, so this is one incremental pass that owns all of its bookkeeping.
179	struct IdentityAssigner<'a> {
180	    manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
181	    ctx: &'a OpenContext<'a>,
182	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
183	    index: IdentityIndex,
184	    claiming_ecosystems: BTreeMap<PathBuf, BTreeSet<Ecosystem>>,
185	    // Every (ecosystem, native name) any path declares, anywhere in that path's
186	    // manifest list -- not only its primary name -- belongs to exactly one directory.
187	    native_owner: BTreeMap<(Ecosystem, String), PathBuf>,
188	    path_native_keys: BTreeMap<PathBuf, Vec<(Ecosystem, String)>>,
189	    path_platform_keys: BTreeMap<PathBuf, Vec<String>>,
190	    primary_ecosystems: BTreeMap<PathBuf, Ecosystem>,
191	    promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
192	}
193	
194	impl<'a> IdentityAssigner<'a> {
195	    fn new(manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>, ctx: &'a OpenContext<'a>) -> Self {
196	        IdentityAssigner {
197	            manifest_cache,
198	            ctx,
199	            package_manifest_decls: BTreeMap::new(),
200	            index: IdentityIndex::default(),
201	            claiming_ecosystems: BTreeMap::new(),
202	            native_owner: BTreeMap::new(),
203	            path_native_keys: BTreeMap::new(),
204	            path_platform_keys: BTreeMap::new(),
205	            primary_ecosystems: BTreeMap::new(),
206	            promoted_siblings: BTreeMap::new(),
207	        }
208	    }
209	
210	    fn assign(&mut self, rel_path: PathBuf, mut list: Vec<(Ecosystem, PackageId)>) -> Result<(), GraphError> {
211	        // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
212	        // Do NOT rely on enum discriminant order -- sort by this named
213	        // priority function so the precedence survives future variant
214	        // additions to `Ecosystem`.
215	        list.sort_by_key(|a| ecosystem_primary_priority(a.0));
216	
217	        // E100 whenever any (ecosystem, native name) this path declares -- primary
218	        // or not -- is already owned by a different path; names both. Checked before
219	        // any promotion bookkeeping so a dual-manifest directory's non-primary name
220	        // (e.g. an npm sibling of a Cargo-primary package) is covered too, not just
221	        // each path's own primary name.
222	        if let Some((eco, id)) = list.iter().find(|(eco, id)| {
223	            self.native_owner
224	                .get(&(*eco, id.name().to_string()))
225	                .is_some_and(|p| *p != rel_path)
226	        }) {
227	            let owner_path = self.native_owner[&(*eco, id.name().to_string())].clone();
228	            return Err(GraphError::DuplicatePackage {
229	                id: id.clone(),
230	                paths: vec![owner_path, rel_path],
231	            });
232	        }
233	        for (eco, id) in &list {
234	            self.native_owner
235	                .insert((*eco, id.name().to_string()), rel_path.clone());
236	        }
237	
238	        let mut primary_id = list[0].1.clone();
239	        let (this_claiming, this_native_keys) = compute_claiming_ecosystems_and_native_keys(&list, &primary_id);
240	        self.claiming_ecosystems.insert(rel_path.clone(), this_claiming.clone());
241	        self.path_native_keys.insert(rel_path.clone(), this_native_keys);
242	        self.primary_ecosystems.insert(rel_path.clone(), list[0].0);
243	
244	        let mut branch_ii_promoted = false;
245	        if self.promoted_siblings.contains_key(primary_id.name()) {
246	            let this_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
247	            let promoted_id = PackageId::Prefixed {
248	                ecosystem: self.primary_ecosystems[&rel_path],
249	                name: primary_id.name().to_string(),
250	            };
251	            self.promoted_siblings
252	                .entry(primary_id.name().to_string())
253	                .or_default()
254	                .push((promoted_id.clone(), this_set));
255	            primary_id = promoted_id;
256	            branch_ii_promoted = true;
257	        }
258	
259	        if !branch_ii_promoted {
260	            self.index
261	                .bare
262	                .insert(primary_id.name().to_string(), primary_id.clone());
263	        }
264	
265	        let mut decls = Vec::new();
266	        for (eco, id) in &list {
267	            let (fmt, filename) = match eco {
268	                Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
269	                Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
270	                Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
271	                _ => (ManifestFormat::PackageJson, "package.json"),
272	            };
273	            let manifest_rel = rel_path.join(filename);
274	            let canonical_decl = ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt).ok();
275	            if let Some(decl) = &canonical_decl {
276	                decls.push(decl.clone());
277	            }
278	            // For napi platform packages (os + cpu constraints in package.json),
279	            // also push a Platform-role decl so release derivation can route them
280	            // as platform publishes instead of main packages. Reuses
281	            // the canonical decl's manifest handle via the shared
282	            // `manifest_cache` (`npm_role()`) instead of a second, raw
283	            // `fs::read` of the same package.json -- the handle opened here
284	            // is the same one `publish_targets`/`iter_dependencies` reuse
285	            // further down.
286	            if *eco == Ecosystem::Npm {
287	                let role = canonical_decl
288	                    .as_ref()
289	                    .and_then(|decl| open_cached(self.manifest_cache, decl, self.ctx).ok())
290	                    .and_then(|m| m.npm_role())
291	                    .map(|npm_role| match npm_role {
292	                        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
293	                            ManifestRole::Platform { platform, arch, abi }
294	                        }
295	                    })
296	                    .unwrap_or(ManifestRole::Canonical);
297	                if let ManifestRole::Platform { .. } = role {
298	                    if let Ok(platform_decl) = ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
299	                        decls.push(platform_decl);
300	                    }
301	                    // `id` is this manifest's own npm identity, resolved from its
302	                    // own `name` field -- distinct from `primary_id` whenever a
303	                    // higher-priority ecosystem (Cargo) shares this directory.
304	                    // Config authors reference the platform package by
305	                    // its own name in `[[fixed-group]] members`, so that must be
306	                    // the index key; `primary_id` is who it belongs to.
307	                    self.index
308	                        .platform
309	                        .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
310	                    self.path_platform_keys
311	                        .entry(rel_path.clone())
312	                        .or_default()
313	                        .push(id.name().to_string());
314	                }
315	            }
316	            self.index
317	                .native
318	                .insert((*eco, id.name().to_string()), primary_id.clone());
319	            if id.name() == primary_id.name() {
320	                self.index
321	                    .prefixed
322	                    .insert((*eco, id.name().to_string()), primary_id.clone());
323	            }
324	        }
325	
326	        let current_decls = decls.clone();
327	        if let Some((existing_path, existing_decls)) = self
328	            .package_manifest_decls
329	            .insert(primary_id.clone(), (rel_path.clone(), decls))
330	        {
331	            self.promotion_rekey(primary_id, existing_path, existing_decls, rel_path, current_decls);
332	        }
333	        Ok(())
334	    }
335	
336	    /// A second path just claimed the bare name `primary_id`, so both paths are promoted to ecosystem-prefixed ids
337	    /// and every key already stored under the stale bare id is re-keyed.
338	    fn promotion_rekey(
339	        &mut self,
340	        primary_id: PackageId,
341	        existing_path: PathBuf,
342	        existing_decls: Vec<ManifestDecl>,
343	        rel_path: PathBuf,
344	        current_decls: Vec<ManifestDecl>,
345	    ) {
346	        // Both paths' claiming ecosystems are guaranteed disjoint here: an
347	        // overlap would already have failed at the native_owner check above.
348	        let name = primary_id.name().to_string();
349	        // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
350	        // each path's own newly-promoted Prefixed id, sourcing each path's own
351	        // decls -- captured via the `existing_decls` returned by `insert` above
352	        // and the `current_decls` clone taken before `insert` overwrote the map,
353	        // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
354	        // there would silently substitute an empty Vec -- the
355	        // manifests-bleed bug).
356	        let existing_id = PackageId::Prefixed {
357	            ecosystem: self.primary_ecosystems[&existing_path],
358	            name: name.clone(),
359	        };
360	        let current_id = PackageId::Prefixed {
361	            ecosystem: self.primary_ecosystems[&rel_path],
362	            name: name.clone(),
363	        };
364	        self.package_manifest_decls
365	            .insert(existing_id.clone(), (existing_path.clone(), existing_decls));
366	        self.package_manifest_decls
367	            .insert(current_id.clone(), (rel_path.clone(), current_decls));
368	        self.package_manifest_decls.remove(&primary_id);
369	        // STALE-KEY REWRITE location (1): once a bare name is promoted,
370	        // it MUST NOT remain in index.bare.
371	        self.index.bare.remove(&name);
372	        // STALE-KEY REWRITE location (2): update index.native values
373	        // for all native keys declared by either path so they map to
374	        // their path's newly-promoted Prefixed id, not the stale primary_id.
375	        if let Some(keys) = self.path_native_keys.get(&existing_path) {
376	            for key in keys {
377	                self.index.native.insert(key.clone(), existing_id.clone());
378	            }
379	        }
380	        if let Some(keys) = self.path_native_keys.get(&rel_path) {
381	            for key in keys {
382	                self.index.native.insert(key.clone(), current_id.clone());
383	            }
384	        }
385	        // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
386	        // for the primary identities so they point to the newly-promoted
387	        // Prefixed id rather than the pre-promotion primary_id.
388	        for eco in self
389	            .claiming_ecosystems
390	            .get(&existing_path)
391	            .cloned()
392	            .unwrap_or_default()
393	        {
394	            self.index.prefixed.insert((eco, name.clone()), existing_id.clone());
395	        }
396	        for eco in self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
397	            self.index.prefixed.insert((eco, name.clone()), current_id.clone());
398	        }
399	        // STALE-KEY REWRITE location (6): update index.platform's owner-id
400	        // component for every platform manifest declared under either path,
401	        // so a platform sibling co-located with a promoted owner keeps
402	        // pointing at that owner's newly-promoted Prefixed id rather than
403	        // the stale pre-promotion primary_id.
404	        if let Some(keys) = self.path_platform_keys.get(&existing_path) {
405	            for key in keys {
406	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
407	                    self.index
408	                        .platform
409	                        .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
410	                }
411	            }
412	        }
413	        if let Some(keys) = self.path_platform_keys.get(&rel_path) {
414	            for key in keys {
415	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
416	                    self.index
417	                        .platform
418	                        .insert(key.clone(), (current_id.clone(), manifest_rel, role));
419	                }
420	            }
421	        }
422	        let existing_set = self
423	            .claiming_ecosystems
424	            .get(&existing_path)
425	            .cloned()
426	            .unwrap_or_default();
427	        let current_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
428	        self.promoted_siblings
429	            .entry(name.clone())
430	            .or_default()
431	            .extend([(existing_id, existing_set), (current_id, current_set)]);
432	    }
433	
434	    /// After every path is assigned, so each owner's id is final (post-promotion).
435	    fn attach_platforms(&mut self, attached_platforms: BTreeMap<PathBuf, (PathBuf, String, ManifestRole)>) {
436	        for (platform_dir, (owner_dir, name, role)) in attached_platforms {
437	            let manifest_rel = platform_dir.join("package.json");
438	            let owner = self.package_manifest_decls.iter_mut().find(|(_, (path, decls))| {
439	                *path == owner_dir && decls.iter().any(|d| d.format == ManifestFormat::PackageJson)
440	            });
441	            let (Some((owner_id, (_, decls))), Ok(decl)) = (
442	                owner,
443	                ManifestDecl::new(manifest_rel.clone(), role.clone(), ManifestFormat::PackageJson),
444	            ) else {
445	                continue;
446	            };
447	            decls.push(decl);
448	            self.index.platform.insert(name, (owner_id.clone(), manifest_rel, role));
449	        }
450	    }
451	
452	    fn finish(self) -> Identified {
453	        Identified {
454	            package_manifest_decls: self.package_manifest_decls,
455	            index: self.index,
456	            promoted_siblings: self.promoted_siblings,
457	        }
458	    }
459	}
