461	/// Applies `[[package]]` and `[[package-set]]` rules to each identified package, then reports rules that matched
462	/// nothing or matched across ecosystems.
463	fn resolve_packages(
464	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
465	    cfg: &ResolvedConfig,
466	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
467	    ctx: &OpenContext<'_>,
468	    diagnostics: &mut Vec<Diagnostic>,
469	) -> Result<BTreeMap<PackageId, Package>, GraphError> {
470	    // Tracks, per cfg.package_sets entry (by index), whether it matched at
471	    // least one real discovered package during this walk. A [[package-set]]
472	    // rule that matches nothing is almost always a typo or a stale
473	    // ecosystem prefix (see PackageSetMatchedNothing below) rather than
474	    // intentional, so it must be surfaced instead of silently ignored.
475	    let mut package_set_matched = vec![false; cfg.package_sets.len()];
476	
477	    // Same tracking, for `[[package]]` rules: an exact-id rule that matches zero real
478	    // packages (e.g. an ecosystem prefix the package doesn't actually have) is just as
479	    // likely a typo as an empty `[[package-set]]` glob, so it gets the same diagnostic.
480	    let mut package_rule_matched = vec![false; cfg.packages.len()];
481	
482	    let mut packages = BTreeMap::new();
483	    for (id, (rel_path, decls)) in package_manifest_decls {
484	        let ch_path = rel_path.join("CHANGELOG.md");
485	        let mut publish_to = Vec::new();
486	        // Attached platform manifests publish as their owner's platform operations, not as targets.
487	        for decl in decls.iter().filter(|d| d.role == ManifestRole::Canonical) {
488	            if let Ok(editor) = open_cached(manifest_cache, decl, ctx) {
489	                for target in editor.publish_targets() {
490	                    if target != PublishTarget::None && !publish_to.contains(&target) {
491	                        publish_to.push(target);
492	                    }
493	                }
494	            }
495	        }
496	        if publish_to.is_empty() {
497	            publish_to.push(PublishTarget::None);
498	        }
499	
500	        // The real ecosystem(s) this package's manifests were discovered
501	        // in. `id` may be PackageId::Bare (unpromoted) or PackageId::Prefixed
502	        // (promoted); this is the
503	        // only place an ecosystem-prefixed [[package-set]] pattern has
504	        // anything to match against.
505	        let package_ecosystems: Vec<Ecosystem> = decls.iter().map(|d| d.ecosystem()).collect();
506	
507	        // Two-pass specificity search for [[package]] rules.
508	        // Pass 1: find the first Prefixed rule (pattern.ecosystem().is_some())
509	        //         that matches this package's ID. Prefixed rules always win
510	        //         over Bare rules regardless of declaration order in callisto.toml.
511	        // Pass 2: only if pass 1 found nothing, find the first Bare rule
512	        //         (any rule, since no Prefixed rule matched, the first match
513	        //          is necessarily Bare) that matches this package's ID.
514	        // Within each pass, first-match-wins (TOML declaration order) applies.
515	        let pkg_override = resolve_package_config(&id, &package_ecosystems, cfg)?;
516	
517	        // Record which [[package-set]] patterns match this package,
518	        // independent of whether a [[package]] rule ends up shadowing the
519	        // fallback below — a pattern that is always shadowed still
520	        // "matched" for the purpose of the zero-match diagnostic.
521	        for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
522	            if pattern.matches_in_ecosystems(id.name(), &package_ecosystems) {
523	                package_set_matched[idx] = true;
524	            }
525	        }
526	        for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
527	            if rule_applies(rule_id, &id, &package_ecosystems) {
528	                package_rule_matched[idx] = true;
529	            }
530	        }
531	
532	        // If no [[package]] rule matched, look for a [[package-set]] fallback.
533	        // [[package-set]] uses glob patterns and can match many packages at once;
534	        // [[package]] always takes priority over [[package-set]] for the same package.
535	        let set_override = if pkg_override.is_none() {
536	            cfg.package_sets
537	                .iter()
538	                .find(|(pattern, _)| pattern.matches_in_ecosystems(id.name(), &package_ecosystems))
539	                .map(|(_, cfg)| cfg)
540	        } else {
541	            None
542	        };
543	
544	        let active_override = pkg_override.or(set_override);
545	
546	        // Single source of truth for the default: ReleaseTrigger's #[default].
547	        let release_trigger = active_override.and_then(|o| o.release_trigger).unwrap_or_default();
548	
549	        let tag_template = active_override.and_then(|o| o.tag_template.clone());
550	
551	        let changelog = if let Some(override_path) = active_override.and_then(|o| o.changelog.as_ref()) {
552	            Some(rel_path.join(override_path))
553	        } else {
554	            Some(ch_path)
555	        };
556	
557	        // Apply the resolved override's publish-to if the operator explicitly set it.
558	        //
559	        // A `[[package]]`/`[[package-set]]` rule has no package context at
560	        // config-parse time (it's just a pattern + string list), so the
561	        // only place the package's real, detected ecosystem is known is
562	        // here, once `decls` (the package's actual manifests) have been
563	        // walked. Reject any configured target whose `.ecosystem()` does
564	        // not match one of the package's detected ecosystems — e.g.
565	        // `publish-to = ["nuget"]` on a Cargo-only crate — rather than
566	        // silently accepting it and having the crate vanish from every
567	        // real publish downstream with zero diagnostic.
568	        if let Some(override_targets) = active_override.and_then(|o| o.publish_to.as_deref()) {
569	            for target in override_targets {
570	                if let Some(target_ecosystem) = target.ecosystem() {
571	                    if !package_ecosystems.contains(&target_ecosystem) {
572	                        return Err(GraphError::PublishTargetEcosystemMismatch {
573	                            package: id.clone(),
574	                            target: target.config_str().to_string(),
575	                            target_ecosystem,
576	                            package_ecosystems,
577	                        });
578	                    }
579	                }
580	            }
581	            // The override replaces *which* targets the package publishes
582	            // to, but must not silently drop manifest-derived fields
583	            // (npm publishConfig.access/registry) the config itself
584	            // didn't set -- config wins when explicit, manifest fills gaps.
585	            publish_to = override_targets
586	                .iter()
587	                .map(|target| {
588	                    let manifest_target = target
589	                        .ecosystem()
590	                        .and_then(|eco| publish_to.iter().find(|m| m.ecosystem() == Some(eco)));
591	                    match manifest_target {
592	                        Some(manifest_target) => target.clone().merge_manifest_gaps(manifest_target),
593	                        None => target.clone(),
594	                    }
595	                })
596	                .collect();
597	        }
598	
599	        let pkg = Package {
600	            id: id.clone(),
601	            manifests: decls,
602	            changelog,
603	            release_trigger,
604	            publish_to,
605	            tag_template,
606	        };
607	        packages.insert(id, pkg);
608	    }
609	
610	    // A [[package-set]] rule that matched zero real packages is almost
611	    // always a mistake (e.g. an ecosystem prefix that doesn't correspond
612	    // to any discovered package, or a typo in the glob) rather than
613	    // intentional, so surface it as a visible, non-fatal diagnostic
614	    // instead of letting the rule silently do nothing. This is
615	    // deliberately advisory rather than a hard `GraphError`: a
616	    // `[[package-set]]` rule declared for a monorepo-wide callisto.toml
617	    // can legitimately match nothing when only part of the workspace is
618	    // present (e.g. a partial checkout or filtered walk), and a hard
619	    // error would break that case.
620	    for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
621	        if !package_set_matched[idx] {
622	            diagnostics.push(Diagnostic {
623	                code: DiagnosticCode::PackageSetMatchedNothing,
624	                severity: DiagnosticSeverity::Warning,
625	                message: format!("[[package-set]] `{}` matched no packages", pattern.as_str()),
626	                package: None,
627	                path: None,
628	                escalated_by: None,
629	                governed_by: None,
630	            });
631	        }
632	    }
633	
634	    // A [[package]] rule that matched zero real packages is the same kind of mistake as an
635	    // empty [[package-set]] match above (e.g. `cargo/foo` when `foo` only exists in npm) --
636	    // advisory for the same reason: a monorepo-wide callisto.toml against a partial checkout
637	    // can legitimately match nothing.
638	    for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
639	        if !package_rule_matched[idx] {
640	            diagnostics.push(Diagnostic {
641	                code: DiagnosticCode::PackageRuleMatchedNothing,
642	                severity: DiagnosticSeverity::Warning,
643	                message: format!("[[package]] `{rule_id}` matched no packages"),
644	                package: None,
645	                path: None,
646	                escalated_by: None,
647	                governed_by: None,
648	            });
649	        }
650	    }
651	
652	    // Cross-ecosystem diagnostic pass.
653	    //
654	    // For each bare [[package]] rule in cfg.packages (pattern.ecosystem() == None),
655	    // compute the distinct-ecosystem set: the Ecosystem values found in the canonical
656	    // ManifestDecls of every packages-map entry matched by this rule.
657	    //
658	    // Packages-map keys may be PackageId::Bare or PackageId::Prefixed (a
659	    // promoted package). This loop
660	    // remains correct regardless: ecosystem information is always sourced from
661	    // pkg.canonical_manifests(), never from key.ecosystem(), and `pattern`
662	    // here is always unprefixed (prefixed rules `continue` above), so
663	    // pattern.matches(key) matches by name alone independent of whether `key`
664	    // itself is Bare or Prefixed. Do NOT use key.ecosystem().
665	    //
666	    // The primary trigger is a single directory containing both Cargo.toml and
667	    // package.json (the napi case): one packages-map entry with two canonical
668	    // ManifestDecls whose ecosystems are {Cargo, Npm}.
669	    //
670	    // Prefixed [[package]] rules are skipped unconditionally.
671	    // [[package-set]] rules are never iterated here.
672	    for (pattern, _) in &cfg.packages {
673	        if pattern.ecosystem().is_some() {
674	            continue; // Prefixed rules never trigger this diagnostic.
675	        }
676	        let ecosystems: BTreeSet<Ecosystem> = packages
677	            .iter()
678	            .filter(|(key, _)| pattern.matches(key))
679	            // Use the existing Package::canonical_manifests() helper
680	            // (package.rs) which filters to ManifestRole::Canonical.
681	            .flat_map(|(_, pkg)| pkg.canonical_manifests().map(|d| d.ecosystem()))
682	            .collect();
683	        if ecosystems.len() >= 2 {
684	            let eco_list: Vec<&str> = ecosystems.iter().map(|e| e.prefix()).collect();
685	            diagnostics.push(Diagnostic {
686	                code: DiagnosticCode::BareRuleMatchesMultipleEcosystems,
687	                severity: DiagnosticSeverity::Warning,
688	                message: format!(
689	                    "[[package]] rule `{}` matches packages in multiple ecosystems ({}); \
690	                         use an ecosystem-prefixed pattern like `{}/{}` to target only one",
691	                    pattern.name(),
692	                    eco_list.join(", "),
693	                    ecosystems.iter().next().map(|e| e.prefix()).unwrap_or("cargo"),
694	                    pattern.name(),
695	                ),
696	                package: None,
697	                path: None,
698	                escalated_by: None,
699	                governed_by: None,
700	            });
701	        }
702	    }
703	
704	    Ok(packages)
705	}
706	
707	type EdgeIndex = BTreeMap<PackageId, Vec<usize>>;
708	
709	/// One edge per dependency declaration of each canonical manifest that resolves to a workspace package.
710	fn build_edges(
711	    root: &Path,
712	    packages: &BTreeMap<PackageId, Package>,
713	    index: &IdentityIndex,
714	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
715	    ctx: &OpenContext<'_>,
716	    diagnostics: &mut Vec<Diagnostic>,
717	) -> (Vec<DepEdge>, EdgeIndex, EdgeIndex) {
718	    let mut edges = Vec::new();
719	    let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
720	    let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
721	
722	    for pkg in packages.values() {
723	        for decl in &pkg.manifests {
724	            if decl.role != ManifestRole::Canonical {
725	                continue;
726	            }
727	            if let Ok(m) = open_cached(manifest_cache, decl, ctx) {
728	                for entry in m.iter_dependencies() {
729	                    let (spec, declaring_path) = if entry.inherited {
730	                        if let Some(ref inh) = ctx.cargo_workspace {
731	                            if let Some(inherited_dep) = inh.inherited(&entry.name) {
732	                                (inherited_dep.spec.clone(), inherited_dep.declared_in.to_path_buf())
733	                            } else {
734	                                (entry.spec.clone(), decl.path.clone())
735	                            }
736	                        } else {
737	                            (entry.spec.clone(), decl.path.clone())
738	                        }
739	                    } else {
740	                        (entry.spec.clone(), decl.path.clone())
741	                    };
742	
743	                    let workspace_target = match &spec {
744	                        DepSpec::WorkspaceProtocol(workspace) => workspace
745	                            .relative_path()
746	                            .and_then(|relative| relative_workspace_target(root, &decl.path, relative))
747	                            .and_then(|target| {
748	                                packages.values().find(|package| {
749	                                    package.canonical_manifests().any(|manifest| {
750	                                        manifest.ecosystem() == Ecosystem::Npm
751	                                            && root
752	                                                .join(manifest.path.parent().unwrap_or(Path::new("")))
753	                                                .canonicalize()
754	                                                .ok()
755	                                                .as_ref()
756	                                                == Some(&target)
757	                                    })
758	                                })
759	                            })
760	                            .map(|package| package.id.clone()),
761	                        _ => None,
762	                    };
763	                    let to = match &spec {
764	                        DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some() => {
765	                            workspace_target
766	                        }
767	                        _ => workspace_target.or_else(|| {
768	                            index
769	                                .resolve_native_with_fallback(decl.ecosystem(), &entry.package_name, diagnostics)
770	                                .cloned()
771	                        }),
772	                    };
773	                    if let Some(to) = to {
774	                        let idx = edges.len();
775	                        let edge = DepEdge {
776	                            from: pkg.id.clone(),
777	                            to: to.clone(),
778	                            name: entry.name,
779	                            kind: entry.kind,
780	                            spec,
781	                            from_manifest: declaring_path,
782	                            inherited: entry.inherited,
783	                            locator: entry.locator,
784	                        };
785	                        edges.push(edge);
786	
787	                        out_index.entry(pkg.id.clone()).or_default().push(idx);
788	                        in_index.entry(to).or_default().push(idx);
789	                    } else if matches!(&spec, DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some())
790	                    {
791	                        diagnostics.push(Diagnostic {
792	                                code: DiagnosticCode::UnknownPackage,
793	                                severity: DiagnosticSeverity::Warning,
794	                                message: format!(
795	                                    "relative pnpm workspace dependency `{}` from `{}` does not identify an admitted npm workspace member",
796	                                    entry.name,
797	                                    decl.path.display()
798	                                ),
799	                                package: Some(pkg.id.clone()),
800	                                path: Some(decl.path.clone()),
801	                                escalated_by: None,
802	                                governed_by: None,
803	                            });
804	                    }
805	                }
806	            }
807	        }
808	    }
809	
810	    (edges, out_index, in_index)
811	}
812	
813	/// Maps each npm-only platform package directory (`os`+`cpu`)
814	/// to the owner directory whose `package.json` names it in `optionalDependencies`,
815	/// plus the platform's own name and role. `non_members` are platform packages
816	/// outside the npm workspace, attachable but otherwise not discovered. A member
817	/// platform named by no owner, or by more than one, stays its own package with a
818	/// diagnostic.
819	fn platform_owners(
820	    root: &Path,
821	    by_path: &BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>>,
822	    non_members: &[callisto_model::ProjectRoot],
823	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
824	    ctx: &OpenContext<'_>,
825	    diagnostics: &mut Vec<Diagnostic>,
826	) -> BTreeMap<PathBuf, (PathBuf, String, ManifestRole)> {
827	    let open_npm = |rel_path: &Path| {
828	        let decl = ManifestDecl::new(
829	            rel_path.join("package.json"),
830	            ManifestRole::Canonical,
831	            ManifestFormat::PackageJson,
832	        )
833	        .ok()?;
834	        open_cached(manifest_cache, &decl, ctx).ok()
835	    };
836	    let platform_role = |manifest: &Arc<dyn Manifest>| match manifest.npm_role()? {
837	        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
838	            Some(ManifestRole::Platform { platform, arch, abi })
839	        }
840	    };
841	
842	    let mut platforms = Vec::new();
843	    let mut owners_of: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
844	    for (rel_path, list) in by_path {
845	        let Some((_, id)) = list.iter().find(|(eco, _)| *eco == Ecosystem::Npm) else {
846	            continue;
847	        };
848	        let Some(manifest) = open_npm(rel_path) else {
849	            continue;
850	        };
851	        // A co-located platform manifest already belongs to its directory's package.
852	        match platform_role(&manifest) {
853	            Some(role) if list.len() == 1 => platforms.push((rel_path.clone(), id.name().to_string(), role, true)),
854	            _ => {
855	                for dep in manifest.iter_dependencies() {
856	                    if dep.kind == callisto_model::DepKind::Optional {
857	                        owners_of.entry(dep.name).or_default().push(rel_path.clone());
858	                    }
859	                }
860	            }
861	        }
862	    }
863	    for candidate in non_members {
864	        if by_path.contains_key(&candidate.path) {
865	            continue;
866	        }
867	        // A Cargo/Python package physically sits beside this candidate's package.json even
868	        // though it wasn't discovered as a workspace member here (e.g. filtered out by that
869	        // ecosystem's own membership) -- attaching it as a bare platform manifest would
870	        // misattach a directory that already hosts a real, distinct package.
871	        if root.join(&candidate.path).join("Cargo.toml").is_file()
872	            || root.join(&candidate.path).join("pyproject.toml").is_file()
873	        {
874	            continue;
875	        }
876	        if let Some(role) = open_npm(&candidate.path).as_ref().and_then(platform_role) {
877	            platforms.push((candidate.path.clone(), candidate.id.name().to_string(), role, false));
878	        }
879	    }
880	
881	    let mut attached = BTreeMap::new();
882	    for (rel_path, name, role, member) in platforms {
883	        match owners_of.get(&name).map(Vec::as_slice) {
884	            Some([owner]) => {
885	                attached.insert(rel_path, (owner.clone(), name, role));
886	            }
887	            None if !member => {}
888	            owners => {
889	                let reason = match owners {
890	                    Some(owners) => format!(
891	                        "is named in the optionalDependencies of {} packages ({})",
892	                        owners.len(),
893	                        owners
894	                            .iter()
895	                            .map(|p| p.display().to_string())
896	                            .collect::<Vec<_>>()
897	                            .join(", ")
898	                    ),
899	                    None => "is not named in any npm package's optionalDependencies".to_string(),
900	                };
901	                diagnostics.push(Diagnostic {
902	                    code: DiagnosticCode::PlatformPackageWithoutOwner,
903	                    severity: DiagnosticSeverity::Warning,
904	                    message: format!(
905	                        "npm platform package `{name}` {reason}; {}",
906	                        if member {
907	                            "it is released as its own package instead of as a platform manifest of its owner"
908	                        } else {
909	                            "it is outside the npm workspace, so it is not released at all"
910	                        }
911	                    ),
912	                    package: None,
913	                    path: Some(rel_path.join("package.json")),
914	                    escalated_by: None,
915	                    governed_by: None,
916	                });
917	            }
918	        }
919	    }
920	    attached
921	}
922	
923	/// Explicit ecosystem precedence for primary-ID selection when a single
924	/// project directory contains manifests from multiple ecosystems (e.g., both
925	/// `Cargo.toml` and `package.json`). Lower value = higher priority.
926	///
927	/// Precedence: Cargo (0) > Npm (1) > Pypi (2) > others (255).
928	///
929	/// This function is used instead of `Ecosystem`'s derived `Ord` so that the
930	/// ordering is stable even if the `Ecosystem` variant sequence changes.
931	fn ecosystem_primary_priority(e: Ecosystem) -> u8 {
932	    match e {
933	        Ecosystem::Cargo => 0,
934	        Ecosystem::Npm => 1,
935	        Ecosystem::Pypi => 2,
936	        _ => u8::MAX,
937	    }
938	}
