1	//! Per-ecosystem manifest read/write for callisto.
2	
3	use std::path::Path;
4	use std::sync::Arc;
5	
6	use callisto_model::{
7	    ApplyPermit, DepSpec, Ecosystem, ManifestDecl, ManifestError, ManifestFormat, ManifestRole, Version, WorkspaceKind,
8	};
9	
10	pub mod atomic;
11	
12	pub mod cargo;
13	mod common;
14	pub mod npm;
15	pub mod python;
16	
17	pub use cargo::{cargo_package_name, CargoToml, InheritedDep, WorkspaceCargoResolver, WorkspaceInheritance};
18	pub use npm::{
19	    detect_npm_workspace_kind, napi_binary_name, npm_declares_private, npm_package_name, npm_role_from_source,
20	    read_napi_targets, PackageJson,
21	};
22	pub use python::{python_package_name, PyprojectToml, Requirement};
23	
24	/// Package identity extracted directly from manifest source text via
25	/// [`read_identity`], without going through the full `Manifest::open`
26	/// lifecycle (workspace-inheritance context, on-disk path resolution,
27	/// atomic-write machinery). For callers that already hold a manifest's
28	/// content as a string -- a `git show` blob, a walker's pre-read buffer --
29	/// and only need the package's name and/or where its version comes from.
30	#[derive(Clone, Debug, Default, PartialEq, Eq)]
31	pub struct ManifestIdentity {
32	    pub name: Option<String>,
33	    pub version: Option<VersionSource>,
34	}
35	
36	/// Where a manifest's version declaration comes from. Distinct from a raw
37	/// `Option<String>` so Cargo's `version.workspace = true` is a real,
38	/// distinguishable case instead of being silently collapsed into "no
39	/// version present". [`read_identity`] never resolves the inherited value
40	/// (it has no workspace context); [`read_effective_version`] resolves supplied blobs.
41	#[derive(Clone, Debug, PartialEq, Eq)]
42	pub enum VersionSource {
43	    Literal(String),
44	    InheritedFromWorkspace,
45	}
46	
47	#[derive(Clone, Debug, PartialEq, Eq)]
48	pub struct EffectiveManifestVersion {
49	    pub version: Version,
50	    pub authority: std::path::PathBuf,
51	}
52	
53	/// Resolves supplied blobs without I/O; paths must already be normalized and workspace-relative.
54	pub fn read_effective_version(
55	    format: ManifestFormat,
56	    source: &str,
57	    path: &Path,
58	    cargo_workspace: Option<(&Path, &str)>,
59	) -> Result<Option<EffectiveManifestVersion>, ManifestError> {
60	    let identity = read_identity(format, source, path)?;
61	    let (version, authority) = match identity.version {
62	        Some(VersionSource::Literal(raw)) => {
63	            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
64	                ManifestError::InvalidVersion {
65	                    path: path.to_path_buf(),
66	                    raw,
67	                    source,
68	                }
69	            })?;
70	            (version, path.to_path_buf())
71	        }
72	        Some(VersionSource::InheritedFromWorkspace) => {
73	            let (root_path, root_source) = cargo_workspace.ok_or_else(|| ManifestError::MissingField {
74	                path: path.to_path_buf(),
75	                field: "workspace.package.version",
76	            })?;
77	            let version = cargo::workspace_version_from_source(root_source, root_path)?.ok_or_else(|| {
78	                ManifestError::MissingField {
79	                    path: root_path.to_path_buf(),
80	                    field: "workspace.package.version",
81	                }
82	            })?;
83	            (version, root_path.to_path_buf())
84	        }
85	        None => return Ok(None),
86	    };
87	    Ok(Some(EffectiveManifestVersion { version, authority }))
88	}
89	
90	/// Extracts a package's name and version source directly from `source`,
91	/// the raw text of a manifest matching `format`. Pure and I/O-free.
92	///
93	/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
94	/// call sites that already hold manifest content as a string rather than a
95	/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
96	/// blob, or a directory-walker's pre-read buffer.
97	///
98	/// `path` is used only to build accurate `ManifestError::Parse` locations
99	/// on a parse failure; it need not exist on disk. Only the three
100	/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
101	/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
102	pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
103	    match format {
104	        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
105	        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
106	        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
107	        other => Err(ManifestError::ReadOnlyFormat {
108	            path: path.to_path_buf(),
109	            format: other,
110	            reason: "read_identity only supports the three canonical-identity manifest formats \
111	                     (Cargo.toml, package.json, pyproject.toml)",
112	        }),
113	    }
114	}
115	
116	/// The role an npm `package.json` manifest's own content declares itself to
117	/// play (e.g. a napi-rs platform package, signaled by `os`+`cpu` constraint
118	/// arrays), detected directly from the manifest's already-parsed document.
119	///
120	/// Distinct from [`ManifestRole`], which reflects the role a [`ManifestDecl`]
121	/// was *opened with* (assigned externally by the caller), not what the
122	/// manifest content itself declares. [`Manifest::npm_role`] lets a caller
123	/// holding an already-open handle (e.g. from a shared cache) recover this
124	/// without a second read of the underlying file.
125	#[derive(Clone, Debug, PartialEq, Eq)]
126	pub enum NpmRole {
127	    Platform {
128	        platform: String,
129	        arch: String,
130	        abi: Option<String>,
131	    },
132	}
133	
134	/// Trait implemented by per-ecosystem manifest editors.
135	pub trait Manifest: Send + Sync {
136	    fn path(&self) -> &Path;
137	    fn ecosystem(&self) -> Ecosystem;
138	    fn role(&self) -> ManifestRole;
139	    fn package_name(&self) -> Result<String, ManifestError>;
140	    fn current_version(&self) -> Result<Version, ManifestError>;
141	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
142	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
143	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
144	    fn update_dependency_spec(
145	        &mut self,
146	        name: &str,
147	        kind: callisto_model::DepKind,
148	        at: &callisto_model::DepLocator,
149	        new: DepSpec,
150	        permit: &ApplyPermit,
151	    ) -> Result<(), ManifestError>;
152	    fn is_publishable(&self) -> bool {
153	        true
154	    }
155	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
156	        if !self.is_publishable() {
157	            return vec![callisto_model::PublishTarget::None];
158	        }
159	        match self.ecosystem() {
160	            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
161	            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
162	                registry: None,
163	                access: None,
164	            }],
165	            _ => vec![callisto_model::PublishTarget::None],
166	        }
167	    }
168	    fn update_optional_dependencies(
169	        &mut self,
170	        updates: &[(String, Version)],
171	        permit: &ApplyPermit,
172	    ) -> Result<(), ManifestError>;
173	    /// The role this manifest's own content declares itself to play (see
174	    /// [`NpmRole`]). `None` for every ecosystem other than npm, and for an
175	    /// npm manifest that isn't a platform package. Overridden by
176	    /// `PackageJson`, whose implementation derives this from the document
177	    /// already parsed at `open()` time -- no second disk read required.
178	    fn npm_role(&self) -> Option<NpmRole> {
179	        None
180	    }
181	    /// Executable names this package builds; empty for a library-only package.
182	    fn bin_names(&self) -> Vec<String> {
183	        Vec::new()
184	    }
185	    /// The lib name of a napi-rs addon crate: a `cdylib` depending on `napi`.
186	    fn napi_lib_name(&self) -> Option<String> {
187	        None
188	    }
189	}
190	
191	/// Context passed to open() to supply workspace-wide inheritance facts.
192	pub struct OpenContext<'a> {
193	    pub workspace_root: &'a Path,
194	    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
195	    pub npm_workspace_kind: Option<WorkspaceKind>,
196	}
197	
198	impl<'a> OpenContext<'a> {
199	    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
200	    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
201	    /// the npm workspace kind. This is the single reusable constructor for
202	    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
203	    /// workspace kind" sequence that call sites previously reimplemented
204	    /// independently (audit pattern: duplication) -- see
205	    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
206	    /// `apply`, and `commands::version` modules.
207	    pub fn for_workspace_root(root: &'a Path) -> OpenContext<'a> {
208	        let cargo_workspace = if root.join("Cargo.toml").exists() {
209	            if let Ok(resolver) = WorkspaceCargoResolver::load(&root.join("Cargo.toml")) {
210	                resolver.inheritance().ok().map(Arc::new)
211	            } else {
212	                None
213	            }
214	        } else {
215	            None
216	        };
217	
218	        let npm_workspace_kind = detect_npm_workspace_kind(root).ok().flatten();
219	
220	        OpenContext {
221	            workspace_root: root,
222	            cargo_workspace,
223	            npm_workspace_kind,
224	        }
225	    }
226	}
227	
228	/// Test-observability counter: total number of times [`open`] has been
229	/// invoked. Production code never reads this; it exists so callers (in
