459	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
460	        let mut entries = Vec::new();
461	
462	        // 1. PEP 621 [project].dependencies (array of requirement strings)
463	        if let Some(deps) = self
464	            .document
465	            .get("project")
466	            .and_then(|p| p.get("dependencies"))
467	            .and_then(|d| d.as_array())
468	        {
469	            entries.extend(requirement_entries(
470	                deps,
471	                DepKind::Runtime,
472	                &DepContainer::ProjectDependencies,
473	            ));
474	        }
475	
476	        // 1b. PEP 621 [project.optional-dependencies]: extras ship in the published metadata, so a
477	        // pin there goes stale exactly like a runtime one.
478	        if let Some(extras) = self
479	            .document
480	            .get("project")
481	            .and_then(|p| p.get("optional-dependencies"))
482	            .and_then(|d| d.as_table_like())
483	        {
484	            for (extra, group) in extras.iter() {
485	                if let Some(requirements) = group.as_array() {
486	                    entries.extend(requirement_entries(
487	                        requirements,
488	                        DepKind::Optional,
489	                        &DepContainer::Extra(extra.to_string()),
490	                    ));
491	                }
492	            }
493	        }
494	
495	        // 2. Poetry [tool.poetry.dependencies]
496	        if let Some(table) = self
497	            .document
498	            .get("tool")
499	            .and_then(|t| t.get("poetry"))
500	            .and_then(|p| p.get("dependencies"))
501	            .and_then(|d| d.as_table_like())
502	        {
503	            for (name, item) in table.iter() {
504	                if name == "python" {
505	                    continue;
506	                }
507	                // `as_table_like()` covers both inline tables
508	                // (`foo = { version = "^1.2" }`) and dotted-table syntax
509	                // (`[tool.poetry.dependencies.foo]` / `version = "^1.2"`),
510	                // which parse to different `toml_edit::Item` variants but
511	                // must both be recognized -- previously only the inline-table
512	                // variant was handled, so a dotted-table Poetry dependency
513	                // silently vanished from the graph entirely.
514	                let raw_req = match item {
515	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
516	                    _ => item
517	                        .as_table_like()
518	                        .and_then(|t| t.get("version"))
519	                        .and_then(|v| v.as_str()),
520	                };
521	
522	                let spec = match raw_req {
523	                    Some(req_str) => {
524	                        // Poetry allows caret/tilde/wildcard syntax on top of
525	                        // PEP 440 (e.g. `^1.2`, `~1.2.3`, `1.*`), which
526	                        // `pep440_rs` cannot parse directly -- normalize it
527	                        // to an equivalent PEP 440 range first.
528	                        let normalized = normalize_poetry_version_spec(req_str);
529	                        match VersionReq::parse(&normalized, Ecosystem::Pypi) {
530	                            Ok(spec) => DepSpec::Range(spec, req_str.to_string()),
531	                            // Genuinely unrepresentable (syntax this
532	                            // normalizer doesn't cover) -- never silently
533	                            // drop the dependency; keep it visible in the
534	                            // graph as an opaque spec instead.
535	                            Err(_) => DepSpec::Opaque(req_str.to_string()),
536	                        }
537	                    }
538	                    // No `version` key at all -- a path/git/url dependency
539	                    // (e.g. `foo = { git = "...", tag = "v1.0" }`) or an
540	                    // unrecognized value shape. Still must not silently
541	                    // vanish from the graph.
542	                    None => {
543	                        DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string())
544	                    }
545	                };
546	
547	                entries.push(DependencyEntry {
548	                    name: name.to_string(),
549	                    package_name: name.to_string(),
550	                    inherited: false,
551	                    kind: DepKind::Runtime,
552	                    spec,
553	                    locator: DepLocator::python(DepContainer::PoetryDependencies, None),
554	                });
555	            }
556	        }
557	
558	        Box::new(entries.into_iter())
559	    }
