561	    fn update_dependency_spec(
562	        &mut self,
563	        name: &str,
564	        kind: DepKind,
565	        at: &DepLocator,
566	        new: DepSpec,
567	        _permit: &ApplyPermit,
568	    ) -> Result<(), ManifestError> {
569	        let new_spec_str = match new {
570	            DepSpec::Range(req, _) => req.render().to_string(),
571	            DepSpec::Exact(v) => format!("=={}", v.render()),
572	            _ => return Ok(()),
573	        };
574	        let not_found = || ManifestError::DependencyNotFound {
575	            path: self.path.clone(),
576	            name: name.to_string(),
577	            kind,
578	        };
579	
580	        let DepLocator::Python {
581	            container, position, ..
582	        } = at
583	        else {
584	            return Err(not_found());
585	        };
586	        match container {
587	            DepContainer::PoetryDependencies => {
588	                let table = self
589	                    .document
590	                    .get_mut("tool")
591	                    .and_then(|t| t.get_mut("poetry"))
592	                    .and_then(|p| p.get_mut("dependencies"))
593	                    .and_then(|d| d.as_table_like_mut())
594	                    .ok_or_else(not_found)?;
595	                let existing = table.get_mut(name).ok_or_else(not_found)?;
596	                match existing.as_table_like_mut() {
597	                    Some(fields) => {
598	                        fields.insert("version", value(new_spec_str));
599	                    }
600	                    None => {
601	                        table.insert(name, value(new_spec_str));
602	                    }
603	                }
604	            }
605	            container => {
606	                let position = position.ok_or_else(not_found)?;
607	                let requirements = match container {
608	                    DepContainer::ProjectDependencies => {
609	                        self.document.get_mut("project").and_then(|p| p.get_mut("dependencies"))
610	                    }
611	                    DepContainer::Extra(extra) => self
612	                        .document
613	                        .get_mut("project")
614	                        .and_then(|p| p.get_mut("optional-dependencies"))
615	                        .and_then(|d| d.get_mut(extra.as_str())),
616	                    _ => None,
617	                }
618	                .and_then(|item| item.as_array_mut())
619	                .ok_or_else(not_found)?;
620	                // The array may differ from the one the locator was read from: refuse to rewrite another dependency.
621	                let rewritten = requirements
622	                    .get(position)
623	                    .and_then(|item| item.as_str())
624	                    .and_then(|full_req| rewrite_requirement(full_req, name, &new_spec_str))
625	                    .ok_or_else(not_found)?;
626	                requirements.replace(position, rewritten);
627	            }
628	        }
629	
630	        Ok(())
631	    }
