659	    fn update_optional_dependencies(
660	        &mut self,
661	        updates: &[(String, Version)],
662	        _permit: &ApplyPermit,
663	    ) -> Result<(), ManifestError> {
664	        if updates.is_empty() {
665	            return Ok(());
666	        }
667	
668	        // [project.optional-dependencies] is a table of group_name → [PEP 508 strings].
669	        // Collect the table keys first to avoid borrow conflicts.
670	        let group_keys: Vec<String> = self
671	            .document
672	            .get("project")
673	            .and_then(|p| p.get("optional-dependencies"))
674	            .and_then(|od| od.as_table_like())
675	            .map(|t| t.iter().map(|(k, _)| k.to_string()).collect())
676	            .unwrap_or_default();
677	
678	        for group_key in &group_keys {
679	            let Some(arr) = self
680	                .document
681	                .get_mut("project")
682	                .and_then(|p| p.get_mut("optional-dependencies"))
683	                .and_then(|od| od.get_mut(group_key.as_str()))
684	                .and_then(|g| g.as_array_mut())
685	            else {
686	                continue;
687	            };
688	
689	            for idx in 0..arr.len() {
690	                let Some(full_req) = arr.get(idx).and_then(|item| item.as_str()) else {
691	                    continue;
692	                };
693	                let Some(req) = Requirement::parse(full_req) else {
694	                    continue;
695	                };
696	
697	                if let Some((_dep_name, new_ver)) = updates.iter().find(|(dep_name, _)| {
698	                    normalize_pypi_package_name(dep_name) == normalize_pypi_package_name(&req.name)
699	                }) {
700	                    let new_req = Requirement {
701	                        name: req.name.clone(),
702	                        extras: req.extras.clone(),
703	                        spec: Some(format!(">={}", new_ver.render())),
704	                        marker: req.marker.clone(),
705	                    };
706	                    arr.replace(idx, new_req.render());
707	                }
708	            }
709	        }
710	
711	        Ok(())
712	    }
713	}
