715	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
716	///
717	/// The following single-clause and two-clause forms are recognized and rewritten:
718	///
719	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
720	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
721	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
722	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
723	///   where `NEXT_MAJOR` equals `target.major() + 1`.
724	///
725	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
726	/// in full rather than truncated to `major.minor.patch`, the same precision
727	/// rule `cargo::round_trip` applies for SemVer.
728	///
729	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
730	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
731	/// and wildcard `*`. Callers must leave the original constraint unchanged
732	/// when `None` is returned.
733	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
734	    // Only Range specs are produced by iter_dependencies for Python.
735	    let original = match spec {
736	        DepSpec::Range(_, raw) => raw.as_str(),
737	        _ => return None,
738	    };
739	
740	    let trimmed = original.trim();
741	
742	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
743	    if trimmed.contains(',') {
744	        return rewrite_range(trimmed, target);
745	    }
746	
747	    // Single-clause forms matched by their PEP 508 operator prefix.
748	    if trimmed.starts_with("==") {
749	        return rewrite_single(trimmed, "==", target);
750	    }
751	    if trimmed.starts_with("~=") {
752	        return rewrite_single(trimmed, "~=", target);
753	    }
754	    if trimmed.starts_with(">=") {
755	        return rewrite_single(trimmed, ">=", target);
756	    }
757	
758	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
759	    None
760	}
761	
762	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
763	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
764	    // Validate that the original clause parses correctly (guards against
765	    // unknown version syntax that happens to start with a known prefix).
766	    let _rest = original.strip_prefix(op)?;
767	    let rendered = format!("{op}{}", render_target(op, target)?);
768	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
769	    Some(DepSpec::Range(req, rendered))
770	}
771	
772	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
773	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
774	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
775	/// the version with its local segment stripped for every other operator, since PEP 440
776	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
777	fn render_target(op: &str, target: &Version) -> Option<String> {
778	    if target.is_prerelease() {
779	        let full = target.render();
780	        if op == "==" || op == "!=" {
781	            return Some(full.to_string());
782	        }
783	        return Some(full.split('+').next().unwrap_or(full).to_string());
784	    }
785	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
786	}
787	
788	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
789	///
790	/// Returns `None` for anything that does not match exactly this two-clause
791	/// lower/upper pattern, including specs with three or more clauses (e.g.
792	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
793	/// a semantically incorrect constraint.
794	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
795	    // Reject any spec with more than two comma-separated clauses: rewriting
796	    // would silently discard the extra clauses, changing the semantics.
797	    if original.split(',').count() != 2 {
798	        return None;
799	    }
800	
801	    let mut parts = original.splitn(2, ',');
802	    let lower = parts.next()?.trim();
803	    let upper = parts.next()?.trim();
804	
805	    // Lower clause must be `>=…`.
806	    if !lower.starts_with(">=") {
807	        return None;
808	    }
809	    // Upper clause must be strictly `<…` (not `<=`).
810	    if !upper.starts_with('<') || upper.starts_with("<=") {
811	        return None;
812	    }
813	
814	    let next_major = target.major()? + 1;
815	    let rendered = format!(">={},<{next_major}", render_target(">=", target)?);
816	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
817	    Some(DepSpec::Range(req, rendered))
818	}
819	
820	/// Every requirement string of one array as a dependency edge addressed by its index in `container`.
821	fn requirement_entries<'a>(
822	    requirements: &'a toml_edit::Array,
823	    kind: DepKind,
824	    container: &'a DepContainer,
825	) -> impl Iterator<Item = DependencyEntry> + 'a {
826	    requirements.iter().enumerate().filter_map(move |(position, item)| {
827	        let locator = DepLocator::python(container.clone(), Some(position));
828	        pep508_entry(item.as_str()?, kind, locator)
829	    })
830	}
831	
832	/// One PEP 508 requirement string as a dependency edge, or `None` when it names no package.
833	fn pep508_entry(full_req_str: &str, kind: DepKind, locator: DepLocator) -> Option<DependencyEntry> {
834	    // `Requirement::parse` couldn't extract even a package name (an empty string or a
835	    // marker-only fragment): there is no name to key an entry on.
836	    let req = Requirement::parse(full_req_str)?;
837	    let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
838	    let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
839	    let spec = match VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
840	        Ok(spec) => DepSpec::Range(spec, req_str),
841	        // A PEP 508 clause `pep440_rs` can't parse (exotic or malformed syntax): keep the
842	        // dependency visible in the graph rather than silently dropping it.
843	        Err(_) => DepSpec::Opaque(req_str),
844	    };
845	    Some(DependencyEntry {
846	        name: req.name.clone(),
847	        package_name: req.name.clone(),
848	        inherited: false,
849	        kind,
850	        spec,
851	        locator,
852	    })
853	}
854	
855	/// The requirement string with `name`'s constraint replaced by `new_spec_str`, or `None` when
856	/// the requirement names another package.
857	fn rewrite_requirement(full_req: &str, name: &str, new_spec_str: &str) -> Option<String> {
858	    let req = Requirement::parse(full_req)?;
859	    if normalize_pypi_package_name(&req.name) != normalize_pypi_package_name(name) {
860	        return None;
861	    }
862	    let formatted_spec = if new_spec_str.starts_with(['<', '>', '=', '!', '~']) {
863	        new_spec_str.to_string()
864	    } else {
865	        format!(">={new_spec_str}")
866	    };
867	    Some(
868	        Requirement {
869	            name: req.name.clone(),
870	            extras: req.extras.clone(),
871	            spec: Some(formatted_spec),
872	            marker: req.marker.clone(),
873	        }
874	        .render(),
875	    )
876	}
