5	use callisto_manifests::{open, Manifest, OpenContext, WorkspaceCargoResolver};
6	use callisto_model::{
7	    ApplyPermit, CommandError, CommandRunner, DepKind, Ecosystem, LockfileRefreshResult, ManifestFormat, ManifestRole,
8	    Version,
