16	/// Options governing how a version plan is applied to the workspace.
17	#[derive(Clone, Debug, Default)]
18	pub struct ApplyOptions {
19	    /// When true, regenerate each affected ecosystem's lockfile after applying, in transient mode too.
20	    pub refresh_lockfiles: bool,
21	    /// When true (snapshot mode), manifest mutations are written to disk
22	    /// but changelog prepends (step 7), changeset deletions (step 8), and
23	    /// git staging (step 11) are suppressed.
24	    pub transient: bool,
25	}
