27	/// The result of a successful [`apply_version_plan`] call, describing which paths were written and staged.
28	#[derive(Clone, Debug, Default)]
29	pub struct ApplyOutcome {
30	    /// One entry per lockfile refreshed by this apply; `None` when refresh was skipped or nothing ran.
31	    pub lockfile_refresh_results: Option<Vec<LockfileRefreshResult>>,
32	    /// Paths written and staged via `git add`, relative to the workspace root.
33	    pub staged: Vec<PathBuf>,
34	}
35	
36	#[derive(Debug, Default)]
37	pub(crate) struct ManifestWriteGroup {
38	    pub(crate) bump: Option<(usize, callisto_model::Version)>,
39	    pub(crate) rewrite_indices: Vec<usize>,
40	}
41	
42	#[derive(Debug, Default)]
43	pub(crate) struct ManifestWriteClassification {
44	    pub(crate) batched: BTreeMap<PathBuf, ManifestWriteGroup>,
45	    /// Root-manifest paths written exclusively through
46	    /// `WorkspaceCargoResolver` (`CargoWorkspacePackage`/
47	    /// `CargoWorkspaceDependency` targets), with no competing write to the
48	    /// same physical file through the `Manifest` trait's `open()` path.
49	    /// Consumed the same way as `batched`, but via `WorkspaceCargoResolver`
50	    /// instead of `open()` -- see `apply_version_plan`'s resolver-batched
51	    /// loop.
52	    pub(crate) resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup>,
53	    /// Paths that receive writes through BOTH the `Manifest` trait and
54	    /// `WorkspaceCargoResolver` -- the mixed-routing data-loss/ordering
55	    /// hazard.
56	    /// Never batched on either side; each write is applied individually,
57	    /// strictly in plan order, exactly as before this change.
58	    pub(crate) excluded: BTreeSet<PathBuf>,
59	}
60	
61	pub(crate) fn classify_manifest_writes(plan: &VersionPlan) -> ManifestWriteClassification {
62	    let mut resolver_by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
63	    for (idx, bump) in plan.bumps.iter().enumerate() {
64	        for write in &bump.writes {
65	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
66	                resolver_by_path.entry(root_manifest.clone()).or_default().bump = Some((idx, bump.to.clone()));
67	            }
68	        }
69	    }
70	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
71	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
72	            resolver_by_path
73	                .entry(root_manifest.clone())
74	                .or_default()
75	                .rewrite_indices
76	                .push(idx);
77	        }
78	    }
79	
80	    let mut by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
81	    for (idx, bump) in plan.bumps.iter().enumerate() {
82	        for write in &bump.writes {
83	            if let VersionWriteTarget::Manifest(p) = write {
84	                by_path.entry(p.clone()).or_default().bump = Some((idx, bump.to.clone()));
85	            }
86	        }
87	    }
88	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
89	        if let DepWriteTarget::Manifest(p) = &rewrite.key.target {
90	            by_path.entry(p.clone()).or_default().rewrite_indices.push(idx);
91	        }
92	    }
93	
94	    let mut batched = BTreeMap::new();
95	    let mut excluded = BTreeSet::new();
96	    for (path, group) in by_path {
97	        if resolver_by_path.contains_key(&path) {
98	            excluded.insert(path);
99	        } else {
100	            batched.insert(path, group);
101	        }
102	    }
103	
104	    // Every path in `resolver_by_path` that isn't also mixed-routed
105	    // (present in `excluded`) is safe to batch into one
106	    // load/mutate*/persist cycle -- it's written exclusively through
107	    // WorkspaceCargoResolver, never through the Manifest trait.
108	    let resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup> = resolver_by_path
109	        .into_iter()
110	        .filter(|(path, _)| !excluded.contains(path))
111	        .collect();
112	
113	    ManifestWriteClassification {
114	        batched,
115	        resolver_batched,
116	        excluded,
117	    }
118	}
