120	/// Writes `plan` to disk and stages the touched paths in git.
121	///
122	/// Every side effect here is unconditional -- whether to apply at all is
123	/// the caller's decision, which is why an [`ApplyPermit`] is required
124	/// rather than a `dry_run` bool: a bool carries no guarantee any caller
125	/// actually consulted it. A dry-run caller can't obtain a permit and
126	/// simply doesn't call this function; it reports `plan` instead.
127	///
128	/// # Errors
129	///
130	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
131	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
132	/// - I/O errors writing changelog sections or `pre.json`.
133	pub fn apply_version_plan<R: CommandRunner>(
134	    root: &Path,
135	    plan: &VersionPlan,
136	    runner: &R,
137	    opts: &ApplyOptions,
138	    permit: &ApplyPermit,
139	) -> Result<ApplyOutcome, GraphError> {
140	    let mut outcome = ApplyOutcome::default();
141	    let mut modified_paths = Vec::new();
142	    let mut deferred_deletions = Vec::new();
143	
144	    let ctx = OpenContext::for_workspace_root(root);
145	    let classification = classify_manifest_writes(plan);
146	
147	    for step in write_steps(plan, &classification) {
148	        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
149	    }
150	
151	    if !opts.transient {
152	        for cl in &plan.changelog_writes {
153	            let rendered = crate::changelog::render_section(&cl.input)?;
154	            crate::changelog::prepend(
155	                root,
156	                &cl.changelog_path,
157	                &cl.input.package.display_name(),
158	                &rendered,
159	                permit,
160	            )?;
161	            modified_paths.push(cl.changelog_path.clone());
162	        }
163	
164	        for cs_path in &plan.consumed_changesets {
165	            deferred_deletions.push(cs_path.clone());
166	        }
167	
168	        if let Some(ref pre_state) = plan.pre_state_update {
169	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
170	            let rel_pre_path = plan.pre_json_path.clone();
171	            let pre_path = root.join(&rel_pre_path);
172	            let text = match &plan.pre_json_original_text {
173	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
174	                None => callisto_model::format::write_pre_json(pre_state),
175	            };
176	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
177	                path: rel_pre_path.clone(),
178	                message: e.to_string(),
179	            })?;
180	            modified_paths.push(rel_pre_path);
181	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
182	            deferred_deletions.push(rel_pre_path.clone());
183	        }
184	    }
185	
186	    let active_ecosystems = active_ecosystems(plan);
187	
188	    // Must run before the git-staging loop below, so refreshed lockfiles are on disk to be staged.
189	    if opts.refresh_lockfiles {
190	        let refresh_results = refresh_lockfiles(runner, root, &active_ecosystems)?;
191	        if !refresh_results.is_empty() {
192	            outcome.lockfile_refresh_results = Some(refresh_results);
193	        }
194	    }
195	
196	    // Map each well-known lockfile to its ecosystem, then include the file
197	    // only when that ecosystem is active and the file exists on disk.
198	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
199	        ("Cargo.lock", Ecosystem::Cargo),
200	        ("package-lock.json", Ecosystem::Npm),
201	        ("pnpm-lock.yaml", Ecosystem::Npm),
202	        ("yarn.lock", Ecosystem::Npm),
203	        ("bun.lock", Ecosystem::Npm),
204	        ("bun.lockb", Ecosystem::Npm),
205	        ("uv.lock", Ecosystem::Pypi),
206	        ("poetry.lock", Ecosystem::Pypi),
207	        ("pdm.lock", Ecosystem::Pypi),
208	        ("Pipfile.lock", Ecosystem::Pypi),
209	    ];
210	    for (lockfile, ecosystem) in lockfile_ecosystems {
211	        if !active_ecosystems.contains(ecosystem) {
212	            continue;
213	        }
214	        let p = PathBuf::from(lockfile);
215	        if root.join(&p).exists() && !modified_paths.contains(&p) {
216	            modified_paths.push(p);
217	        }
218	    }
219	
220	    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
221	        // Stage all written release state before consuming its inputs. If a refresh or add fails,
222	        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
223	        // still identifies the interrupted run.
224	        let (existing, deleted): (Vec<_>, Vec<_>) = modified_paths.iter().partition(|p| root.join(p).exists());
225	
226	        if !existing.is_empty() {
227	            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
228	        }
229	
230	        if !deleted.is_empty() {
231	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
232	        }
233	
234	        if !deferred_deletions.is_empty() {
235	            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
236	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;
237	
238	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
239	            for path in &deferred_deletions {
240	                let full = root.join(path);
241	                if full.exists() {
242	                    fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
243	                        path: path.clone(),
244	                        message: e.to_string(),
245	                    })?;
246	                }
247	            }
248	            modified_paths.extend(deferred_deletions.iter().cloned());
249	        }
250	
251	        outcome.staged = modified_paths;
252	    }
253	
254	    Ok(outcome)
255	}
