257	/// One physical write of a version plan, in the order it must happen.
258	enum WriteStep<'p> {
259	    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
260	    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
261	    Manifest {
262	        path: &'p PathBuf,
263	        group: &'p ManifestWriteGroup,
264	    },
265	    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
266	    /// writes carry no idempotency precondition.
267	    WorkspaceRoot {
268	        root_manifest: &'p PathBuf,
269	        group: &'p ManifestWriteGroup,
270	    },
271	    /// Mixed-routing manifests (written through both routes) are never batched: each write is
272	    /// its own load/persist, strictly in plan order.
273	    MixedManifestVersion {
274	        path: &'p PathBuf,
275	        bump: &'p PlannedBump,
276	    },
277	    MixedWorkspaceVersion {
278	        root_manifest: &'p PathBuf,
279	        to: &'p Version,
280	    },
281	    MixedManifestRewrite {
282	        path: &'p PathBuf,
283	        rewrite: &'p SpecRewrite,
284	    },
285	    MixedWorkspaceRewrite {
286	        root_manifest: &'p PathBuf,
287	        rewrite: &'p SpecRewrite,
288	    },
289	    PlatformVersion(&'p PlatformWrite),
290	    OptionalDependencies(&'p OptionalDepUpdate),
291	}
292	
293	/// Orders every manifest write once, so execution is a single `match` and the per-file order
294	/// (bump, then rewrites, then one persist) is data rather than control flow.
295	fn write_steps<'p>(plan: &'p VersionPlan, classification: &'p ManifestWriteClassification) -> Vec<WriteStep<'p>> {
296	    let mut steps = Vec::new();
297	    for (path, group) in &classification.batched {
298	        steps.push(WriteStep::Manifest { path, group });
299	    }
300	    for (root_manifest, group) in &classification.resolver_batched {
301	        steps.push(WriteStep::WorkspaceRoot { root_manifest, group });
302	    }
303	    for bump in &plan.bumps {
304	        for write in &bump.writes {
305	            match write {
306	                VersionWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
307	                    steps.push(WriteStep::MixedManifestVersion { path, bump });
308	                }
309	                VersionWriteTarget::CargoWorkspacePackage { root_manifest }
310	                    if !classification.resolver_batched.contains_key(root_manifest) =>
311	                {
312	                    steps.push(WriteStep::MixedWorkspaceVersion {
313	                        root_manifest,
314	                        to: &bump.to,
315	                    });
316	                }
317	                _ => {}
318	            }
319	        }
320	    }
321	    for rewrite in &plan.rewrites {
322	        match &rewrite.key.target {
323	            DepWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
324	                steps.push(WriteStep::MixedManifestRewrite { path, rewrite });
325	            }
326	            DepWriteTarget::CargoWorkspaceDependency { root_manifest }
327	                if !classification.resolver_batched.contains_key(root_manifest) =>
328	            {
329	                steps.push(WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite });
330	            }
331	            _ => {}
332	        }
333	    }
334	    steps.extend(plan.platform_writes.iter().map(WriteStep::PlatformVersion));
335	    steps.extend(plan.optional_dep_updates.iter().map(WriteStep::OptionalDependencies));
336	    steps
337	}
338	
339	/// Performs one step and returns the path to stage.
340	fn apply_write_step(
341	    step: &WriteStep<'_>,
342	    plan: &VersionPlan,
343	    root: &Path,
344	    ctx: &OpenContext<'_>,
345	    permit: &ApplyPermit,
346	) -> Result<PathBuf, GraphError> {
347	    match step {
348	        WriteStep::Manifest { path, group } => {
349	            let mut handle = open_canonical(path, ctx)?;
350	            let mut mutated = false;
351	            if let Some((bump_idx, target_version)) = &group.bump {
352	                let bump = &plan.bumps[*bump_idx];
353	                mutated = write_version_guarded(handle.as_mut(), path, &bump.from, target_version, permit)?;
354	            }
355	            for rewrite_idx in &group.rewrite_indices {
356	                rewrite_dependency(handle.as_mut(), &plan.rewrites[*rewrite_idx], permit)?;
357	                mutated = true;
358	            }
359	            if mutated {
360	                handle.persist(permit)?;
361	            }
362	            Ok((*path).clone())
363	        }
364	        WriteStep::WorkspaceRoot { root_manifest, group } => {
365	            let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
366	            let mut mutated = false;
367	            if let Some((_, target_version)) = &group.bump {
368	                ws_res.write_version(target_version, permit)?;
369	                mutated = true;
370	            }
371	            for rewrite_idx in &group.rewrite_indices {
372	                let rewrite = &plan.rewrites[*rewrite_idx];
373	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
374	                mutated = true;
375	            }
376	            if mutated {
377	                ws_res.persist(permit)?;
378	            }
379	            Ok((*root_manifest).clone())
380	        }
381	        WriteStep::MixedManifestVersion { path, bump } => {
382	            let mut handle = open_canonical(path, ctx)?;
383	            if write_version_guarded(handle.as_mut(), path, &bump.from, &bump.to, permit)? {
384	                handle.persist(permit)?;
385	            }
386	            Ok((*path).clone())
387	        }
388	        WriteStep::MixedWorkspaceVersion { root_manifest, to } => {
389	            let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
390	            ws_res.write_version(to, permit)?;
391	            ws_res.persist(permit)?;
392	            Ok((*root_manifest).clone())
393	        }
394	        WriteStep::MixedManifestRewrite { path, rewrite } => {
395	            let mut handle = open_canonical(path, ctx)?;
396	            rewrite_dependency(handle.as_mut(), rewrite, permit)?;
397	            handle.persist(permit)?;
398	            Ok((*path).clone())
399	        }
400	        WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite } => {
401	            let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
402	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
403	            ws_res.persist(permit)?;
404	            Ok((*root_manifest).clone())
405	        }
406	        WriteStep::PlatformVersion(write) => {
407	            let mut handle = open_canonical(&write.manifest, ctx)?;
408	            if write_version_guarded(handle.as_mut(), &write.manifest, &write.from, &write.version, permit)? {
409	                handle.persist(permit)?;
410	            }
411	            Ok(write.manifest.clone())
412	        }
413	        WriteStep::OptionalDependencies(update) => {
414	            let mut handle = open_canonical(&update.manifest, ctx)?;
415	            handle.update_optional_dependencies(&update.updates, permit)?;
416	            handle.persist(permit)?;
417	            Ok(update.manifest.clone())
418	        }
419	    }
420	}
421	
422	fn open_canonical(path: &Path, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, GraphError> {
423	    let fmt = callisto_model::ManifestFormat::from_path(path)?;
424	    let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
425	    Ok(open(&decl, ctx)?)
426	}
427	
428	/// Writes `to` unless the manifest already has it, and refuses any version other than `from`:
429	/// the precondition that makes re-running an interrupted apply safe. Returns whether it wrote.
430	fn write_version_guarded(
431	    handle: &mut dyn Manifest,
432	    path: &Path,
433	    from: &Version,
434	    to: &Version,
435	    permit: &ApplyPermit,
436	) -> Result<bool, GraphError> {
437	    let current = handle.current_version()?;
438	    if current == *to {
439	        return Ok(false);
440	    }
441	    if current != *from {
442	        return Err(GraphError::UnexpectedManifestVersion {
443	            path: path.to_path_buf(),
444	            expected_from: from.clone(),
445	            expected_to: to.clone(),
446	            found: current,
447	        });
448	    }
449	    handle.write_version(to, permit)?;
450	    Ok(true)
451	}
452	
453	fn rewrite_dependency(
454	    handle: &mut dyn Manifest,
455	    rewrite: &SpecRewrite,
456	    permit: &ApplyPermit,
457	) -> Result<(), GraphError> {
458	    handle.update_dependency_spec(
459	        &rewrite.key.name,
460	        rewrite.key.kind.unwrap_or(DepKind::Runtime),
461	        &rewrite.key.locator,
462	        rewrite.to.clone(),
463	        permit,
464	    )?;
465	    Ok(())
466	}
467	
468	/// The ecosystems a plan touches, so only their lockfiles are refreshed and staged. Staging
469	/// the lockfile of an untouched ecosystem could sweep up unrelated user changes.
470	fn active_ecosystems(plan: &VersionPlan) -> HashSet<Ecosystem> {
471	    let of_manifest = |path: &Path| ManifestFormat::from_path(path).ok().map(|fmt| fmt.ecosystem());
472	    let mut active = HashSet::new();
473	    for bump in &plan.bumps {
474	        active.extend(bump.package.ecosystem());
475	        for write in &bump.writes {
476	            active.extend(match write {
477	                VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
478	                VersionWriteTarget::Manifest(path) => of_manifest(path),
479	            });
480	        }
481	    }
482	    for rewrite in &plan.rewrites {
483	        active.extend(match &rewrite.key.target {
484	            DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
485	            DepWriteTarget::Manifest(path) => of_manifest(path),
486	        });
487	    }
488	    active.extend(
489	        plan.platform_writes
490	            .iter()
491	            .filter_map(|write| of_manifest(&write.manifest)),
492	    );
493	    active.extend(
494	        plan.optional_dep_updates
495	            .iter()
496	            .filter_map(|update| of_manifest(&update.manifest)),
497	    );
498	    active
499	}
500	
501	/// Runs `git <prefix> <paths...>` in `root`, mapping a non-zero exit to `GraphError::Command`.
502	fn run_git_on_paths<R: CommandRunner>(
503	    runner: &R,
504	    root: &Path,
505	    prefix: &[&str],
506	    paths: &[&PathBuf],
507	) -> Result<(), GraphError> {
508	    let rendered: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
509	    let mut args: Vec<&str> = prefix.to_vec();
510	    args.extend(rendered.iter().map(String::as_str));
511	    let output = runner.run("git", &args, root)?;
512	    if !output.success() {
513	        return Err(GraphError::Command(CommandError::Failed {
514	            program: "git".to_string(),
515	            exit_code: output.exit_code,
516	            stderr: output.redacted_stderr(),
517	        }));
518	    }
519	    Ok(())
520	}
521	
522	/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
523	/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
524	fn refresh_lockfiles<R: CommandRunner>(
525	    runner: &R,
526	    root: &Path,
527	    active_ecosystems: &HashSet<Ecosystem>,
528	) -> Result<Vec<LockfileRefreshResult>, GraphError> {
529	    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
530	
531	    if active_ecosystems.contains(&Ecosystem::Cargo) {
532	        refresh_results.push(run_lockfile_refresh(
533	            runner,
534	            root,
535	            "Cargo.lock",
536	            "cargo",
537	            &["update", "--workspace"],
538	        )?);
539	    }
540	
541	    if active_ecosystems.contains(&Ecosystem::Pypi) {
542	        if root.join("uv.lock").exists() {
543	            refresh_results.push(run_lockfile_refresh(runner, root, "uv.lock", "uv", &["lock"])?);
544	        } else if root.join("poetry.lock").exists() {
545	            refresh_results.push(run_lockfile_refresh(
546	                runner,
547	                root,
548	                "poetry.lock",
549	                "poetry",
550	                &["lock", "--no-update"],
551	            )?);
552	        } else if root.join("pdm.lock").exists() {
553	            refresh_results.push(run_lockfile_refresh(
554	                runner,
555	                root,
556	                "pdm.lock",
557	                "pdm",
558	                &["lock", "--update-reuse"],
559	            )?);
560	        }
561	    }
562	
563	    if active_ecosystems.contains(&Ecosystem::Npm) {
564	        if root.join("package-lock.json").exists() {
565	            refresh_results.push(run_lockfile_refresh(
566	                runner,
567	                root,
568	                "package-lock.json",
569	                "npm",
570	                &["install", "--package-lock-only", "--ignore-scripts"],
571	            )?);
572	        }
573	        if root.join("pnpm-lock.yaml").exists() {
574	            refresh_results.push(run_lockfile_refresh(
575	                runner,
576	                root,
577	                "pnpm-lock.yaml",
578	                "pnpm",
579	                &["install", "--lockfile-only"],
580	            )?);
581	        }
582	        if root.join("yarn.lock").exists() {
583	            refresh_results.push(run_lockfile_refresh(
584	                runner,
585	                root,
586	                "yarn.lock",
587	                "yarn",
588	                &["install", "--mode", "update-lockfile"],
589	            )?);
590	        }
591	        if root.join("bun.lock").exists() {
592	            refresh_results.push(run_lockfile_refresh(
593	                runner,
594	                root,
595	                "bun.lock",
596	                "bun",
597	                &["install", "--lockfile-only"],
598	            )?);
599	        } else if root.join("bun.lockb").exists() {
600	            refresh_results.push(run_lockfile_refresh(
601	                runner,
602	                root,
603	                "bun.lockb",
604	                "bun",
605	                &["install", "--lockfile-only"],
606	            )?);
607	        }
608	    }
609	
610	    Ok(refresh_results)
611	}
612	
613	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
614	fn run_lockfile_refresh<R: CommandRunner>(
615	    runner: &R,
616	    root: &Path,
617	    filename: &str,
618	    program: &str,
619	    args: &[&str],
620	) -> Result<LockfileRefreshResult, GraphError> {
621	    let refresh_command = format!("{program} {}", args.join(" "));
622	    let out = runner.run(program, args, root)?;
623	    if !out.success() {
624	        return Err(GraphError::LockfileRefreshFailed {
625	            filename: PathBuf::from(filename),
626	            refresh_command,
627	            exit_code: out.exit_code,
628	            stderr: out.redacted_stderr(),
629	        });
630	    }
631	    Ok(LockfileRefreshResult {
632	        filename: PathBuf::from(filename),
633	        refresh_command,
634	        success: true,
635	        exit_code: out.exit_code,
636	    })
637	}
