59	/// One `.changeset/*.md` file that failed `parse_changeset`, kept alongside its (workspace-root-
60	/// relative) path so a caller that must survive a malformed changeset -- `status` -- can report
61	/// it as a diagnostic instead of aborting.
62	#[derive(Clone, Debug, PartialEq, Eq)]
63	pub struct ChangesetLoadFailure {
64	    pub path: PathBuf,
65	    pub source: callisto_model::format::ParseError,
66	}
67	
68	/// Loads and parses every `.changeset/*.md` file, splitting successes from parse failures
69	/// rather than aborting on the first one -- `status` must report every unparseable changeset,
70	/// not just the first. [`load_changesets`] collapses this to the first failure for callers
71	/// (`aggregate`/`version`) that must hard-fail instead.
72	pub fn load_changesets_permissive(
73	    root: &Path,
74	    cfg: &ResolvedConfig,
75	) -> Result<(Vec<LoadedChangeset>, Vec<ChangesetLoadFailure>), GraphError> {
76	    let dir = root.join(&cfg.changesets_dir);
77	    if !dir.exists() {
78	        return Ok((Vec::new(), Vec::new()));
79	    }
80	
81	    let entries = fs::read_dir(&dir).map_err(|e| callisto_model::ManifestError::Read {
82	        path: dir.clone(),
83	        message: e.to_string(),
84	    })?;
85	
86	    let mut files = Vec::new();
87	    for entry in entries.flatten() {
88	        let path = entry.path();
89	        if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("md") {
90	            if let Some(file_name) = path.file_name().and_then(|s| s.to_str()) {
91	                if file_name != "README.md" && file_name != "config.json" && file_name != "pre.json" {
92	                    files.push(path);
93	                }
94	            }
95	        }
96	    }
97	
98	    files.sort();
99	
100	    let mut loaded = Vec::new();
101	    let mut failures = Vec::new();
102	    for path in files {
103	        let content = fs::read_to_string(&path).map_err(|e| callisto_model::ManifestError::Read {
104	            path: path.clone(),
105	            message: e.to_string(),
106	        })?;
107	        let rel_path = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
108	        match parse_changeset(&content) {
109	            Ok(changeset) => {
110	                let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string();
111	                loaded.push(LoadedChangeset {
112	                    path: rel_path,
113	                    id: stem,
114	                    changeset,
115	                });
116	            }
117	            Err(source) => failures.push(ChangesetLoadFailure { path: rel_path, source }),
118	        }
119	    }
120	
121	    Ok((loaded, failures))
122	}
123	
124	pub fn load_changesets(root: &Path, cfg: &ResolvedConfig) -> Result<Vec<LoadedChangeset>, GraphError> {
125	    let (loaded, mut failures) = load_changesets_permissive(root, cfg)?;
126	    if !failures.is_empty() {
127	        let failure = failures.remove(0);
128	        return Err(GraphError::ParseChangeset {
129	            path: failure.path,
130	            source: failure.source,
131	        });
132	    }
133	    Ok(loaded)
134	}
