136	pub fn apply_pre_major(
137	    inferred: Severity,
138	    policy: PreMajorInferencePolicy,
139	    current: &Version,
140	    has_prior_release: bool,
141	) -> (Severity, bool) {
142	    if policy == PreMajorInferencePolicy::Off {
143	        return (inferred, false);
144	    }
145	    if current.major() != Some(0) || current.minor() == Some(0) || !has_prior_release {
146	        return (inferred, false);
147	    }
148	
149	    match (policy, inferred) {
150	        (PreMajorInferencePolicy::Conservative | PreMajorInferencePolicy::ConservativeFeat, Severity::Major) => {
151	            (Severity::Minor, true)
152	        }
153	        (PreMajorInferencePolicy::ConservativeFeat, Severity::Minor) => (Severity::Patch, true),
154	        (_, s) => (s, false),
155	    }
156	}
