189	#[allow(clippy::too_many_arguments)]
190	pub fn aggregate<D, I>(
191	    graph: &D,
192	    identity: &IdentityIndex,
193	    config: &ResolvedConfig,
194	    git: &GitAccess<'_>,
195	    tags: &TagIndex,
196	    base_versions: &BTreeMap<PackageId, Version>,
197	    pre: Option<&callisto_model::format::PreState>,
198	    inference: &I,
199	) -> Result<Aggregation, GraphError>
200	where
201	    D: DependencyResolver,
202	    I: SeverityInference,
203	{
204	    let loaded = load_changesets(&config.root, config)?;
205	    let mut agg = Aggregation::default();
206	
207	    for pkg in graph.packages() {
208	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
209	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
210	        let last_tag = tags.last_tag(&pkg.id);
211	        let cur_ver = last_tag
212	            .map(|t| t.version.clone())
213	            .or_else(|| base_versions.get(&pkg.id).cloned())
214	            .ok_or_else(|| {
215	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
216	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
217	                    field: "version",
218	                })
219	            })?;
220	
221	        let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
222	        let policy = resolve_package_config(&pkg.id, &package_ecosystems, config)?
223	            .and_then(|pcfg| pcfg.pre_major_inference)
224	            .unwrap_or(PreMajorInferencePolicy::Off);
225	
226	        // release_trigger: Changeset packages take severity from pending changesets only --
227	        // commit inference must not run for them, so neither does resolving its window.
228	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
229	            let window = crate::infer::InferenceWindowSpec {
230	                pathspecs: &pathspecs,
231	                since: last_tag.and_then(|t| resolve_since(git, t.name.as_str())),
232	                current_version: &cur_ver,
233	                has_prior_release: last_tag.is_some(),
234	                policy,
235	            };
236	            inference.infer(pkg, git, window)
237	        } else {
238	            Ok(None)
239	        };
240	
241	        match inferred {
242	            Ok(Some(outcome)) => {
243	                if outcome.severity > cur_sev {
244	                    agg.severities.insert(pkg.id.clone(), outcome.severity);
245	                    agg.reasons.insert(
246	                        pkg.id.clone(),
247	                        BumpReason::Inference {
248	                            commits: outcome.commit_count,
249	                            remapped: outcome.remapped,
250	                        },
251	                    );
252	                    agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
253	                    agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
254	                }
255	            }
256	            Ok(None) => {}
257	            Err(e) => {
258	                agg.diagnostics.push(Diagnostic {
259	                    code: callisto_model::DiagnosticCode::PreMajorInferenceInert,
260	                    severity: callisto_model::DiagnosticSeverity::Warning,
261	                    message: format!("Commit inference failed for package `{}`: {e}", pkg.id.display_name()),
262	                    package: Some(pkg.id.clone()),
263	                    path: None,
264	                    governed_by: None,
265	                    escalated_by: None,
266	                });
267	            }
268	        }
269	    }
270	
271	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
272	    // they remain on disk so they can be re-applied when the cycle exits.
273	    let is_pre_mode = pre
274	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
275	        .unwrap_or(false);
276	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
277	    let already_recorded: std::collections::HashSet<&str> = pre
278	        .map(|s| s.changesets.iter().map(String::as_str).collect())
279	        .unwrap_or_default();
280	
281	    for cs in loaded {
282	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
283	        // Defer adding to `consumed` until after we confirm at least one entry
284	        // resolved to a real workspace package. A changeset where every entry
285	        // names a removed package must NOT be consumed (which would delete it
286	        // on disk); instead, an UnknownPackage diagnostic is emitted and the
287	        // file is left for the user to clean up manually.
288	        //
289	        // A changeset with a MIX of resolved and unresolved entries must also
290	        // stay unconsumed: consuming it would delete the file (or, in pre
291	        // mode, mark it as already-applied) and permanently lose the
292	        // unresolved entry's bump once that entry's target reappears.
293	        let mut matched_any = false;
294	        let mut has_unresolved = false;
295	        for entry in cs.changeset.entries {
296	            let id = match PackageId::parse(&entry.name) {
297	                Ok(id) => id,
298	                Err(_) => {
299	                    has_unresolved = true;
300	                    agg.diagnostics.push(Diagnostic {
301	                        code: callisto_model::DiagnosticCode::UnknownPackage,
302	                        severity: callisto_model::DiagnosticSeverity::Warning,
303	                        message: format!(
304	                            "Changeset `{}` contains invalid package name `{}`; the changeset \
305	                             will not be consumed until this entry is resolved",
306	                            cs.path.display(),
307	                            entry.name
308	                        ),
309	                        package: None,
310	                        path: Some(cs.path.clone()),
311	                        governed_by: None,
312	                        escalated_by: None,
313	                    });
314	                    continue;
315	                }
316	            };
317	            match resolve_target_package(graph.packages(), identity, &id)? {
318	                Some(target_pkg) => {
319	                    matched_any = true;
320	                    let canonical_id = target_pkg.id.clone();
321	                    let cur_sev = agg.severities.get(&canonical_id).copied().unwrap_or(Severity::None);
322	                    if entry.severity > cur_sev {
323	                        agg.severities.insert(canonical_id.clone(), entry.severity);
324	                        agg.reasons.insert(
325	                            canonical_id.clone(),
326	                            BumpReason::Changeset {
327	                                changesets: vec![cs.id.clone()],
328	                            },
329	                        );
330	                        agg.named_by.insert(canonical_id.clone(), NamedBy::Changeset);
331	                    }
332	
333	                    if entry.severity != Severity::None && is_already_recorded {
334	                        agg.pre_mode_recorded_only.insert(canonical_id.clone());
335	                    }
336	                    if entry.severity != Severity::None && !is_already_recorded {
337	                        // In pre-release mode use the pre-cycle entry version as the
338	                        // changelog "from" baseline so the log covers the full pre
339	                        // range rather than reflecting live (pre-tagged) versions.
340	                        let pkg_ver = if is_pre_mode {
341	                            pre.and_then(|s| crate::pre_initial_version(s, &canonical_id))
342	                                .cloned()
343	                                .or_else(|| base_versions.get(&canonical_id).cloned())
344	                                .unwrap_or_else(|| Version::semver(0, 0, 0))
345	                        } else {
346	                            tags.last_tag(&canonical_id)
347	                                .map(|t| t.version.clone())
348	                                .or_else(|| base_versions.get(&canonical_id).cloned())
349	                                .unwrap_or_else(|| Version::semver(0, 0, 0))
350	                        };
351	                        let cl_input =
352	                            agg.changelog_inputs
353	                                .entry(canonical_id.clone())
354	                                .or_insert_with(|| ChangelogInput {
355	                                    package: canonical_id.clone(),
356	                                    from: pkg_ver,
357	                                    to: None,
358	                                    entries: Vec::new(),
359	                                });
360	                        cl_input.entries.push(ChangelogEntry {
361	                            severity: entry.severity,
362	                            source: ChangeSource::Changeset {
363	                                filename: cs.id.clone(),
364	                                summary: cs.changeset.summary.clone(),
365	                            },
366	                        });
367	                    }
368	                }
369	                None => {
370	                    // Entry references a package not in the workspace (e.g. a
371	                    // package that was removed since the changeset was written).
372	                    // Emit a diagnostic so the user knows, but do NOT count
373	                    // this as a match -- a fully-orphaned changeset stays on
374	                    // disk rather than being silently deleted.
375	                    has_unresolved = true;
376	                    agg.diagnostics.push(Diagnostic {
377	                        code: callisto_model::DiagnosticCode::UnknownPackage,
378	                        severity: callisto_model::DiagnosticSeverity::Warning,
379	                        message: format!(
380	                            "Changeset `{}` references package `{}` which is not in the \
381	                             workspace; the changeset will not be consumed until this entry \
382	                             is resolved",
383	                            cs.path.display(),
384	                            entry.name
385	                        ),
386	                        package: None,
387	                        path: Some(cs.path.clone()),
388	                        governed_by: None,
389	                        escalated_by: None,
390	                    });
391	                }
392	            }
393	        }
394	        // A changeset with any unresolved entry (orphaned or invalid) is left on disk and
395	        // unrecorded regardless of mode, so a later rerun can still pick up its bump.
396	        if matched_any && !has_unresolved {
397	            if is_pre_mode {
398	                agg.pre_mode_has_active_changeset = true;
399	                // Records newly-seen ids so a rerun treats them as already-applied and skips the changelog entry.
400	                if !is_already_recorded {
401	                    agg.new_pre_changesets.push(cs.id.clone());
402	                }
403	            } else {
404	                agg.consumed.push(cs.path.clone());
405	            }
406	        }
407	    }
408	
409	    loop {
410	        let mut changed = false;
411	        if union_fixed(&mut agg, &config.groups, base_versions) {
412	            changed = true;
413	        }
414	        if union_linked(&mut agg, &config.groups, base_versions) {
415	            changed = true;
416	        }
417	        if !changed {
418	            break;
419	        }
420	    }
421	
422	    Ok(agg)
423	}
424	
425	pub(crate) fn union_fixed(
426	    agg: &mut Aggregation,
427	    groups: &GroupTable,
428	    base_versions: &BTreeMap<PackageId, Version>,
429	) -> bool {
430	    let mut changed = false;
431	    for g in groups.fixed.values() {
432	        let target = g.max_severity(&agg.severities);
433	        if target == Severity::None {
434	            continue;
435	        }
436	
437	        for m in g.package_members().cloned().collect::<Vec<_>>() {
438	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
439	            if target > cur {
440	                // Guard against stale group members: a package listed in the
441	                // config group that was subsequently removed from the workspace
442	                // must not be inserted into severities.  Doing so causes
443	                // `bump_target` in `solve_cascade` to call
444	                // `input.base.get(stale_id)` -> `None` ->
445	                // `Err(GraphError::Manifest(MissingField))`, which surfaces as
446	                // a misleading crash.  Emit a warning instead and skip.
447	                if !base_versions.contains_key(&m) {
448	                    agg.diagnostics.push(Diagnostic {
449	                        code: callisto_model::DiagnosticCode::UnknownPackage,
450	                        severity: callisto_model::DiagnosticSeverity::Warning,
451	                        message: format!(
452	                            "Fixed group `{}` references package `{}` which is not in the \
453	                             workspace; the stale group member is skipped. Remove it from \
454	                             callisto.toml to silence this warning.",
455	                            g.name,
456	                            m.display_name()
457	                        ),
458	                        package: Some(m.clone()),
459	                        path: None,
460	                        governed_by: Some(callisto_model::ConfigKey::FIXED_GROUP),
461	                        escalated_by: None,
462	                    });
463	                    continue;
464	                }
465	                agg.severities.insert(m.clone(), target);
466	                agg.reasons
467	                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
468	                changed = true;
469	            }
470	        }
471	    }
472	    changed
473	}
474	
475	pub(crate) fn union_linked(
476	    agg: &mut Aggregation,
477	    groups: &GroupTable,
478	    base_versions: &BTreeMap<PackageId, Version>,
479	) -> bool {
480	    let mut changed = false;
481	    for g in groups.linked.values() {
482	        let named_any = g.package_members().any(|id| agg.named_by.contains_key(id));
483	        if !named_any {
484	            continue;
485	        }
486	
487	        // Unlike `union_fixed`'s max_severity (over every member), a linked
488	        // group's target severity comes only from members a changeset or
489	        // inference actually named -- an unnamed sibling's stale leftover
490	        // severity from an earlier fixed-point round must not count.
491	        let target_sev = g
492	            .package_members()
493	            .filter(|id| agg.named_by.contains_key(*id))
494	            .filter_map(|id| agg.severities.get(id).copied())
495	            .max()
496	            .unwrap_or(Severity::None);
497	
498	        for m in g.package_members().cloned().collect::<Vec<_>>() {
499	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
500	            if target_sev > cur {
501	                // Guard against stale linked-group members, same rationale as
502	                // in `union_fixed`: a removed package must not enter
503	                // `agg.severities`, which would cause `bump_target` to crash.
504	                if !base_versions.contains_key(&m) {
505	                    agg.diagnostics.push(Diagnostic {
506	                        code: callisto_model::DiagnosticCode::UnknownPackage,
507	                        severity: callisto_model::DiagnosticSeverity::Warning,
508	                        message: format!(
509	                            "Linked group `{}` references package `{}` which is not in the \
510	                             workspace; the stale group member is skipped. Remove it from \
511	                             callisto.toml to silence this warning.",
512	                            g.name,
513	                            m.display_name()
514	                        ),
515	                        package: Some(m.clone()),
516	                        path: None,
517	                        governed_by: Some(callisto_model::ConfigKey::LINKED_GROUP),
518	                        escalated_by: None,
519	                    });
520	                    continue;
521	                }
522	                agg.severities.insert(m.clone(), target_sev);
523	                agg.reasons
524	                    .insert(m.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
525	                changed = true;
526	            }
527	        }
528	    }
529	    changed
530	}
