24	/// Whether each of `packages` changed since its last tag: a non-merge commit
25	/// in `tag..HEAD` touched one of its paths, or its tracked files differ from
26	/// the tag. An untagged package counts as changed.
27	///
28	/// One `git rev-parse` for every tag, then per distinct tag commit one `git
29	/// log` and at most one `git diff`, however many packages share that commit.
30	pub fn changed_since_last_tag(
31	    packages: &[&Package],
32	    tags: &TagIndex,
33	    git: &GitAccess<'_>,
34	) -> Result<BTreeMap<PackageId, bool>, GraphError> {
35	    let mut changed = BTreeMap::new();
36	    let mut tagged = Vec::new();
37	    for pkg in packages {
38	        match tags.last_tag(&pkg.id) {
39	            // Fully qualified so a tag name can never be misread as a flag.
40	            Some(last) => tagged.push((*pkg, format!("refs/tags/{}", last.name.as_str()))),
41	            None => {
42	                changed.insert(pkg.id.clone(), true);
43	            }
44	        }
45	    }
46	    if tagged.is_empty() {
47	        return Ok(changed);
48	    }
49	
50	    let refs: Vec<String> = tagged.iter().map(|(_, r)| r.clone()).collect();
51	    let keys: Vec<String> = match git.resolve_commits(&refs)? {
52	        Some(shas) => shas.iter().map(|sha| sha.as_str().to_string()).collect(),
53	        None => refs,
54	    };
55	    let mut groups: BTreeMap<String, Vec<&Package>> = BTreeMap::new();
56	    for ((pkg, _), key) in tagged.into_iter().zip(keys) {
57	        groups.entry(key).or_default().push(pkg);
58	    }
59	
60	    for (since, members) in groups {
61	        // A failed walk only skips the cheap check in favor of the exact diff.
62	        let committed = match git.paths_changed_since(&since) {
63	            Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
64	            result => result.unwrap_or_default(),
65	        };
66	        let mut differing: Option<Option<Vec<PathBuf>>> = None;
67	        for pkg in members {
68	            let specs = package_paths(pkg);
69	            let mut is_changed = touches(&committed, &specs);
70	            if !is_changed {
71	                if differing.is_none() {
72	                    differing = Some(match git.paths_differing_from(&since) {
73	                        Ok(paths) => Some(paths),
74	                        Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
75	                        Err(_) => None,
76	                    });
77	                }
78	                // A diff that could not run counts as changed.
79	                is_changed = differing
80	                    .as_ref()
81	                    .and_then(Option::as_ref)
82	                    .is_none_or(|paths| touches(paths, &specs));
83	            }
84	            changed.insert(pkg.id.clone(), is_changed);
85	        }
86	    }
87	    Ok(changed)
88	}
