1	use std::collections::BTreeMap;
2	
3	use callisto_model::vcs::GitAccess;
4	use callisto_model::{
5	    select_last_tag, CommitSha, Diagnostic, Ecosystem, LastTag, LastTagSelection, PackageId, TagTemplate,
6	    VersionGrammar,
7	};
8	
9	use crate::config::ResolvedConfig;
10	use crate::error::GraphError;
11	use crate::resolver::DependencyResolver;
12	use crate::IdentityIndex;
13	
14	/// Fetches the full, unfiltered list of every tag name in the repository.
15	///
16	/// Deliberately fetches with no glob pattern: callers filter afterwards via
17	/// [`matching_tags`], so the fetch batches once across every package (see
18	/// [`TagIndex::build`]) instead of one `git` spawn per package.
19	pub(crate) fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
20	    let tags = git.list_tags(None)?;
21	    Ok(tags.into_iter().map(|t| t.as_str().to_string()).collect())
22	}
23	
24	/// Filters `all_tags` down to those matching `template`'s glob.
25	///
26	/// Compiles the glob via [`callisto_model::vcs::compile_tag_glob`] -- the same
27	/// helper `GitAccess::list_tags` uses -- so tag selection is identical
28	/// either way. Includes error behavior: a
29	/// `template.glob()` that fails to compile surfaces as
30	/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
31	/// the unsafe alternative, since a malformed template must never silently
32	/// make "last tag" resolution pick an unrelated package's tag.
33	fn matching_tags<'a>(all_tags: &'a [String], template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
34	    let glob = template.glob();
35	    GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
36	    let matcher = callisto_model::vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;
37	
38	    Ok(all_tags
39	        .iter()
40	        .filter(|t| matcher.is_match(t.as_str()))
41	        .map(|s| s.as_str())
42	        .collect())
43	}
44	
45	/// Test-observability counter: total number of times [`matching_tags`] has
46	/// compiled a fresh `globset::Glob`. Production code never reads this; it
47	/// exists so tests can assert `TagIndex::build` compiles/scans at most once
48	/// per *distinct* tag-template glob, not once per package -- a
49	/// `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template` can
50	/// apply the identical template string to many packages at once.
51	static GLOB_COMPILE_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
52	
53	/// Resets the internal glob-compile call counter to zero. Intended for use in test setup.
54	///
55	/// Process-global, like `callisto_manifests::reset_open_call_count` -- exact
56	/// counts must be asserted from an isolated integration-test binary under
57	/// `#[serial]`, not an inline unit test sharing this crate's `--lib`
58	/// process with other, non-serial tests (see
59	/// `tests/tag_glob_cache_count_test.rs`).
60	pub fn reset_glob_compile_count() {
61	    GLOB_COMPILE_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
62	}
63	
64	/// Reads the current value of the internal glob-compile call counter.
65	pub fn glob_compile_count() -> usize {
66	    GLOB_COMPILE_COUNT.load(std::sync::atomic::Ordering::SeqCst)
67	}
68	
69	/// Selects the highest-versioned tag matching `template` out of a full tag
70	/// list previously obtained via [`fetch_all_tags`], reusing a `cache` of
71	/// already-compiled/already-scanned candidates keyed by `template.glob()`
72	/// -- a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
73	/// string applies the identical template to every matching package, so
74	/// without this cache `TagIndex::build`'s per-package loop would recompile
75	/// the same `globset::Glob` and rescan the full tag list once per package
76	/// sharing that template, instead of once per distinct template.
77	fn select_from_tags_cached<'a>(
78	    all_tags: &'a [String],
79	    template: &TagTemplate,
80	    grammar: VersionGrammar,
81	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
82	) -> Result<LastTagSelection, GraphError> {
83	    let glob = template.glob();
84	    let candidates = match cache.get(&glob) {
85	        Some(cached) => cached.clone(),
86	        None => {
87	            let matched = matching_tags(all_tags, template)?;
88	            cache.insert(glob, matched.clone());
89	            matched
90	        }
91	    };
92	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
93	}
94	
95	/// The higher-versioned of two tags found for one package; `first` wins a tie.
96	fn newest(first: Option<LastTag>, second: Option<LastTag>) -> Option<LastTag> {
97	    match (first, second) {
98	        (Some(first), Some(second)) => {
99	            let newer = second
100	                .version
101	                .compare(&first.version)
102	                .is_ok_and(std::cmp::Ordering::is_gt);
103	            Some(if newer { second } else { first })
104	        }
