147	        let built = TagIndex::build(self.git_access(), &self.graph, &self.identity, &self.config)?;
148	        // `OnceCell::set` only fails if another write already raced it in;
149	        // `Workspace` is only ever accessed through `&self` here (never
150	        // shared across threads -- `R`/`D` carry no such bound), so the
151	        // `get()` check above already ruled that out. Fall back to `get()`
152	        // either way rather than trusting the `set` call's own return value,
153	        // so this stays correct even if that assumption ever changes.
154	        self.tags.set(built).ok();
