260	pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
261	    git: &GitAccess<'_>,
262	    graph: &D,
263	    identity: &IdentityIndex,
264	    pre_json: &std::path::Path,
265	    mut state: callisto_model::format::PreState,
266	    raw_versions: &indexmap::IndexMap<String, String>,
267	) -> Result<callisto_model::format::PreState, GraphError> {
268	    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
269	    let mut owners = BTreeMap::new();
270	    let mut rosters = history::Rosters::default();
271	    for key in &keys {
272	        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
273	            owners.insert(key.clone(), owner);
274	            continue;
275	        }
276	        let same: Vec<&callisto_model::Package> = graph
277	            .packages()
278	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
279	            .collect();
280	        let owner = if same.is_empty() {
281	            match identity.resolve(key) {
282	                Ok(id) => graph.packages().find(|p| p.id == id),
283	                Err(GraphError::UnknownPackage { .. }) => None,
284	                Err(GraphError::AmbiguousName { candidates, .. }) => {
285	                    return Err(GraphError::AmbiguousPreJsonKey {
286	                        key: key.clone(),
287	                        candidates,
288	                    });
289	                }
290	                Err(error) => return Err(error),
291	            }
292	        } else {
293	            let owner = match git.commit_adding(pre_json).map_err(GraphError::Vcs)? {
294	                Some(added) => history::sole_owner_at(git, &added, key, &same, identity, &mut rosters)?,
295	                None => None,
296	            };
297	            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
298	                key: key.clone(),
299	                candidates: same.iter().map(|p| p.id.clone()).collect(),
