302	        if let Some(owner) = owner {
303	            owners.insert(key.clone(), owner);
304	        }
305	    }
306	    state
307	        .resolve_initial_versions_from_raw(raw_versions, |key| {
308	            owners
309	                .get(key)
310	                .and_then(|owner| owner.canonical_manifests().next().map(|manifest| manifest.ecosystem()))
311	        })
312	        .map_err(GraphError::PreJson)?;
313	    let mut legacy_by_owner_key: BTreeMap<String, Vec<String>> = BTreeMap::new();
314	    for key in keys {
315	        if let Some(owner) = owners.get(&key) {
316	            let owner_key = pre_json_key(&owner.id);
317	            if owner_key != key {
318	                legacy_by_owner_key.entry(owner_key).or_default().push(key);
319	            }
320	        }
321	    }
322	    // Every key for one package must agree before anything moves.
323	    for (owner_key, legacy_keys) in &legacy_by_owner_key {
324	        let reference = if state.initial_versions.contains_key(owner_key) {
325	            owner_key
326	        } else {
327	            &legacy_keys[0]
328	        };
329	        let reference_version = &state.initial_versions[reference];
330	        for key in legacy_keys.iter().filter(|key| *key != reference) {
331	            let version = &state.initial_versions[key];
