78	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
79	/// the file is absent -- not every package has a `package.json`.
80	///
81	/// Callers needing more than one field out of the same `package.json` (e.g.
82	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
83	/// call this once and pass the resulting `Value` to each field-extraction
84	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
85	/// each one independently re-read and re-parse the file from disk.
86	pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
87	    if !pkg_json_path.exists() {
88	        return Ok(None);
89	    }
90	    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
91	        GraphError::Manifest(ManifestError::Read {
92	            path: pkg_json_path.to_path_buf(),
93	            message: e.to_string(),
94	        })
95	    })?;
96	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
97	        GraphError::Manifest(ManifestError::Parse {
98	            path: pkg_json_path.to_path_buf(),
99	            format: ManifestFormat::PackageJson,
100	            message: e.to_string(),
101	        })
102	    })?;
103	    Ok(Some(val))
104	}
