120	/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
121	/// platform/arch/abi with this module's hostRunner/useCross/artifactName
122	/// table. Returns `None` when `triple` is not recognised by either --
123	/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
124	/// rather than treating it as an error.
125	pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
126	    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
127	        return None;
128	    };
129	    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
130	    let artifact_name = artifact_name_for_package_platform(package_name, &platform, &arch, abi.as_deref());
131	    Some(PlatformTarget {
132	        triple: triple.to_string(),
133	        platform,
134	        arch,
135	        abi,
136	        host_runner: host_runner.to_string(),
137	        use_cross,
138	        artifact_name,
139	        package_dir: package_dir.to_string(),
140	        package_name: package_name.to_string(),
141	        manifest_path: None,
142	    })
143	}
