382	/// The `--manifest-path` a napi package's build needs; `None` when its own directory holds its addon crate.
383	pub(crate) fn napi_manifest_path(
384	    pkg: &MatrixPackageInput,
385	    pkg_json: &serde_json::Value,
386	    crates: &[NapiCrate],
387	) -> Result<Option<String>, GraphError> {
388	    let in_package_dir =
389	        |candidate: &&NapiCrate| Path::new(&candidate.manifest_path).parent() == Some(Path::new(&pkg.dir_rel));
390	    if crates.iter().any(|candidate| in_package_dir(&candidate)) {
391	        return Ok(None);
392	    }
393	    let binary_name = callisto_manifests::napi_binary_name(pkg_json);
394	    let matches: Vec<&NapiCrate> = crates
395	        .iter()
396	        .filter(|candidate| candidate.lib_name == binary_name)
397	        .collect();
398	    if let [only] = matches.as_slice() {
399	        return Ok(Some(only.manifest_path.clone()));
400	    }
401	    let listed: Vec<&NapiCrate> = if matches.is_empty() {
402	        crates.iter().collect()
403	    } else {
404	        matches
405	    };
406	    Err(GraphError::NapiCrateUnresolved {
407	        package: pkg.id.clone(),
408	        binary_name,
409	        candidates: listed
410	            .iter()
411	            .map(|candidate| format!("{} (lib `{}`)", candidate.manifest_path, candidate.lib_name))
412	            .collect(),
413	    })
414	}
