382	    release_trigger: Option<&str>,
383	    tag_template: Option<&str>,
384	    previous_tag_templates: Option<&[String]>,
385	    changelog: Option<&str>,
386	    pre_major_inference: Option<&str>,
387	    publish_to: Option<&[String]>,
388	) -> Result<PackageConfig, ConfigError> {
389	    let release_trigger = release_trigger.map(parse_release_trigger).transpose()?;
390	
391	    let tag_template = tag_template
392	        .map(TagTemplate::parse)
393	        .transpose()
394	        .map_err(ConfigError::Tag)?;
395	
396	    let previous_tag_templates = previous_tag_templates
397	        .unwrap_or_default()
398	        .iter()
399	        .map(|template| TagTemplate::parse(template))
400	        .collect::<Result<Vec<_>, _>>()
401	        .map_err(ConfigError::Tag)?;
402	
403	    let changelog = changelog
404	        .map(|s| {
405	            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
406	                pattern: pattern_display.to_string(),
407	                value: s.to_string(),
408	            })
409	        })
410	        .transpose()?;
411	
412	    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;
413	
414	    let publish_to = publish_to
415	        .map(|targets| {
416	            targets
417	                .iter()
418	                .map(|s| parse_publish_target(s))
419	                .collect::<Result<Vec<_>, _>>()
420	        })
421	        .transpose()
422	        .map_err(|e| match e {
423	            ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
424	                path: callisto_toml.to_path_buf(),
425	                key: format!("{error_prefix} publish-to: {key}"),
426	            },
427	            other => other,
428	        })?;
