440	/// Reads and parses `root/callisto.toml` (absent means empty), then [`resolve`]s it.
441	pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
442	    let callisto_toml = root.join("callisto.toml");
443	    let raw = if callisto_toml.exists() {
444	        let content = fs::read_to_string(&callisto_toml).map_err(|e| ConfigError::Read {
445	            path: callisto_toml.clone(),
446	            message: e.to_string(),
447	        })?;
448	        toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
449	            path: callisto_toml.clone(),
450	            message: e.to_string(),
451	        })?
452	    } else {
453	        RawConfig::default()
454	    };
455	    resolve(root, raw)
456	}
457	
458	/// Validates and defaults an already-parsed config for the workspace at `root`.
459	pub fn resolve(root: &Path, raw: RawConfig) -> Result<ResolvedConfig, ConfigError> {
460	    let callisto_toml = root.join("callisto.toml");
461	    let mut provenance = BTreeMap::new();
462	    let product_release = raw.release.map(resolve_product_release).transpose()?;
463	
464	    let changesets_dir_str = raw
465	        .changesets
466	        .as_ref()
467	        .and_then(|c| c.dir.as_deref())
468	        .unwrap_or(".changeset");
469	
470	    // Reject any changesets.dir value that is absolute or contains '..'
471	    // components — either would allow load_changesets / atomic_write to
472	    // escape the workspace root. We check components() rather than
473	    // canonicalizing because the directory may not exist yet (e.g. a fresh
474	    // workspace).
475	    let changesets_dir =
476	        callisto_model::workspace_relative(changesets_dir_str).map_err(|_err| ConfigError::InvalidChangesetsDir {
477	            dir: changesets_dir_str.to_string(),
478	        })?;
479	
480	    let cascade_raw = raw.cascade.unwrap_or_default();
481	    let mode = match cascade_raw.mode.as_deref() {
482	        Some("always") => {
483	            provenance.insert(ConfigKey::CASCADE_MODE, ConfigProvenance::Explicit);
484	            CascadeMode::Always
485	        }
486	        Some("out-of-range") | None => CascadeMode::OutOfRange,
487	        Some(other) => {
488	            return Err(ConfigError::UnknownKey {
489	                path: callisto_toml,
490	                key: format!("cascade.mode = {other}"),
491	            })
492	        }
493	    };
494	
495	    let bump_severity = match cascade_raw.bump_severity.as_deref() {
496	        Some("minor") => {
