44	/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
45	/// instead of `cargo` silently re-resolving one at publish time.
46	/// `registry_key` is `Some` only for a non-default registry -- crates.io is
47	/// the implicit default and never needs `--registry`.
48	///
49	/// Before returning, verifies that the on-disk `Cargo.toml` version under
50	/// `package_dir` (resolving `version.workspace = true` against the
51	/// workspace root's `[workspace.package].version` when present) matches
52	/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
53	/// the durable release executor's own `dispatch_registry` had silently
54	/// dropped: it catches the common mistake of running `release execute`
55	/// without first running `callisto version`, which would otherwise silently
56	/// publish the old on-disk version.
57	pub fn cargo_publish_argv(
58	    workspace_root: &Path,
59	    package_dir: &Path,
60	    package_name: &str,
61	    version: &Version,
62	    registry_key: Option<&str>,
63	) -> Result<Argv, GraphError> {
64	    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;
65	
66	    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
67	    let mut args = vec![
68	        "publish".to_string(),
69	        "--manifest-path".to_string(),
70	        manifest_path.to_string_lossy().into_owned(),
71	        "--locked".to_string(),
72	    ];
73	    if let Some(reg) = registry_key {
74	        args.push("--registry".to_string());
75	        args.push(reg.to_string());
76	    }
77	    Ok(Argv {
78	        program: "cargo".to_string(),
79	        args,
80	        cwd: workspace_root.to_path_buf(),
81	    })
82	}
83	
84	fn verify_cargo_ondisk_version(
85	    workspace_root: &Path,
86	    package_dir: &Path,
87	    package_name: &str,
88	    planned: &Version,
89	) -> Result<(), GraphError> {
90	    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
91	    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
92	        path: manifest_path.clone(),
93	        message: error.to_string(),
94	    })?;
95	    // Parse only the [package].version field -- no need for full CST. A
96	    // permissive `toml::Value` intermediate rather than a direct `String`
97	    // deserialization, because `version.workspace = true` (Cargo's
98	    // workspace-version-inheritance syntax) parses `version` as a table, not
99	    // a string.
100	    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
101	        path: manifest_path.clone(),
102	        message: error.to_string(),
103	    })?;
104	    let version_value =
105	        parsed
106	            .get("package")
107	            .and_then(|p| p.get("version"))
108	            .ok_or_else(|| GraphError::ReleaseInputRead {
109	                path: manifest_path.clone(),
110	                message: "missing [package].version".to_string(),
111	            })?;
112	
113	    let on_disk = if let Some(s) = version_value.as_str() {
114	        s.to_string()
115	    } else if version_value.get("workspace").and_then(toml::Value::as_bool) == Some(true) {
116	        let root_manifest_path = workspace_root.join("Cargo.toml");
117	        let resolver = WorkspaceCargoResolver::load(&root_manifest_path)?;
118	        let ws_version = resolver
119	            .workspace_version()?
120	            .ok_or_else(|| GraphError::ReleaseInputRead {
121	                path: root_manifest_path.clone(),
122	                message: "`version.workspace = true` but the workspace root has no [workspace.package].version"
123	                    .to_string(),
124	            })?;
125	        ws_version.render().to_string()
126	    } else {
127	        return Err(GraphError::ReleaseInputRead {
128	            path: manifest_path,
129	            message: "[package].version is neither a string nor a `{ workspace = true }` table".to_string(),
130	        });
131	    };
132	
133	    let found = Version::parse(&on_disk, planned.grammar())?;
134	    if found != *planned {
135	        return Err(GraphError::OnDiskVersionDrift {
136	            package: PackageId::Prefixed {
137	                ecosystem: Ecosystem::Cargo,
138	                name: package_name.to_string(),
139	            },
140	            expected: planned.clone(),
141	            found,
142	        });
143	    }
144	    Ok(())
145	}
146	
147	// ------------------------------------------------------------------ npm
148	
149	/// The npm-compatible package manager a workspace uses, detected from
150	/// lockfile presence. Each one needs a materially different invocation to
151	/// publish a single named package out of a monorepo -- see
152	/// [`npm_publish_argv`].
153	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
154	pub enum NpmPackageManager {
155	    Pnpm,
156	    Yarn,
157	    Bun,
158	    Npm,
159	}
160	
161	/// Detects the npm-compatible package manager for `workspace_root` from
162	/// lockfile presence. Detection priority: pnpm > yarn > bun > npm (default).
163	///
164	/// This is real, live-today correctness content: the durable release
165	/// executor's `dispatch_registry` used to hardcode plain `npm publish`
166	/// regardless of which package manager a workspace actually uses, so a pnpm
167	/// or yarn workspace published with the wrong tool.
168	pub fn detect_npm_package_manager(workspace_root: &Path) -> NpmPackageManager {
169	    if workspace_root.join("pnpm-lock.yaml").exists() {
170	        NpmPackageManager::Pnpm
171	    } else if workspace_root.join("yarn.lock").exists() {
172	        NpmPackageManager::Yarn
173	    } else if workspace_root.join("bun.lockb").exists() || workspace_root.join("bun.lock").exists() {
174	        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
175	        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
176	        NpmPackageManager::Bun
177	    } else {
178	        NpmPackageManager::Npm
179	    }
180	}
181	
182	/// Builds the npm-ecosystem publish argv for one package, given the
183	/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
184	///
185	/// | Package manager | Program | Base args                                  |
186	/// |------------------|---------|--------------------------------------------|
187	/// | Pnpm             | `pnpm`  | `publish --filter=<name> --no-git-checks`  |
188	/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
189	/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
190	/// | Npm              | `npm`   | `publish --workspace=<name>`               |
191	///
192	/// `--filter=`/`--workspace=` use the joined form so the name cannot be
193	/// re-read as an option. Yarn takes the name positionally and has no joined
194	/// spelling, so there it rests on `ReleasePackageId`'s leading-`-` rejection.
195	///
196	/// `tag`/`access`/`registry` are appended to every variant's base args.
197	/// `package_dir` is only used for bun: it has no `--filter`/`--workspace`
198	/// flag to target one package by name, so it alone must run from the
199	/// package's own directory rather than the workspace root.
200	pub fn npm_publish_argv(
201	    workspace_root: &Path,
202	    package_dir: &Path,
203	    package_name: &str,
204	    package_manager: NpmPackageManager,
205	    tag: Option<&str>,
206	    access: Option<NpmAccess>,
207	    registry: Option<&str>,
208	) -> Argv {
209	    let extra = npm_publish_flags(package_name, tag, access, registry);
210	
211	    let (program, mut args, cwd) = match package_manager {
212	        NpmPackageManager::Pnpm => (
213	            "pnpm",
214	            vec![
215	                "publish".to_string(),
216	                // `--filter=<name>`, not `--filter <name>`: the joined form
217	                // cannot be re-read as an option even if a name slipped past
218	                // `ReleasePackageId`'s charset rule.
219	                format!("--filter={package_name}"),
220	                // pnpm >= 7 refuses to publish from a dirty working tree by
221	                // default. After `callisto version` stages manifest bumps,
222	                // the tree is always dirty until the operator commits, so
223	                // this bypasses the git-status check.
224	                "--no-git-checks".to_string(),
225	            ],
226	            workspace_root.to_path_buf(),
227	        ),
228	        NpmPackageManager::Yarn => (
229	            "yarn",
230	            vec![
231	                "workspace".to_string(),
232	                package_name.to_string(),
233	                "npm".to_string(),
234	                "publish".to_string(),
235	            ],
236	            workspace_root.to_path_buf(),
237	        ),
238	        NpmPackageManager::Bun => ("bun", vec!["publish".to_string()], workspace_root.join(package_dir)),
239	        NpmPackageManager::Npm => (
240	            "npm",
241	            vec!["publish".to_string(), format!("--workspace={package_name}")],
242	            workspace_root.to_path_buf(),
243	        ),
244	    };
245	    args.extend(extra);
246	    Argv {
247	        program: program.to_string(),
248	        args,
249	        cwd,
250	    }
251	}
252	
253	/// The access an npm package publishes with: the explicit `publishConfig.access`,
254	/// else `public` for a scoped `@scope/name` (npm defaults scoped packages to restricted).
255	pub fn npm_default_access(name: &str, explicit: Option<NpmAccess>) -> Option<NpmAccess> {
256	    explicit.or_else(|| name.starts_with('@').then_some(NpmAccess::Public))
257	}
258	
259	/// `--tag`/`--access`/`--registry`, shared by every npm-ecosystem publish argv.
260	fn npm_publish_flags(
261	    package_name: &str,
262	    tag: Option<&str>,
263	    access: Option<NpmAccess>,
264	    registry: Option<&str>,
265	) -> Vec<String> {
266	    let mut extra: Vec<String> = Vec::new();
267	    if let Some(t) = tag {
268	        extra.push("--tag".to_string());
269	        extra.push(t.to_string());
270	    }
271	    if let Some(access) = npm_default_access(package_name, access) {
272	        extra.push("--access".to_string());
273	        extra.push(
274	            match access {
275	                NpmAccess::Public => "public",
276	                NpmAccess::Restricted => "restricted",
277	            }
278	            .to_string(),
279	        );
280	    }
281	    if let Some(reg) = registry {
282	        extra.push("--registry".to_string());
283	        extra.push(reg.to_string());
284	    }
285	    extra
286	}
287	
288	/// Publishes the package in `package_dir` by path: `npm publish <dir>` from the
289	/// workspace root, whatever the package manager. pnpm `--filter`, yarn
290	/// `workspace`, and npm `--workspace` select only workspace members, and an npm
291	/// platform package directory usually is not one. The path is absolute, so it
292	/// cannot be read as an option.
293	pub fn npm_publish_directory_argv(
294	    workspace_root: &Path,
295	    package_dir: &Path,
296	    package_name: &str,
297	    tag: Option<&str>,
298	    access: Option<NpmAccess>,
299	    registry: Option<&str>,
300	) -> Argv {
301	    let mut args = vec![
302	        "publish".to_string(),
303	        workspace_root.join(package_dir).to_string_lossy().into_owned(),
304	    ];
305	    args.extend(npm_publish_flags(package_name, tag, access, registry));
306	    Argv {
307	        program: "npm".to_string(),
308	        args,
309	        cwd: workspace_root.to_path_buf(),
310	    }
311	}
312	
313	// ----------------------------------------------------------------- pypi
314	
315	/// `python -m build --sdist --wheel --outdir <outdir>` in the package directory, with the first interpreter on PATH
316	/// and `SOURCE_DATE_EPOCH` set so backends that honor it stamp the same time into every rebuild.
317	pub fn pypi_build_argv(
318	    workspace_root: &Path,
319	    package_dir: &Path,
320	    outdir: &Path,
321	    source_date_epoch: u64,
322	) -> Result<Argv, GraphError> {
323	    let interpreter = resolve_python_interpreter(std::env::var_os("PATH").as_deref())?;
324	    Ok(Argv {
325	        program: "env".to_string(),
326	        args: vec![
327	            format!("SOURCE_DATE_EPOCH={source_date_epoch}"),
328	            interpreter.to_string(),
329	            "-m".to_string(),
330	            "build".to_string(),
331	            "--sdist".to_string(),
332	            "--wheel".to_string(),
333	            "--outdir".to_string(),
334	            outdir.to_string_lossy().into_owned(),
335	        ],
336	        cwd: workspace_root.join(package_dir),
337	    })
338	}
339	
340	/// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
341	pub fn pypi_upload_argv(workspace_root: &Path, package_dir: &Path, index: Option<&str>, files: &[PathBuf]) -> Argv {
342	    let mut args = vec!["upload".to_string()];
343	    if let Some(index) = index {
344	        args.push("--repository-url".to_string());
345	        args.push(index.to_string());
346	    }
347	    args.extend(files.iter().map(|file| file.to_string_lossy().into_owned()));
348	    Argv {
349	        program: "twine".to_string(),
350	        args,
351	        cwd: workspace_root.join(package_dir),
352	    }
353	}
354	
355	/// Resolves the interpreter for the PyPI build step's `python -m build`:
356	/// prefers `python3` -- the only name macOS and Debian systems guarantee --
357	/// and falls back to bare `python` for systems that only ship that. Errors
358	/// naming both when neither is on `path_value`.
359	///
360	/// `path_value` is injected rather than read from `$PATH` directly so tests
361	/// can exercise both resolutions and the error without mutating process-wide
362	/// environment state.
363	fn resolve_python_interpreter(path_value: Option<&OsStr>) -> Result<&'static str, GraphError> {
364	    if exists_on_path("python3", path_value) {
365	        Ok("python3")
366	    } else if exists_on_path("python", path_value) {
367	        Ok("python")
368	    } else {
369	        Err(GraphError::ReleasePreconditionUnmet {
370	            requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath,
371	        })
372	    }
373	}
374	
375	/// Whether `program` exists as a file in some directory of `path_value` --
376	/// PATH-lookup semantics, without ever spawning it.
377	fn exists_on_path(program: &str, path_value: Option<&OsStr>) -> bool {
378	    path_value.is_some_and(|path| std::env::split_paths(path).any(|dir| dir.join(program).is_file()))
379	}
380	
381	// ---- shared output-classification helpers --------------------------------
382	
383	fn combined_lower(output: &CommandOutput) -> String {
384	    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
385	}
386	
387	/// Parses a numeric retry-after value (seconds) as reported by a registry
388	/// tool's output.
389	fn parse_retry_after(raw: &str) -> Option<Duration> {
390	    raw.trim().parse::<u64>().ok().map(Duration::from_secs)
391	}
392	
393	/// Looks for a `retry after <N>` mention in already-lowercased text and
394	/// parses `<N>` as a whole-second duration.
395	fn extract_retry_after_duration(text_lower: &str) -> Option<Duration> {
396	    const NEEDLE: &str = "retry after ";
397	    let idx = text_lower.find(NEEDLE)?;
398	    let rest = &text_lower[idx + NEEDLE.len()..];
399	    let token = rest.split_whitespace().next()?;
400	    let digits: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
401	    if digits.is_empty() {
402	        return None;
403	    }
404	    parse_retry_after(&digits)
405	}
406	
407	fn detect_rate_limit(text_lower: &str) -> Option<RegistryError> {
408	    // Match rate-limit signals with context, never on bare digits alone.
409	    // Bare "429" in cargo's compressed-size output ("429.1KiB compressed")
410	    // would otherwise trigger this. Require at least one contextual phrase
411	    // alongside any "429".
412	    let is_rate_limited = text_lower.contains("too many requests")
413	        || text_lower.contains("rate limit")
414	        || text_lower.contains("erate_limit")
415	        || (text_lower.contains("429")
416	            && (text_lower.contains("too many") || text_lower.contains("rate") || text_lower.contains("retry")));
417	    if is_rate_limited {
418	        let dur = extract_retry_after_duration(text_lower).unwrap_or(Duration::from_secs(DEFAULT_RATE_LIMIT_WAIT_SECS));
419	        Some(RegistryError::RateLimited(dur))
420	    } else {
421	        None
422	    }
423	}
424	
425	fn detect_auth_failure(text_lower: &str, raw_stderr: &CommandOutput) -> Option<RegistryError> {
426	    // Match "401"/"403" with context, never on bare digits alone -- same
427	    // rationale as detect_rate_limit's guard against bare "429": a byte
428	    // count or elapsed-time figure in cargo's own packaging/build output
429	    // ("403129 bytes", "elapsed 4013ms") would otherwise misclassify an
430	    // unrelated failure as an auth failure.
431	    if (text_lower.contains("401") && text_lower.contains("auth"))
432	        || (text_lower.contains("403") && (text_lower.contains("auth") || text_lower.contains("forbidden")))
433	        || text_lower.contains("authentication")
434	        || text_lower.contains("not logged in")
435	        || text_lower.contains("invalid token")
436	        || text_lower.contains("forbidden")
437	    {
438	        Some(RegistryError::AuthFailed(raw_stderr.redacted_stderr()))
439	    } else {
440	        None
441	    }
442	}
443	
444	/// Classifies combined `cargo publish` output into a [`PublishOutcome`] or
445	/// [`RegistryError`].
446	pub(crate) fn classify_cargo_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
447	    let combined = combined_lower(output);
448	
449	    if combined.contains("already exists") || combined.contains("already uploaded") {
450	        return Ok(PublishOutcome::AlreadyPublished);
451	    }
452	    if output.success() {
453	        return Ok(PublishOutcome::Published);
454	    }
455	    if let Some(err) = detect_rate_limit(&combined) {
456	        return Err(err);
457	    }
458	    if let Some(err) = detect_auth_failure(&combined, output) {
459	        return Err(err);
460	    }
461	    Err(RegistryError::Other(format!(
462	        "cargo publish failed (exit {:?}): {}",
463	        output.exit_code,
464	        output.redacted_stderr().trim()
465	    )))
466	}
467	
468	/// Classifies combined `npm publish` (or `pnpm`/`yarn`/`bun` equivalent)
469	/// output into a [`PublishOutcome`] or [`RegistryError`].
470	pub(crate) fn classify_npm_publish_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
471	    let combined = combined_lower(output);
472	
473	    if combined.contains("epublishconflict")
474	        || combined.contains("previously published")
475	        || combined.contains("cannot publish over")
476	        || combined.contains("e409")
477	        || combined.contains("409 conflict")
478	    {
479	        return Ok(PublishOutcome::AlreadyPublished);
480	    }
481	    if output.success() {
482	        return Ok(PublishOutcome::Published);
483	    }
484	    if let Some(err) = detect_rate_limit(&combined) {
485	        return Err(err);
486	    }
487	    if let Some(err) = detect_auth_failure(&combined, output) {
488	        return Err(err);
489	    }
490	    Err(RegistryError::Other(format!(
491	        "npm publish failed (exit {:?}): {}",
492	        output.exit_code,
493	        output.redacted_stderr().trim()
494	    )))
495	}
496	
497	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
498	/// [`RegistryError`].
499	///
500	/// Priority order (highest wins):
501	/// 1. A successful run printing `"already exist"` (twine's `--skip-existing` message) without `"uploading"` ->
502	///    [`PublishOutcome::AlreadyPublished`]. Callisto passes no `--skip-existing`, so a conflict is a failing run and
503	///    falls through to `RegistryError::Other` below, which is the intended fail-closed outcome.
504	/// 2. Zero exit code with no skip-only mention -> [`PublishOutcome::Published`].
505	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) ->
506	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
507	///    retry-after duration.
508	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) ->
509	///    [`RegistryError::AuthFailed`].
510	/// 5. Anything else -> [`RegistryError::Other`].
511	pub(crate) fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
512	    let combined = combined_lower(output);
513	
514	    let has_skip = combined.contains("already exist");
515	    let has_upload = combined.contains("uploading");
516	    if has_skip && !has_upload && output.success() {
517	        return Ok(PublishOutcome::AlreadyPublished);
518	    }
519	    if output.success() {
520	        return Ok(PublishOutcome::Published);
521	    }
522	    if let Some(err) = detect_rate_limit(&combined) {
523	        return Err(err);
524	    }
525	    if let Some(err) = detect_auth_failure(&combined, output) {
526	        return Err(err);
527	    }
528	    let progress = callisto_model::redact_command_stderr(&output.stdout);
529	    let progress: Vec<_> = progress.lines().rev().take(8).collect();
530	    Err(RegistryError::Other(format!(
531	        "twine upload failed (exit {:?}): {}{}",
532	        output.exit_code,
533	        progress.into_iter().rev().collect::<Vec<_>>().join("\n"),
534	        output.redacted_stderr().trim_end()
535	    )))
536	}
