334	/// The name the *cargo* client knows this registry by. Callisto's logical
335	/// `cratesIo` key is cargo's built-in `crates-io`; every other key is spelled
336	/// the same in `.cargo/config.toml` as it is in `callisto.toml`.
337	/// The cargo registry name for a logical registry key (`cratesIo` is cargo's `crates-io`).
338	pub fn cargo_registry_name(key: &RegistryKey) -> &str {
339	    if key.as_str() == RegistryKey::CRATES_IO {
