414	/// Classifies one real `cargo info` run. There is no `--json`, so the two
415	/// answers cargo actually proves are read from its exit code and its text:
416	///
417	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
418	///   `cargo info` reports neither the index checksum nor the yank flag, so the
419	///   evidence says `None` for both rather than inventing them.
420	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
421	/// - anything else -- another exit code, another message (a network failure
422	///   prints ``failed to load source for dependency``), or a zero exit with no
423	///   matching version line: transient `Indeterminate`, retried by the bounded
424	///   policy. An unreachable registry must never read as an absence.
425	///
426	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
427	/// and answers "could not find" for one. That fails closed rather than open:
428	/// the publish attempt that follows is refused by the registry, and since only
429	/// an `Exact` observation may satisfy an operation, the run ends in the typed
430	/// `RegistryPublishUnconfirmed` error instead of a receipt.
431	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
432	    if output.success() {
433	        return if reports_version(&output.stdout, version) {
434	            settled(ProviderObservationV1::Exact {
435	                evidence: ProviderEvidenceV1::RegistryVersion {
436	                    version: version.clone(),
437	                    checksum: None,
438	                    yanked: None,
439	                },
440	            })
441	        } else {
442	            transient(ProviderIndeterminateCause::MalformedResponse, None)
443	        };
444	    }
445	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
446	        return settled(ProviderObservationV1::Absent);
447	    }
448	    transient(ProviderIndeterminateCause::CommandFailed, None)
449	}
450	
451	/// Whether cargo's `version: X ...` line names exactly the requested version.
452	fn reports_version(stdout: &str, version: &Version) -> bool {
453	    stdout.lines().any(|line| {
454	        line.trim()
455	            .strip_prefix("version: ")
456	            .and_then(|rest| rest.strip_prefix(version.render()))
457	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
458	    })
459	}
460	
461	/// The code npm gives a registry 404 for a package or a version.
462	const NPM_NOT_FOUND_CODE: &str = "E404";
463	
464	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
465	fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
466	    if output.success() {
467	        return if output.stdout_trimmed().is_empty() {
468	            transient(ProviderIndeterminateCause::MalformedResponse, None)
469	        } else {
470	            settled(ProviderObservationV1::Exact {
471	                evidence: ProviderEvidenceV1::RegistryVersion {
472	                    version: version.clone(),
473	                    checksum: None,
474	                    yanked: None,
475	                },
476	            })
477	        };
478	    }
479	    let code = if output.stdout_trimmed().is_empty() {
480	        npm_stderr_code(&output.stderr)
481	    } else {
482	        npm_error_code(&output.stdout)
483	    };
484	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
485	        return settled(ProviderObservationV1::Absent);
486	    }
487	    transient(ProviderIndeterminateCause::CommandFailed, None)
488	}
489	
490	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
491	fn npm_error_code(stdout: &str) -> Option<String> {
492	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
493	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
494	}
495	
496	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
497	fn npm_stderr_code(stderr: &str) -> Option<String> {
498	    stderr.lines().find_map(|line| {
499	        let rest = line
500	            .strip_prefix("npm ERR! ")
501	            .or_else(|| line.strip_prefix("npm error "))?;
502	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
503	    })
504	}
