580	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
581	/// experimental and hides yanked releases, and an unreachable index and a
582	/// missing project both look like "no versions found" to it. The index itself
583	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
584	/// so observation goes straight to `https://pypi.org/simple/<project>/`
585	/// (or the configured private index) over `curl`, never through `pip`.
586	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
587	
588	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
589	/// the legacy HTML page a bare GET would otherwise serve.
590	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
591	
592	/// The project's simple-index URL: the configured private index if one is
593	/// bound (already https-validated in `binding.rs`), else the public default.
594	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
595	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
596	    let project = normalize_pypi_project_name(package_name);
597	    format!("{}/{project}/", base.trim_end_matches('/'))
598	}
599	
600	/// The version segment of a simple-index filename, or `None` for an extension
601	/// this parser does not recognize (a legacy installer, say).
602	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
603	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
604	}
605	
606	/// Whether a simple-index file's filename names exactly the requested version.
607	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
608	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
609	        Version::parse(candidate, version.grammar())
610	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
611	    })
612	}
613	
614	/// Classifies a parsed 200 body: the matching file's yank status decides the
615	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
616	/// release is not the version this intent authorized, so it fails closed.
617	fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
618	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
619	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
620	    };
621	    let matching = index
622	        .files
623	        .iter()
624	        .filter(|file| pypi_simple_file_matches(file, version));
625	    let mut matched = false;
626	    for file in matching {
627	        if file.is_yanked() {
628	            return settled(ProviderObservationV1::Absent);
629	        }
630	        matched = true;
631	    }
632	    if !matched {
633	        return settled(ProviderObservationV1::Absent);
634	    }
635	    settled(exact_version(version))
636	}
637	
638	/// The observation that a version is on the registry, unyanked.
639	fn exact_version(version: &Version) -> ProviderObservationV1 {
640	    ProviderObservationV1::Exact {
641	        evidence: ProviderEvidenceV1::RegistryVersion {
642	            version: version.clone(),
643	            checksum: None,
644	            yanked: Some(false),
645	        },
646	    }
647	}
648	
649	/// What the index holds for one release.
650	enum PypiRemote {
651	    Absent,
652	    Files(Vec<PypiSimpleFile>),
653	    Indeterminate(ProviderIndeterminateCause),
654	}
655	
656	/// The release's own files from a parsed 200 body.
657	fn classify_pypi_files_body(body: &str, version: &Version) -> Attempt<PypiRemote> {
658	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
659	        return Attempt::Transient {
660	            value: PypiRemote::Indeterminate(ProviderIndeterminateCause::MalformedResponse),
661	            retry_after: None,
662	        };
663	    };
664	    let files: Vec<_> = index
665	        .files
666	        .into_iter()
667	        .filter(|file| pypi_simple_file_matches(file, version))
668	        .collect();
669	    Attempt::Settled(if files.is_empty() {
670	        PypiRemote::Absent
671	    } else {
672	        PypiRemote::Files(files)
673	    })
674	}
675	
676	/// Classifies one `curl -sS -i` run against the simple index. A private index
677	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
678	/// inside `on_ok` and reads as `MalformedResponse`, same as any other body PEP
679	/// 691 JSON parsing cannot make sense of.
680	///
681	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
682	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
683	fn classify_pypi_status<T>(
684	    output: &CommandOutput,
685	    on_ok: impl FnOnce(&str) -> Attempt<T>,
686	    absent: T,
687	    indeterminate: impl Fn(ProviderIndeterminateCause) -> T,
688	) -> Attempt<T> {
689	    let response = match parse_http_response(&output.stdout) {
690	        Ok(response) => response,
691	        Err(_) if !output.success() => {
692	            return Attempt::Transient {
693	                value: indeterminate(ProviderIndeterminateCause::CommandFailed),
694	                retry_after: None,
695	            }
696	        }
697	        Err(_) => {
698	            return Attempt::Transient {
699	                value: indeterminate(ProviderIndeterminateCause::MalformedResponse),
700	                retry_after: None,
701	            }
702	        }
703	    };
704	    match response.status {
705	        200 => on_ok(&response.body),
706	        404 => Attempt::Settled(absent),
707	        status if response.is_transient() => Attempt::Transient {
708	            value: indeterminate(ProviderIndeterminateCause::ProviderStatus { status }),
709	            retry_after: response.retry_after(),
710	        },
711	        status => Attempt::Settled(indeterminate(ProviderIndeterminateCause::ProviderStatus { status })),
712	    }
713	}
714	
715	fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
716	    classify_pypi_status(
717	        output,
718	        |body| classify_pypi_simple_body(body, version),
719	        ProviderObservationV1::Absent,
720	        |cause| ProviderObservationV1::Indeterminate { cause },
721	    )
722	}
723	
724	fn classify_pypi_files(output: &CommandOutput, version: &Version) -> Attempt<PypiRemote> {
725	    classify_pypi_status(
726	        output,
727	        |body| classify_pypi_files_body(body, version),
728	        PypiRemote::Absent,
729	        PypiRemote::Indeterminate,
730	    )
731	}
