734	    /// One `curl` of the project's simple index; `Err` when the command could not run at all.
735	    fn fetch_once(
736	        context: &ProviderContext<'_>,
737	        operation: &RegistryPublishOperation,
738	    ) -> Result<Result<CommandOutput, policy::CommandUnavailable>, GraphError> {
739	        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
740	        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
741	        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
742	        run_observation(
743	            context.runner(),
744	            programs::CURL,
745	            &args,
746	            context.root(),
747	            timeouts::REGISTRY_QUERY,
748	            false,
749	        )
750	    }
751	
752	    /// The release's files on the index, retried on a transient failure.
753	    fn remote(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<PypiRemote, GraphError> {
754	        policy::retry_observation(context.sleeper(), || {
755	            Ok(match Self::fetch_once(context, operation)? {
756	                Ok(output) => classify_pypi_files(&output, &operation.version),
757	                Err(_unavailable) => Attempt::Transient {
758	                    value: PypiRemote::Indeterminate(ProviderIndeterminateCause::CommandFailed),
759	                    retry_after: None,
760	                },
761	            })
762	        })
763	    }
764	
765	    /// The files of this release, once per run: the build job's sealed set when the manifest has one, else a build.
766	    fn built_set(
767	        context: &ProviderContext<'_>,
768	        id: &ReleaseOperationId,
769	        operation: &RegistryPublishOperation,
770	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
771	    ) -> Result<Arc<BuiltSet>, GraphError> {
772	        let sets = context.file_sets().ok_or_else(|| GraphError::ReleaseInvariant {
773	            detail: "a Python release needs the per-run file set cache".to_string(),
774	        })?;
775	        sets.get_or_build(
776	            (operation.package_dir.clone(), operation.version.render().to_string()),
777	            || match artifacts.and_then(|artifacts| artifacts.sealed_files(&id.package, &operation.version)) {
778	                Some(files) => BuiltSet::sealed(
779	                    files
780	                        .into_iter()
781	                        .map(|file| BuiltFile {
782	                            filename: file.filename,
783	                            path: file.path,
784	                            sha256: file.sha256,
785	                        })
786	                        .collect(),
787	                    &operation.package_name,
788	                    &operation.version,
789	                ),
790	                None => {
791	                    if artifacts.is_some() {
792	                        eprintln!(
793	                            "warning: the artifact manifest does not seal {} {}; building it in this job",
794	                            operation.package_name,
795	                            operation.version.render()
796	                        );
797	                    }
798	                    Self::build_set(context, operation)
799	                }
800	            },
801	        )
802	    }
803	
804	    /// Builds the sdist and wheel into a fresh directory, so a stale `dist/` can never reach the upload.
805	    fn build_set(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<BuiltSet, GraphError> {
806	        let dir = tempfile::tempdir().map_err(|error| {
807	            GraphError::Command(callisto_model::CommandError::Io {
808	                program: "python -m build".to_string(),
809	                message: error.to_string(),
810	            })
811	        })?;
812	        Self::build_into(context, operation, dir.path())?;
813	        BuiltSet::from_dir(dir, &operation.package_name, &operation.version)
814	    }
815	
816	    /// Runs the build into `outdir`, with file timestamps pinned to the release commit.
817	    pub(crate) fn build_into(
818	        context: &ProviderContext<'_>,
819	        operation: &RegistryPublishOperation,
820	        outdir: &std::path::Path,
821	    ) -> Result<(), GraphError> {
822	        let epoch = callisto_model::vcs::GitAccess::new(context.root(), context.runner()).commit_time("HEAD")?;
823	        let build = registry_argv::pypi_build_argv(context.root(), &operation.package_dir, outdir, epoch)?;
824	        let built = run_build_argv(context, &build)?;
825	        if built.exit_code != Some(0) {
826	            return Err(GraphError::ReleaseCommand {
827	                program: build.program.clone(),
828	                args: build.args.clone(),
829	                failure: CommandFailure::NonZeroExit {
830	                    exit_code: built.exit_code,
831	                    stderr: built.stderr,
832	                },
833	            });
834	        }
835	        Ok(())
836	    }
837	}
838	
839	/// Files on the index that no build of this release declared are never checked, but they are worth a line.
840	fn warn_about_extra_files(operation: &RegistryPublishOperation, extras: &[&str]) {
841	    if !extras.is_empty() {
842	        eprintln!(
843	            "warning: the index lists {} for {} {}, which this release did not build; it is not checked",
844	            extras.join(", "),
845	            operation.package_name,
846	            operation.version.render()
847	        );
848	    }
849	}
850	
851	impl RegistryEcosystem for PypiRegistry {
852	    /// PyPI's own JSON simple index (PEP 691) answers exactly like every
853	    /// other registry: 200 with the version present or absent, 404 for an
854	    /// unknown project. `pip` cannot observe this; `curl` against the index
855	    /// directly can.
856	    fn can_observe_versions(&self) -> bool {
857	        true
858	    }
859	
860	    fn observe_once(
861	        &self,
862	        context: &ProviderContext<'_>,
863	        operation: &RegistryPublishOperation,
864	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
865	        let output = match Self::fetch_once(context, operation)? {
866	            Ok(output) => output,
867	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
868	        };
869	        Ok(classify_pypi_simple(&output, &operation.version))
870	    }
871	
872	    /// No file on the index needs no build; any file means a partial release, so a build says which are missing.
873	    fn preflight(
874	        &self,
875	        context: &ProviderContext<'_>,
876	        id: &ReleaseOperationId,
877	        operation: &RegistryPublishOperation,
878	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
879	    ) -> Result<ReleasePreflight, GraphError> {
880	        let remote = match Self::remote(context, operation)? {
881	            PypiRemote::Absent => return Ok(proceed()),
882	            PypiRemote::Indeterminate(cause) => {
883	                return Err(GraphError::ReleaseProviderIndeterminate {
884	                    operation: Box::new(id.clone()),
885	                    cause,
886	                })
887	            }
888	            PypiRemote::Files(remote) => remote,
889	        };
890	        let set = Self::built_set(context, id, operation, artifacts)?;
891	        let comparison = pypi_files::compare(&set, &remote);
892	        warn_about_extra_files(operation, &comparison.extras);
893	        if let Some(filename) = comparison.differing.first() {
894	            return Err(GraphError::PypiFileDiffers {
895	                filename: (*filename).to_string(),
896	            });
897	        }
898	        if !comparison.yanked.is_empty() {
899	            return preflight_from_observation(
900	                ProviderObservationV1::Conflict {
901	                    reason: ProviderConflictReason::RegistryVersionYanked,
902	                },
903	                id,
904	                RemoteConflict::RegistryVersionDiffers,
905	            );
906	        }
907	        if comparison.is_complete() {
908	            return preflight_from_observation(
909	                exact_version(&operation.version),
910	                id,
911	                RemoteConflict::RegistryVersionDiffers,
912	            );
913	        }
914	        Ok(proceed())
915	    }
916	
917	    /// Uploads only the files the index lacks, named one by one: a file already there is never offered again.
918	    fn publish(
919	        &self,
920	        context: &ProviderContext<'_>,
921	        id: &ReleaseOperationId,
922	        operation: &RegistryPublishOperation,
923	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
924	    ) -> Result<CommandOutput, GraphError> {
925	        let set = Self::built_set(context, id, operation, artifacts)?;
926	        let remote = match Self::remote(context, operation)? {
927	            PypiRemote::Absent => Vec::new(),
928	            PypiRemote::Files(remote) => remote,
929	            PypiRemote::Indeterminate(cause) => {
930	                return Err(GraphError::ReleaseProviderIndeterminate {
931	                    operation: Box::new(id.clone()),
932	                    cause,
933	                })
934	            }
935	        };
936	        let comparison = pypi_files::compare(&set, &remote);
937	        if let Some(filename) = comparison.differing.first() {
938	            return Err(GraphError::PypiFileDiffers {
939	                filename: (*filename).to_string(),
940	            });
941	        }
942	        if !comparison.yanked.is_empty() {
943	            return Err(GraphError::ReleaseRemoteConflict {
944	                conflict: RemoteConflict::RegistryVersionDiffers,
945	            });
946	        }
947	        let missing: Vec<&BuiltFile> = set
948	            .files
949	            .iter()
950	            .filter(|file| comparison.missing.contains(&file.filename.as_str()))
951	            .collect();
952	        if missing.is_empty() {
953	            return Ok(CommandOutput {
954	                exit_code: Some(0),
955	                stdout: String::new(),
956	                stderr: String::new(),
957	            });
958	        }
959	        set.recheck(&missing)?;
960	        let paths: Vec<_> = missing.iter().map(|file| file.path.clone()).collect();
961	        let upload = registry_argv::pypi_upload_argv(
962	            context.root(),
963	            &operation.package_dir,
964	            operation.registry.endpoint.as_deref(),
965	            &paths,
966	        );
967	        let output = run_pypi_upload_argv(context, &upload)?;
968	        if output.success() {
969	            set.mark_uploaded(&missing);
970	        }
971	        Ok(output)
972	    }
973	
974	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
975	        registry_argv::classify_twine_output(output)
976	    }
977	
978	    /// Waits for every file to be on the index; a sealed or uploaded file must carry the bytes it was sealed or sent with.
979	    fn confirm(
980	        &self,
981	        context: &ProviderContext<'_>,
982	        id: &ReleaseOperationId,
983	        operation: &RegistryPublishOperation,
984	        published: bool,
985	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
986	    ) -> Result<ProviderObservationV1, GraphError> {
987	        let set = Self::built_set(context, id, operation, artifacts)?;
988	        let observe = || -> Result<ProviderObservationV1, GraphError> {
989	            Ok(match Self::remote(context, operation)? {
990	                PypiRemote::Indeterminate(cause) => ProviderObservationV1::Indeterminate { cause },
991	                PypiRemote::Absent => ProviderObservationV1::Absent,
992	                PypiRemote::Files(remote) => {
993	                    let comparison = pypi_files::compare(&set, &remote);
994	                    if !comparison.yanked.is_empty() {
995	                        ProviderObservationV1::Conflict {
996	                            reason: ProviderConflictReason::RegistryVersionYanked,
997	                        }
998	                    } else if let Some(filename) = comparison.differing.first() {
999	                        return Err(GraphError::PypiFileDiffers {
1000	                            filename: (*filename).to_string(),
1001	                        });
1002	                    } else if comparison.missing.is_empty() {
1003	                        exact_version(&operation.version)
1004	                    } else {
1005	                        ProviderObservationV1::Absent
1006	                    }
1007	                }
1008	            })
1009	        };
1010	        if published {
1011	            policy::observe_until_visible(context.sleeper(), observe)
1012	        } else {
1013	            observe()
1014	        }
1015	    }
1016	}
1017	
1018	/// Builds the sdist and wheel of a Python publish into `outdir`, for a build job that seals them.
1019	pub(crate) fn build_python_into(
1020	    context: &ProviderContext<'_>,
1021	    operation: &RegistryPublishOperation,
1022	    outdir: &std::path::Path,
1023	) -> Result<(), GraphError> {
1024	    PypiRegistry::build_into(context, operation, outdir)
1025	}
1026	
1027	/// The plan-time gate: an ecosystem whose client cannot prove a version absent
1028	/// could never mint the absence proof an effect needs, nor the exact evidence a
1029	/// receipt needs, so the plan is refused here rather than at dispatch.
1030	pub(crate) fn require_observable_registry(ecosystem: Ecosystem) -> Result<(), GraphError> {
1031	    if !adapter_for(ecosystem)?.can_observe_versions() {
1032	        return Err(GraphError::ReleasePreconditionUnmet {
1033	            requirement: ReleasePreconditionRequirement::ObservableRegistryClient,
1034	        });
1035	    }
1036	    Ok(())
