64	                Some(path.to_string_lossy().into_owned())
65	            }
66	            ReleaseNotes::Generated { reason } => {
67	                eprintln!("{}", generated_notes_notice(&request.id.package, *reason));
68	                None
69	            }
70	        };
71	        let create_args = release_create_args(operation, &repository, notes_file.as_deref());
72	        run_gh(context, &create_args, timeouts::FORGE_RELEASE_CREATE)?;
73	        confirmed_evidence(
74	            observe_until_visible(context.sleeper(), || {
75	                observed_forge_release(
76	                    context,
77	                    &operation.tag,
78	                    operation.prerelease,
79	                    &repository,
80	                    Draft::Either,
81	                )
82	            })?,
