89	/// `gh release create` for a draft: the changelog section when `notes_file` is set, else generated notes.
90	fn release_create_args<'a>(
91	    operation: &'a ForgeReleaseOperation,
92	    repository: &'a str,
93	    notes_file: Option<&'a str>,
94	) -> Vec<&'a str> {
95	    let mut args = vec![
