139	    fn observe(
140	        &self,
141	        context: &ProviderContext<'_>,
142	        request: &ProviderRequest<'_>,
143	    ) -> Result<ProviderObservationV1, GraphError> {
144	        let operation = publish_operation(request)?;
145	        let repository = context.github_repository_slug()?;
146	        observed_forge_release(
147	            context,
148	            &operation.tag,
149	            operation.prerelease,
150	            &repository,
151	            Draft::PublishedOnly,
152	        )
153	    }
154	
155	    fn publish(
156	        &self,
157	        context: &ProviderContext<'_>,
158	        request: &ProviderRequest<'_>,
159	        _effect: &EffectAuthorization<'_>,
160	    ) -> Result<ExactEvidence, GraphError> {
161	        let operation = publish_operation(request)?;
162	        let repository = context.github_repository_slug()?;
163	        // `gh release edit` looks the draft up the same way.
164	        confirmed_evidence(
165	            observe_until_visible(context.sleeper(), || {
166	                observed_forge_release(
167	                    context,
168	                    &operation.tag,
169	                    operation.prerelease,
170	                    &repository,
171	                    Draft::Either,
172	                )
173	            })?,
174	            request.id,
175	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
176	        )?;
177	        run_gh(
178	            context,
179	            &[
180	                "release",
181	                "edit",
182	                operation.tag.as_str(),
183	                "--repo",
184	                repository.as_str(),
185	                "--draft=false",
186	            ],
187	            timeouts::FORGE_RELEASE_CREATE,
188	        )?;
189	        confirmed_evidence(
190	            observe_until_visible(context.sleeper(), || {
191	                observed_forge_release(
192	                    context,
193	                    &operation.tag,
194	                    operation.prerelease,
195	                    &repository,
196	                    Draft::PublishedOnly,
197	                )
198	            })?,
