38	/// Coordinator-owned identity used to bind a product artifact to the exact
39	/// workflow revision that built it. This is distinct from a historic release
40	/// source during recovery.
41	#[derive(Clone, Debug)]
42	pub struct ArtifactBuildPolicy {
43	    pub repository: GitHubRepository,
44	    pub workflow_path: String,
45	    pub workflow_commit: CommitSha,
46	}
