48	pub(crate) type DerivedReleaseInputs = (
49	    ReleaseInputSnapshotV1,
50	    Vec<ReleaseOperation>,
51	    BTreeMap<ReleaseOperationId, PreparedOperation>,
52	    Option<PreparedGitRemote>,
