61	/// Whether a missing `origin` push URL fails derivation or leaves tags unbound.
62	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
63	pub(crate) enum GitRemoteRequirement {
64	    Required,
65	    /// A preview only: tag operations are derived without a remote identity.
66	    OptionalForPreview,
