203	fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
204	    workspace: &Workspace<'_, R, D>,
205	    decision: &ReleaseDecisionV1,
206	    source: SourceIdentity,
207	    artifact_policy: Option<&ArtifactBuildPolicy>,
208	    remote: GitRemoteRequirement,
209	    diagnostics: &mut Vec<Diagnostic>,
210	) -> Result<DerivedReleaseInputs, GraphError> {
211	    if workspace
212	        .config
213	        .product_release
214	        .as_ref()
215	        .is_some_and(|release| release.forge_repository.is_none())
216	    {
217	        return Err(GraphError::ReleaseForgeRepositoryMissing);
218	    }
219	    let mut package_inputs = Vec::new();
220	    let Selection {
221	        selected,
222	        package_ids,
223	        owners,
224	    } = select_packages(workspace, decision)?;
225	    require_dependencies_selected(workspace, &selected, &package_ids)?;
226	    let all_packages: Vec<_> = workspace.graph.packages().map(|package| package.id.clone()).collect();
227	    let publish_edges = PublishEdgeFilter::new(
228	        &package_ids.keys().cloned().collect(),
229	        &all_packages,
230	        |id: &callisto_model::PackageId| {
231	            workspace
232	                .graph
233	                .dependencies_of(id)
234	                .map(|edge| (edge.to.clone(), edge.kind))
235	                .collect()
236	        },
237	    )?;
238	
239	    let git_remote = prepare_remote(workspace, &selected, artifact_policy, remote)?;
240	
241	    let mut ops = Ops::default();
242	    build_publish_leaves(workspace, &selected, git_remote.as_ref(), &mut package_inputs, &mut ops)?;
243	    link_publish_prerequisites(workspace, &selected, &package_ids, &publish_edges, &mut ops)?;
244	    add_tags(&selected, &package_ids, &owners, &source, &mut ops)?;
245	    add_forge_releases(workspace, &selected, &owners, &mut ops)?;
246	    let artifact_slots = add_artifact_uploads(workspace, &selected, &owners, artifact_policy, &mut ops, diagnostics)?;
247	    add_forge_publishes(&selected, &owners, &mut ops)?;
248	
249	    Ok((
250	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
251	        canonical_operation_order(ops.operations)?,
252	        ops.prepared,
253	        git_remote,
254	        artifact_slots,
255	    ))
256	}
257	
258	fn select_packages<'w, R: CommandRunner, D: DependencyResolver>(
259	    workspace: &'w Workspace<'_, R, D>,
260	    decision: &ReleaseDecisionV1,
261	) -> Result<Selection<'w>, GraphError> {
262	    let mut selected = BTreeMap::new();
263	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
264	    let mut owners = Owners::new();
265	    for package in workspace.graph.packages() {
266	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
267	        if let Some(owner) = ids
268	            .iter()
269	            .find(|id| decision.entries.iter().any(|entry| &entry.package == *id))
270	        {
271	            owners.insert(package.id.clone(), owner.clone());
272	        }
273	        // One canonical manifest per ecosystem is the expected shape, but
274	        // dedup defensively -- `release_package_ids` maps every canonical
275	        // manifest, and two manifests sharing an ecosystem would otherwise
276	        // select/push the same identity twice.
277	        for id in ids.into_iter().collect::<BTreeSet<_>>() {
278	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
279	                selected.insert(id.clone(), (package, entry.target_version.clone()));
280	                package_ids.entry(package.id.clone()).or_default().push(id);
281	            }
282	        }
283	    }
284	    for entry in &decision.entries {
285	        let id = &entry.package;
286	        if !selected.contains_key(id) {
287	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
288	        }
289	    }
290	    Ok(Selection {
291	        selected,
292	        package_ids,
293	        owners,
294	    })
295	}
296	
297	fn prepare_remote<R: CommandRunner, D: DependencyResolver>(
298	    workspace: &Workspace<'_, R, D>,
299	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
300	    artifact_policy: Option<&ArtifactBuildPolicy>,
301	    remote: GitRemoteRequirement,
302	) -> Result<Option<PreparedGitRemote>, GraphError> {
303	    let requires_git_remote = selected.values().any(|(package, _)| {
304	        package
305	            .publish_to
306	            .iter()
307	            .any(|target| !matches!(target, PublishTarget::None))
308	    });
309	    let git_remote = match (requires_git_remote, remote) {
310	        (false, _) => None,
311	        (true, GitRemoteRequirement::Required) => Some(prepared_git_remote(&workspace.root, workspace.runner)?),
312	        (true, GitRemoteRequirement::OptionalForPreview) => optional_git_remote(&workspace.root, workspace.runner)?,
313	    };
314	    if let Some(policy) = artifact_policy {
315	        let remote = git_remote
316	            .as_ref()
317	            .and_then(|remote| remote.github_repository.as_ref())
318	            .ok_or(GraphError::ReleasePreconditionUnmet {
319	                requirement: ReleasePreconditionRequirement::GitHubRemote,
320	            })?;
321	        if remote != &policy.repository {
322	            return Err(GraphError::ReleaseArtifactRepositoryMismatch {
323	                configured: policy.repository.clone(),
324	                remote: remote.clone(),
325	            });
326	        }
327	    }
328	    Ok(git_remote)
329	}
330	
331	/// One registry publish per package target, with its platform publishes, and each package's input fingerprint.
332	fn build_publish_leaves<R: CommandRunner, D: DependencyResolver>(
333	    workspace: &Workspace<'_, R, D>,
334	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
335	    git_remote: Option<&PreparedGitRemote>,
336	    package_inputs: &mut Vec<ReleasePackageInputV1>,
337	    ops: &mut Ops,
338	) -> Result<(), GraphError> {
339	    let Ops {
340	        operations,
341	        prepared,
342	        index: OpIndex {
343	            publishes_by_package,
344	            platforms_by_publish,
345	            ..
346	        },
347	    } = ops;
348	
349	    // First construct leaves so dependency prerequisites can refer only to
350	    // exact selected release identities, never PackageId's wildcard matcher.
351	    for (id, (package, version)) in selected {
352	        let produces_tag = package
353	            .publish_to
354	            .iter()
355	            .any(|target| !matches!(target, PublishTarget::None));
356	        let fingerprint = package_fingerprint(
357	            workspace,
358	            id,
359	            package,
360	            version,
361	            produces_tag.then_some(git_remote).flatten(),
362	        )?;
363	        package_inputs.push(ReleasePackageInputV1 {
364	            package: id.clone(),
365	            fingerprint,
366	        });
367	
368	        let mut publishes = Vec::new();
369	        for target in &package.publish_to {
370	            if !target.is_implemented() {
371	                return Err(GraphError::PublishTargetNotImplemented {
372	                    package: id.clone(),
373	                    target: target.config_str(),
374	                });
375	            }
376	            if target.ecosystem() == Some(id.ecosystem()) {
377	                super::provider::registry::require_observable_registry(id.ecosystem())?;
378	                let binding = prepared_registry_binding(workspace, target, &package.id)?;
379	                let binding_id = RegistryBindingId::new(binding.key.as_str(), binding.identity.clone())?;
380	                let operation =
381	                    ReleaseOperation::registry_publish(id.clone(), version.clone(), binding_id.clone(), Vec::new())?;
382	                // A durable registry operation must have one exact endpoint
383	                // binding. The model-level operation identity currently has
384	                // only a registry key, so reject a second target that would
385	                // collapse to the same operation until the typed binding
386	                // identity is added there.
387	                if prepared.contains_key(operation.id()) {
388	                    return Err(GraphError::ReleaseSelectionInvalid {
389	                        package: id.clone(),
390	                        reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
391	                    });
392	                }
393	                let explicit_access = match target {
394	                    PublishTarget::Npm { access, .. } => *access,
395	                    _ => None,
396	                };
397	                let npm_tag = matches!(target, PublishTarget::Npm { .. })
398	                    .then(|| version.is_prerelease().then_some("next".to_string()))
399	                    .flatten();
400	                if matches!(target, PublishTarget::Npm { .. }) {
401	                    let mut platform_ids = Vec::new();
402	                    for (name, manifest) in workspace.identity.attached_platforms(package) {
403	                        let directory = manifest.parent().unwrap_or(std::path::Path::new(""));
404	                        let platform = PlatformPackageV1::new(
405	                            ReleasePackageId::new(callisto_model::Ecosystem::Npm, name)?,
406	                            directory.to_string_lossy().replace('\\', "/"),
407	                        )?;
408	                        let platform_operation = ReleaseOperation::new(
409	                            callisto_model::ReleaseOperationId::platform_publish(
410	                                id.clone(),
411	                                version.clone(),
412	                                binding_id.clone(),
413	                                platform,
414	                            ),
415	                            Vec::new(),
416	                        )?;
417	                        prepared.insert(
418	                            platform_operation.id().clone(),
419	                            PreparedOperation::RegistryPublish(RegistryPublishOperation {
420	                                package_dir: directory.to_path_buf(),
421	                                package_name: name.to_string(),
422	                                version: version.clone(),
423	                                registry: prepared_registry_binding(workspace, target, &package.id)?,
424	                                npm_access: npm_default_access(name, explicit_access),
425	                                npm_tag: npm_tag.clone(),
426	                                by_directory: true,
427	                            }),
428	                        );
429	                        platform_ids.push(platform_operation.id().clone());
430	                        operations.insert(platform_operation.id().clone(), platform_operation);
431	                    }
432	                    platforms_by_publish.insert(operation.id().clone(), platform_ids);
433	                }
434	                prepared.insert(
435	                    operation.id().clone(),
436	                    PreparedOperation::RegistryPublish(RegistryPublishOperation {
437	                        package_dir: package_dir(package)?,
438	                        package_name: id.name().to_string(),
439	                        version: version.clone(),
440	                        registry: binding,
441	                        npm_access: matches!(target, PublishTarget::Npm { .. })
442	                            .then(|| npm_default_access(id.name(), explicit_access))
443	                            .flatten(),
444	                        npm_tag,
445	                        by_directory: false,
446	                    }),
447	                );
448	                publishes.push(operation.id().clone());
449	                operations.insert(operation.id().clone(), operation);
450	            }
451	        }
452	        publishes.sort();
453	        publishes_by_package.insert(id.clone(), publishes);
454	    }
455	    Ok(())
456	}
457	
458	/// Replaces each publish leaf with prerequisites from selected dependency packages.
459	fn link_publish_prerequisites<R: CommandRunner, D: DependencyResolver>(
460	    workspace: &Workspace<'_, R, D>,
461	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
462	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
463	    publish_edges: &PublishEdgeFilter,
464	    ops: &mut Ops,
465	) -> Result<(), GraphError> {
466	    let Ops {
467	        operations,
468	        index: OpIndex {
469	            publishes_by_package,
470	            platforms_by_publish,
471	            ..
472	        },
473	        ..
474	    } = ops;
475	
476	    // Replace each publish leaf with prerequisites from selected dependency
477	    // packages, ordered by the shared publish edge filter.
478	    for (id, (package, _)) in selected {
479	        let mut prerequisites = BTreeSet::new();
480	        for edge in workspace.graph.dependencies_of(&package.id) {
481	            if !publish_edges.allows(&package.id, &edge.to, edge.kind) {
482	                continue;
483	            }
484	            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
485	                prerequisites.extend(
486	                    publishes_by_package
487	                        .get(dependency_release_id)
488	                        .into_iter()
489	                        .flatten()
490	                        .cloned(),
491	                );
492	            }
493	        }
494	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
495	            let operation = operations.get(publish_id).expect("publish operation was constructed");
496	            let mut prerequisites = prerequisites.clone();
497	            prerequisites.extend(platforms_by_publish.get(publish_id).into_iter().flatten().cloned());
498	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.into_iter().collect())?;
499	            operations.insert(publish_id.clone(), replacement);
500	        }
501	    }
502	    Ok(())
503	}
504	
505	fn add_tags(
506	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
507	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
508	    owners: &Owners,
509	    source: &SourceIdentity,
510	    ops: &mut Ops,
511	) -> Result<(), GraphError> {
512	    let Ops {
513	        operations,
514	        prepared,
515	        index,
516	    } = ops;
517	
518	    for (id, (package, version)) in owned(selected, owners) {
519	        if !package
520	            .publish_to
521	            .iter()
522	            .any(|target| !matches!(target, PublishTarget::None))
523	        {
524	            continue;
525	        }
526	        let tag = ReleaseOperation::tag(
527	            id.clone(),
528	            version.clone(),
529	            index.tag_prerequisites(
530	                package_ids
531	                    .get(&package.id)
532	                    .map_or(std::slice::from_ref(id), Vec::as_slice),
533	            ),
534	        )?;
535	        let tag_name = package
536	            .tag_template
537	            .clone()
538	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
539	            .render(version);
540	        let target = match source {
541	            SourceIdentity::GitCommit { sha } => sha.clone(),
542	            SourceIdentity::HermeticContent { .. } => {
543	                return Err(GraphError::UnsupportedRelease {
544	                    feature: UnsupportedReleaseFeature::SourceIdentity,
545	                })
546	            }
547	        };
548	        prepared.insert(
549	            tag.id().clone(),
550	            PreparedOperation::Tag(TagOperation {
551	                annotation: format!("Release {tag_name}"),
552	                name: tag_name,
553	                target,
554	            }),
555	        );
556	        index.tag_by_package.insert(id.clone(), tag.id().clone());
557	        operations.insert(tag.id().clone(), tag);
558	    }
