810	/// derivation would silently yield zero artifact slots.
811	fn require_product_package_publishes_to_forge<R: CommandRunner, D: DependencyResolver>(
812	    workspace: &Workspace<'_, R, D>,
813	    product: &callisto_model::PackageId,
814	) -> Result<(), GraphError> {
815	    let mut found = false;
816	    for package in workspace.graph.packages() {
817	        if !workspace.identity.identifies(product, &package.id) {
818	            continue;
819	        }
820	        found = true;
821	        if package
822	            .publish_to
823	            .iter()
824	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
825	        {
826	            return Ok(());
827	        }
828	    }
829	    let detail = if found {
830	        format!("product-package `{product}` does not publish to github-release")
831	    } else {
832	        format!("product-package `{product}` is not a package in this workspace")
833	    };
834	    Err(crate::error::ConfigError::InvalidProductRelease { detail }.into())
835	}
