928	pub(crate) fn canonical_operation_order(
929	    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
930	) -> Result<Vec<ReleaseOperation>, GraphError> {
931	    let mut remaining: BTreeMap<_, usize> = operations
932	        .iter()
933	        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
934	        .collect();
935	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
936	    for (id, operation) in &operations {
937	        for prerequisite in operation.prerequisites() {
938	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
939	        }
940	    }
941	    let mut ready: BTreeSet<_> = remaining
942	        .iter()
943	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
944	        .collect();
945	    let mut ordered = Vec::with_capacity(operations.len());
946	    while let Some(id) = ready.pop_first() {
947	        ordered.push(operations.get(&id).expect("known operation").clone());
948	        for dependent in dependents.get(&id).into_iter().flatten() {
949	            let count = remaining.get_mut(dependent).expect("known operation");
950	            *count -= 1;
951	            if *count == 0 {
952	                ready.insert(dependent.clone());
953	            }
954	        }
955	    }
956	    if ordered.len() != operations.len() {
957	        return Err(GraphError::ReleaseInvariant {
958	            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
959	                .to_string(),
960	        });
961	    }
962	    Ok(ordered)
963	}
