971	fn target_fingerprint<R: CommandRunner, D: DependencyResolver>(
972	    workspace: &Workspace<'_, R, D>,
973	    package: &callisto_model::PackageId,
974	    npm_name: &str,
975	    target: &PublishTarget,
976	) -> Result<SemanticInputDigest, GraphError> {
977	    let mut transcript = CanonicalTranscript::semantic_input_v1();
978	    // Single source of truth for the "kind" string, shared with
979	    // `PublishTarget::config_str`'s other diagnostic/config-parsing callers
980	    // instead of re-hardcoding these per-variant literals here too.
981	    transcript.push_str("target.kind", target.config_str());
982	    match target {
983	        PublishTarget::GitHubRelease | PublishTarget::None => {}
984	        PublishTarget::CratesIo => {
985	            push_registry_binding(
986	                &mut transcript,
987	                prepared_registry_binding(workspace, target, package)?.identity,
988	            )?;
989	        }
990	        PublishTarget::Npm { access, .. } => {
991	            push_registry_binding(
992	                &mut transcript,
993	                prepared_registry_binding(workspace, target, package)?.identity,
994	            )?;
995	            transcript.push_str(
996	                "target.access",
997	                match npm_default_access(npm_name, *access) {
998	                    Some(callisto_model::NpmAccess::Public) => "public",
999	                    Some(callisto_model::NpmAccess::Restricted) => "restricted",
1000	                    None => "default",
1001	                },
1002	            );
1003	        }
1004	        PublishTarget::Pypi { .. } | PublishTarget::NuGet { .. } => {
1005	            push_registry_binding(
1006	                &mut transcript,
1007	                prepared_registry_binding(workspace, target, package)?.identity,
1008	            )?;
1009	        }
1010	        #[allow(unreachable_patterns)]
1011	        _ => {
1012	            return Err(GraphError::UnsupportedRelease {
1013	                feature: UnsupportedReleaseFeature::PublishTarget,
1014	            })
1015	        }
1016	    }
1017	    Ok(SemanticInputDigest::from_transcript(&transcript))
1018	}
