1020	fn push_registry_binding(
1021	    transcript: &mut CanonicalTranscript,
1022	    fingerprint: RegistryBindingDigest,
1023	) -> Result<(), GraphError> {
1024	    transcript.push_str("target.registry", fingerprint.as_str());
1025	    Ok(())
1026	}
