353	/// Verifies the release roster a merged release commit claims, against a
354	/// release-decision file committed alongside it at `decision_path`.
355	///
356	/// This is intentionally *not* a second computation of changeset, fixed-group,
357	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
358	/// (via [`derive_release_decision`]) already computed that once, correctly,
359	/// when the release PR was generated -- and `callisto version --emit-decision`
360	/// commits its exact output alongside the manifest and changelog edits.
361	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
362	/// the kind of duplicated logic that drifts: an earlier version of this
363	/// function did just that, understood only a direct changeset match, and
364	/// rejected every real release in this repository once a fixed-group cascade
365	/// (a case its reimplementation never learned) touched an unnamed sibling.
366	///
367	/// Instead, this function reads the committed decision back and confirms the
368	/// commit's actual diff matches it exactly -- no more, no less.
369	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
370	/// entries don't match its content digest, so a hand-edited or corrupted
371	/// decision file fails before this function's own diff cross-check runs.
372	///
373	/// The caller must check out the exact merge commit in detached HEAD state
374	/// before creating an intent. GitHub-specific PR/approval provenance belongs
375	/// in the workflow boundary; this graph function verifies the local,
376	/// provider-neutral commit delta only.
377	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
378	    workspace: &Workspace<'_, R, D>,
379	    release_commit: &CommitSha,
380	    decision_path: &std::path::Path,
381	) -> Result<ReleaseDecisionV1, GraphError> {
382	    let head_args = ["rev-parse", "HEAD"];
383	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
384	    let head =
385	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
386	    if &head != release_commit {
387	        return Err(GraphError::ReleaseCommitVerificationFailed {
388	            commit: release_commit.clone(),
389	            reason: CommitVerificationFailure::HeadMismatch,
390	        });
391	    }
392	
393	    let parent_ref = format!("{}^", release_commit.as_str());
394	    let parent_args = ["rev-parse", parent_ref.as_str()];
395	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
396	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
397	
398	    let diff_tree_args = [
399	        "diff-tree",
400	        "--no-commit-id",
401	        "--name-status",
402	        "-r",
403	        "--no-renames",
404	        parent.as_str(),
405	        release_commit.as_str(),
406	    ];
407	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
408	    let changed = parse_name_status(&changed, &diff_tree_args)?;
409	
410	    // The decision must be freshly authored as part of *this* commit, not a
411	    // stale leftover an earlier release already committed and this one never
412	    // touched -- otherwise a commit that changes nothing real could still
413	    // carry forward a prior, unrelated decision's authority.
414	    let decision_path_str = normalized_git_path(decision_path)?;
415	    let decision_freshly_written = changed
416	        .iter()
417	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
418	    if !decision_freshly_written {
419	        return Err(GraphError::ReleaseCommitVerificationFailed {
420	            commit: release_commit.clone(),
421	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
422	        });
423	    }
424	
425	    // A cheap, independent sanity check that this commit is a real version
426	    // application and not just a hand-crafted decision file: some real
427	    // changeset was actually consumed. The decision's own entries, not this
428	    // changeset's content, remain the sole authority verified below.
429	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
430	    let consumed_a_changeset = changed
431	        .iter()
432	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
433	    if !consumed_a_changeset {
434	        return Err(GraphError::ReleaseCommitVerificationFailed {
435	            commit: release_commit.clone(),
436	            reason: CommitVerificationFailure::NoChangesetConsumed,
437	        });
438	    }
439	
440	    let decision_source = git_file(
441	        workspace.runner,
442	        &workspace.root,
443	        release_commit.as_str(),
444	        &decision_path_str,
445	    )?;
446	    let decision: ReleaseDecisionV1 =
447	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
448	            path: decision_path.to_path_buf(),
449	            message: error.to_string(),
450	        })?;
451	    let claimed = decision
452	        .entries
453	        .iter()
454	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
455	        .collect::<std::collections::BTreeMap<_, _>>();
456	
457	    let changed_paths = changed
458	        .iter()
459	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
460	        .collect::<std::collections::BTreeSet<_>>();
461	
462	    // Every canonical manifest path this workspace currently declares, in
463	    // the exact order `workspace.graph.packages()` and
464	    // `Package::canonical_manifests()` yield -- both are backed by ordered
465	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
466	    // the second traversal below visits the same (package, manifest) pairs
467	    // in the same order. That lets it zip the batched `before`/`after`
468	    // results back on by position instead of re-keying by path, which would
469	    // misbehave if two packages ever declared an identical manifest path.
470	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
471	        .graph
472	        .packages()
473	        .flat_map(Package::canonical_manifests)
474	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
475	        .collect::<Result<_, GraphError>>()?;
476	    let mut query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
477	    if manifest_queries
478	        .iter()
479	        .any(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
480	        && !query_paths.contains(&"Cargo.toml")
481	    {
482	        query_paths.push("Cargo.toml");
483	    }
484	
485	    // Exactly two `git cat-file --batch` subprocess invocations total (one
486	    // per commit), regardless of how many canonical manifests the
487	    // workspace has -- replaces what was previously 2*N separate `git
488	    // show` spawns (one `manifest_version_at` call per manifest per
489	    // commit).
490	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
491	    let after_blobs =
492	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
493	    let before_versions = resolve_batch_versions(before_blobs, &query_paths, &manifest_queries)?;
494	    let after_versions = resolve_batch_versions(after_blobs, &query_paths, &manifest_queries)?;
495	
496	    let mut observed = std::collections::BTreeSet::new();
497	    let mut manifest_index = 0usize;
498	    for package in workspace.graph.packages() {
499	        let package_ids = release_package_ids(&workspace.identity, package)?;
500	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
501	        if package_is_claimed {
502	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
503	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
504	            })?;
505	            let changelog = normalized_git_path(changelog)?;
506	            if !changed_paths.contains(changelog.as_str()) {
507	                return Err(GraphError::ReleaseCommitVerificationFailed {
508	                    commit: release_commit.clone(),
509	                    reason: CommitVerificationFailure::ChangelogNotTouched,
510	                });
511	            }
512	        }
513	        for id in package_ids {
514	            let before = &before_versions[manifest_index];
515	            let after = &after_versions[manifest_index];
516	            manifest_index += 1;
517	            let changed_version = before.version != after.version;
518	            match claimed.get(&id) {
519	                Some(target_version) => {
520	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
521	                        return Err(GraphError::ReleaseCommitVerificationFailed {
522	                            commit: release_commit.clone(),
523	                            reason: CommitVerificationFailure::ManifestNotInDiff,
524	                        });
525	                    }
526	                    if !changed_version || &after.version != target_version {
527	                        return Err(GraphError::ReleaseCommitVerificationFailed {
528	                            commit: release_commit.clone(),
529	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
530	                        });
531	                    }
532	                    observed.insert(id);
533	                }
534	                None => {
535	                    if changed_version {
536	                        // A changed version the committed decision never
537	                        // claimed is not this commit's authority -- fail
538	                        // closed rather than trust a partial match.
539	                        return Err(GraphError::ReleaseCommitVerificationFailed {
540	                            commit: release_commit.clone(),
541	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
542	                        });
543	                    }
544	                }
545	            }
546	        }
547	    }
548	    if observed.len() != claimed.len() {
549	        return Err(GraphError::ReleaseCommitVerificationFailed {
550	            commit: release_commit.clone(),
551	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
552	        });
553	    }
554	
555	    Ok(decision)
556	}
557	
558	fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
559	    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
560	        if changeset_dir.is_empty() {
561	            Some(path)
562	        } else {
563	            path.strip_prefix('/')
564	        }
565	    }) else {
566	        return false;
567	    };
568	
569	    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
570	}
571	
572	/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
573	/// exited non-zero, carrying its real exit status and stderr instead of
574	/// discarding them.
575	fn command_non_zero_exit(program: &str, args: &[&str], output: &callisto_model::CommandOutput) -> GraphError {
576	    GraphError::ReleaseCommand {
577	        program: program.to_string(),
578	        args: args.iter().map(|s| s.to_string()).collect(),
579	        failure: CommandFailure::NonZeroExit {
580	            exit_code: output.exit_code,
581	            stderr: output.stderr.clone(),
582	        },
583	    }
584	}
585	
586	/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
587	/// output could not be parsed into the shape this module expects.
588	fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
589	    GraphError::ReleaseCommand {
590	        program: program.to_string(),
591	        args: args.iter().map(|s| s.to_string()).collect(),
592	        failure: CommandFailure::MalformedOutput { detail: detail.into() },
593	    }
594	}
595	
596	fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
597	    let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
598	    if !output.success() {
599	        return Err(command_non_zero_exit("git", args, &output));
600	    }
601	    Ok(output.stdout_trimmed().to_string())
602	}
603	
604	fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
605	    output
606	        .lines()
607	        .map(|line| {
608	            let (status, path) = line.split_once('\t').ok_or_else(|| {
609	                command_malformed_output(
610	                    "git",
611	                    args,
612	                    format!("name-status line missing a tab separator: `{line}`"),
613	                )
614	            })?;
615	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
616	                return Err(command_malformed_output(
617	                    "git",
618	                    args,
619	                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
620	                ));
621	            }
622	            Ok((status.to_string(), path.to_string()))
623	        })
624	        .collect()
625	}
626	
627	fn git_file<R: CommandRunner>(
628	    runner: &R,
629	    root: &std::path::Path,
630	    commit: &str,
631	    path: &str,
632	) -> Result<String, GraphError> {
633	    let object = format!("{commit}:{path}");
634	    git_stdout(runner, root, &["show", &object])
635	}
636	
637	pub(super) fn normalized_git_path(path: &std::path::Path) -> Result<String, GraphError> {
638	    let path = callisto_model::workspace_relative(path)?;
639	    let path = path.to_string_lossy().into_owned();
640	    if path.contains(['\0', '\n', '\r']) {
641	        return Err(command_malformed_output(
642	            "git",
643	            &["cat-file", "--batch"],
644	            "workspace path contains a forbidden control character",
645	        ));
646	    }
647	    Ok(path)
648	}
