650	fn historical_manifest_error(error: callisto_model::ManifestError) -> GraphError {
651	    match error {
652	        callisto_model::ManifestError::InvalidVersion { source, .. } => GraphError::from(source),
653	        other => command_malformed_output("git", &["cat-file", "--batch"], other.to_string()),
654	    }
655	}
