197	        let object_format = self
198	            .runner
199	            .run("git", &["rev-parse", "--show-object-format"], &self.root)?;
200	        if !object_format.success() || object_format.stdout_trimmed() != "sha1" {
201	            return Err(VcsError::UnsupportedObjectFormat {
202	                found: object_format.stdout_trimmed().to_string(),
203	            });
204	        }
205	        let shallow = self
206	            .runner
207	            .run("git", &["rev-parse", "--is-shallow-repository"], &self.root)?;
208	        if !shallow.success() || shallow.stdout_trimmed() != "false" {
209	            return Err(VcsError::ShallowRepository);
210	        }
211	
212	        let head = self
213	            .runner
214	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
215	        if !head.success() {
216	            return Err(VcsError::Git(
217	                "could not resolve a commit for release trust".to_string(),
218	            ));
219	        }
220	        let head = CommitSha::parse(head.stdout_trimmed()).map_err(|error| VcsError::InvalidCommitSha {
221	            context: "for release trust".to_string(),
222	            message: error.to_string(),
223	        })?;
224	
225	        let symbolic_head = self
226	            .runner
227	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
228	        let head_disposition = match symbolic_head.exit_code {
229	            Some(0) => GitHeadDisposition::Attached,
230	            Some(1) => GitHeadDisposition::Detached,
231	            _ => {
232	                return Err(VcsError::Git(
233	                    "could not determine the symbolic HEAD state for release trust".to_string(),
234	                ))
235	            }
236	        };
237	
238	        let status = self.runner.run(
239	            "git",
240	            &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
241	            &self.root,
242	        )?;
243	        if !status.success() {
244	            return Err(VcsError::Git(
245	                "could not inspect the worktree for release trust".to_string(),
246	            ));
247	        }
248	        check_release_worktree_status(&status.stdout)?;
249	
250	        Ok(GitCommitTrustEvidence::new(canonical_root, head, head_disposition))
251	    }
252	}
