312	/// Maps a `git diff --raw` single-letter status to a [`StagedChangeKindV1`].
313	/// Any status this codebase does not have a named case for (Git's own docs
314	/// list `X` as "unknown") conservatively maps to `Unmerged`, which
315	/// [`crate::ReleasePrCommitPlanV1::from_changes`] always rejects --
316	/// safe by construction rather than by an exhaustive status list here.
317	fn staged_change_kind(status: char) -> StagedChangeKindV1 {
318	    match status {
319	        'A' => StagedChangeKindV1::Added,
320	        'M' => StagedChangeKindV1::Modified,
321	        'D' => StagedChangeKindV1::Deleted,
322	        'R' => StagedChangeKindV1::Renamed,
323	        'C' => StagedChangeKindV1::Copied,
324	        'T' => StagedChangeKindV1::TypeChanged,
325	        _ => StagedChangeKindV1::Unmerged,
326	    }
327	}
