329	fn canonical_git_root(raw_root: &str) -> Result<PathBuf, VcsError> {
330	    if raw_root.is_empty() {
331	        return Err(VcsError::InvalidRepositoryRoot {
332	            detail: "Git returned an empty repository root".to_string(),
333	        });
334	    }
335	    dunce::canonicalize(raw_root).map_err(|error| VcsError::InvalidRepositoryRoot {
336	        detail: format!("could not canonicalize `{raw_root}`: {error}"),
337	    })
338	}
