340	/// Ignored paths are build output and never block; tracked or untracked changes do.
341	fn check_release_worktree_status(status: &str) -> Result<(), VcsError> {
342	    match status.split('\0').find(|record| !record.is_empty()) {
343	        None => Ok(()),
344	        Some(record) => Err(VcsError::DirtyWorktree {
345	            path: record.get(3..).unwrap_or(record).to_string(),
346	        }),
347	    }
348	}
