351	    /// Returns the commit SHA that `HEAD` currently resolves to.
352	    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
353	        let output = self.runner.run("git", &["rev-parse", "HEAD"], &self.root)?;
354	        if !output.success() {
355	            return Err(VcsError::Git(format!(
356	                "`git rev-parse HEAD` failed in `{}`: {}",
357	                self.root.display(),
358	                output.redacted_stderr()
359	            )));
360	        }
361	        let sha_str = output.stdout_trimmed();
362	        CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
363	            context: format!("in `git rev-parse HEAD` output `{sha_str}`"),
364	            message: e.to_string(),
365	        })
366	    }
