368	    /// The committer time of `rev` in whole seconds since the epoch.
369	    pub fn commit_time(&self, rev: &str) -> Result<u64, VcsError> {
370	        let output = self.runner.run(
371	            "git",
372	            &["show", "-s", "--no-show-signature", "--format=%ct", rev],
373	            &self.root,
374	        )?;
375	        let stdout = output.stdout_trimmed();
376	        match stdout.parse::<u64>() {
377	            Ok(seconds) if output.success() => Ok(seconds),
378	            _ => Err(VcsError::Git(format!(
379	                "`git show -s --no-show-signature --format=%ct {rev}` failed in `{}`: {}",
380	                self.root.display(),
381	                output.redacted_stderr()
382	            ))),
383	        }
384	    }
385	
386	    /// Whether `path` (relative to this root) exists in `rev`'s tree.
387	    pub fn path_exists_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
388	        let spec = format!("{rev}:./{}", path.display());
389	        let output = self
390	            .runner
391	            .run("git", &["rev-parse", "--verify", "--quiet", &spec], &self.root)?;
392	        Ok(output.success())
393	    }
