395	    /// Files in `rev`'s tree matching one of `pathspecs` whose text contains `needle`, ignoring case.
396	    ///
397	    /// A revision that cannot be searched (not a commit, or objects missing) has no matches, as in
398	    /// [`Self::path_exists_at`].
399	    pub fn files_containing_at(&self, rev: &str, needle: &str, pathspecs: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
400	        let mut args = vec!["grep", "-l", "-z", "-F", "-i", "-e", needle, rev, "--"];
401	        args.extend_from_slice(pathspecs);
402	        let output = self.runner.run("git", &args, &self.root)?;
403	        if !output.success() {
404	            return Ok(Vec::new());
405	        }
406	        let prefix = format!("{rev}:");
407	        Ok(output
408	            .stdout
409	            .split('\0')
410	            .filter_map(|entry| entry.strip_prefix(&prefix))
411	            .map(PathBuf::from)
412	            .collect())
413	    }
414	
415	    /// The text of `path` (relative to this root) in `rev`'s tree, decoded lossily; `None` when it is absent.
416	    pub fn read_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
417	        let spec = format!("{rev}:./{}", path.display());
418	        let output = self.runner.run("git", &["show", &spec], &self.root)?;
419	        Ok(output.success().then_some(output.stdout))
420	    }
421	
422	    /// The most recent commit that added `path`, if it is committed.
423	    pub fn commit_adding(&self, path: &Path) -> Result<Option<String>, VcsError> {
424	        let path = path.to_string_lossy();
425	        let output = self.runner.run(
426	            "git",
427	            &["log", "--diff-filter=A", "--format=%H", "-1", "--", &path],
428	            &self.root,
429	        )?;
430	        let sha = output.stdout_trimmed();
431	        Ok((output.success() && !sha.is_empty()).then(|| sha.to_string()))
432	    }
