434	    /// Lists tag names, optionally filtered by `glob` (a [`globset::Glob`]
435	    /// pattern; `None` matches every tag).
436	    ///
437	    /// Always fetches the full tag list and filters locally with the same
438	    /// `globset` matcher `callisto-graph`'s `tags::matching_tags` uses, never
439	    /// `git tag --list <pattern>`'s different glob dialect.
440	    pub fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
441	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
442	        if !output.success() {
443	            // A directory with no `.git` anywhere in its ancestry is not a
444	            // hard failure -- it's the normal shape of a brand-new/pre-git
445	            // package, and callers (e.g. `status`) treat "no tags" as
446	            // "unreleased" rather than aborting. Any OTHER failure (a
447	            // corrupted or locked repository, a permissions error, ...)
448	            // must still surface as a real error rather than silently
449	            // becoming "zero tags".
450	            if !output.stderr.contains("not a git repository") {
451	                return Err(VcsError::Git(format!(
452	                    "`git tag --list` failed in `{}`: {}",
453	                    self.root.display(),
454	                    output.redacted_stderr()
455	                )));
456	            }
457	        }
458	        let all = output.stdout_lines().map(|s| s.to_string());
459	
460	        let matcher = glob.map(crate::vcs::compile_tag_glob).transpose()?;
461	
462	        Ok(all
463	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
464	            // A legal Git ref is not necessarily safe as a bare CLI positional (a leading `-`).
465	            .filter_map(|t| TagName::parse(&t).ok())
466	            .collect())
467	    }
