469	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
470	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
471	    /// callers treat as "no bound" / "infer over full history".
472	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
473	        let rev = format!("{refname}^{{commit}}");
474	        let output = self
475	            .runner
476	            .run("git", &["rev-parse", "--verify", "--quiet", &rev], &self.root)?;
477	
478	        if !output.success() {
479	            return Ok(None);
480	        }
481	        let sha_str = output.stdout_trimmed();
482	        if sha_str.is_empty() {
483	            return Ok(None);
484	        }
485	        Ok(CommitSha::parse(sha_str).ok())
486	    }
