488	    /// Lists non-merge commits reachable from `HEAD`, down to (exclusive)
489	    /// `since_ref` when given, keeping those that touch at least one of
490	    /// `pathspecs` (empty keeps every commit).
491	    ///
492	    /// `--full-history`: a commit touching a pathspec counts even when a
493	    /// later merge discarded its change (e.g. `merge -s ours`); default
494	    /// history simplification would silently drop it.
495	    ///
496	    /// A `since_ref` that is given but does not resolve is
497	    /// [`VcsError::RefNotFound`], never a silent unbounded walk.
498	    pub fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
499	        let mut args: Vec<String> = vec![
500	            "log".to_string(),
501	            "--no-merges".to_string(),
502	            "--full-history".to_string(),
503	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
504	        ];
505	
506	        match since_ref {
507	            Some(r) => args.push(format!("{r}..HEAD")),
508	            None => args.push("HEAD".to_string()),
509	        }
510	
511	        if !pathspecs.is_empty() {
512	            args.push("--".to_string());
513	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
514	        }
515	
516	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
517	        let output = self.runner.run("git", &arg_refs, &self.root)?;
518	
519	        if !output.success() {
520	            if let Some(r) = since_ref {
521	                if self.resolve_commit(r)?.is_none() {
522	                    return Err(VcsError::RefNotFound {
523	                        ref_name: r.to_string(),
524	                    });
525	                }
526	            }
527	            return Err(VcsError::Git(format!(
528	                "`git log` failed in `{}`: {}",
529	                self.root.display(),
530	                output.redacted_stderr()
531	            )));
532	        }
533	
534	        parse_git_log_output(&output.stdout, &self.root)
535	    }
