537	    /// Resolves every ref in `refs` to its commit with one `git rev-parse`.
538	    /// `None` when any of them does not resolve.
539	    pub fn resolve_commits(&self, refs: &[String]) -> Result<Option<Vec<CommitSha>>, VcsError> {
540	        let revs: Vec<String> = refs.iter().map(|r| format!("{r}^{{commit}}")).collect();
541	        let mut args = vec!["rev-parse"];
542	        args.extend(revs.iter().map(String::as_str));
543	        let output = self.runner.run("git", &args, &self.root)?;
544	        if !output.success() {
545	            return Ok(None);
546	        }
547	        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
548	        Ok(shas.filter(|shas| shas.len() == refs.len()))
549	    }
