551	    /// Paths, relative to the root and limited to it, that non-merge commits
552	    /// in `since_ref..HEAD` touched. Selects exactly what
553	    /// [`Self::commits_since`] filters on: `--full-history`, and a rename
554	    /// counts for both its old and new path.
555	    pub fn paths_changed_since(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
556	        let range = format!("{since_ref}..HEAD");
557	        self.name_only(&[
558	            "log",
