585	    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
586	        let output = self.runner.run("git", args, &self.root)?;
587	        if !output.success() {
588	            return Err(VcsError::Git(format!(
589	                "`git {}` failed in `{}`: {}",
590	                args[0],
591	                self.root.display(),
592	                output.redacted_stderr()
593	            )));
594	        }
595	        Ok(output
596	            .stdout
597	            .split('\0')
598	            .map(|path| path.trim_start_matches('\n'))
599	            .filter(|path| !path.is_empty())
600	            .map(PathBuf::from)
601	            .collect())
602	    }
