604	    /// Creates the tag `name` at `target_sha`: annotated with `message`
605	    /// when `Some`, lightweight when `None`. Fails if the tag already
606	    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
607	    pub fn create_tag(
608	        &self,
609	        name: &str,
610	        target_sha: &CommitSha,
611	        message: Option<&str>,
612	        sign: TagSignPolicy,
613	        _permit: &ApplyPermit,
614	    ) -> Result<(), VcsError> {
615	        let identity = match message {
616	            Some(_) => self.tagger_identity_override(target_sha)?,
617	            None => None,
618	        };
619	        let mut args: Vec<&str> = Vec::new();
620	        if let Some([name_config, email_config]) = &identity {
621	            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
622	        }
623	        // `--` ends option parsing so `name` can never be misread as a flag.
624	        args.push("tag");
625	        if let Some(msg) = message {
626	            args.extend(["-a", "-m", msg]);
627	        }
628	        if matches!(sign, TagSignPolicy::ForceUnsigned) {
629	            args.push("--no-sign");
630	        }
631	        args.extend(["--", name, target_sha.as_str()]);
632	        let output = self.runner.run("git", &args, &self.root)?;
633	        if !output.success() {
634	            return Err(VcsError::Git(format!(
635	                "`git tag` failed in `{}`: {}",
636	                self.root.display(),
637	                output.redacted_stderr()
638	            )));
639	        }
640	        Ok(())
641	    }
642	
643	    /// `None` when Git can resolve a committer identity itself. Otherwise the
644	    /// target commit's committer, as `-c` overrides, since an annotated tag
645	    /// needs a tagger and a release runner's checkout often configures none.
646	    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
647	        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
648	        if ident.success() {
649	            return Ok(None);
650	        }
651	        let commit = self
652	            .runner
653	            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
654	        let committer = commit
655	            .stdout
656	            .lines()
657	            .take_while(|line| !line.is_empty())
658	            .find_map(|line| line.strip_prefix("committer "))
659	            .and_then(|ident| ident.split_once(" <"))
660	            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
661	        match committer {
662	            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
663	                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
664	            }
665	            _ => Err(VcsError::Git(format!(
666	                "no Git identity for the tagger and could not read the committer of `{}`: {}",
667	                target_sha.as_str(),
668	                commit.redacted_stderr()
669	            ))),
670	        }
671	    }
