673	    /// Force-creates or -moves the floating tag `major_name` to
674	    /// `target_sha`. Writes a ref, so it requires an [`ApplyPermit`].
675	    pub fn create_floating_major(
676	        &self,
677	        major_name: &str,
678	        target_sha: &CommitSha,
679	        _permit: &ApplyPermit,
680	    ) -> Result<(), VcsError> {
681	        let output = self
682	            .runner
683	            .run("git", &["tag", "-f", "--", major_name, target_sha.as_str()], &self.root)?;
684	        if !output.success() {
685	            return Err(VcsError::Git(format!(
686	                "`git tag -f` failed in `{}`: {}",
687	                self.root.display(),
688	                output.redacted_stderr()
689	            )));
690	        }
691	        Ok(())
692	    }
