695	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
696	/// produced by [`GitAccess::commits_since`] into [`GitCommit`]s, splitting
697	/// each raw message on its first blank line into `summary`/`body`.
698	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
699	    let mut commits = Vec::new();
700	
701	    for record in stdout.split(RECORD_SEP) {
702	        // `tformat:`-style `--format=` output (the default when the format
703	        // string doesn't start with `format:`/`tformat:`) appends a
704	        // trailing newline after every entry; strip it rather than the
705	        // message's own content.
706	        let record = record.trim_end_matches('\n');
707	        if record.is_empty() {
708	            continue;
709	        }
710	
711	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
712	            return Err(VcsError::MalformedLogOutput {
713	                detail: format!(
714	                    "in `{}`: expected a `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
715	                    cwd.display()
716	                ),
717	            });
718	        };
719	
720	        let sha = CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
721	            context: format!("in `git log` output in `{}`", cwd.display()),
722	            message: e.to_string(),
723	        })?;
724	
725	        let message = message.replace("\r\n", "\n");
726	        let (summary, body) = match message.split_once("\n\n") {
727	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
728	            None => (message.trim_end().to_string(), None),
729	        };
730	
731	        commits.push(GitCommit { sha, summary, body });
732	    }
733	
734	    Ok(commits)
735	}
