40	struct ChildEnvironment<'a> {
41	    remove: &'a [&'a str],
42	    set: &'a [(&'a str, &'a str)],
43	}
44	
45	/// The release credentials a tool reads from its own environment. Every other release
46	/// credential is removed from its child process, so a tool never sees a secret it does not use.
47	/// A tool absent here needs none; publishers receive theirs explicitly instead.
48	fn credentials_needed_by(tool: &str) -> &'static [&'static str] {
49	    match tool {
50	        "npm" | "pnpm" | "yarn" | "bun" => &["NPM_CONFIG_TOKEN", "NPM_TOKEN", "NODE_AUTH_TOKEN"],
51	        "cargo" => &["CARGO_REGISTRY_TOKEN"],
52	        // `gh` reads GH_TOKEN, and GITHUB_TOKEN when that is unset; it runs the attestation
53	        // check and every forge call, and refuses to run without a token.
54	        "gh" => &["GH_TOKEN", "GITHUB_TOKEN"],
55	        _ => &[],
56	    }
57	}
58	
59	fn unrelated_credentials(program: &str) -> Vec<&'static str> {
60	    let tool = Path::new(program)
61	        .file_name()
62	        .and_then(|name| name.to_str())
63	        .unwrap_or(program);
64	    let keep = credentials_needed_by(tool);
65	    RELEASE_CREDENTIALS
66	        .iter()
67	        .copied()
68	        .filter(|credential| !keep.contains(credential))
69	        .collect()
70	}
