78	pub struct CliCommandRunner;
79	
80	impl CommandRunner for CliCommandRunner {
81	    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
82	        let mut command = std::process::Command::new(program);
83	        command.args(args).current_dir(cwd);
84	        remove_env(&mut command, &unrelated_credentials(program));
85	        let output = command
86	            .stdin(Stdio::null())
87	            .stdout(Stdio::piped())
88	            .stderr(Stdio::piped())
89	            .output();
90	
91	        match output {
92	            Ok(o) => {
93	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
94	                // Keep raw stderr available to callers for protocol/error
95	                // classification, but never leak credentials to the terminal.
96	                if !stderr.is_empty() {
97	                    let secrets = known_credential_env_values(std::env::vars());
98	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
99	                }
100	                Ok(CommandOutput {
101	                    exit_code: o.status.code(),
102	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
103	                    stderr,
104	                })
105	            }
106	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
107	                program: program.to_string(),
108	            }),
109	            Err(e) => Err(CommandError::Io {
110	                program: program.to_string(),
111	                message: e.to_string(),
112	            }),
113	        }
114	    }
115	
116	    fn run_with_timeout(
117	        &self,
118	        program: &str,
119	        args: &[&str],
120	        cwd: &Path,
121	        timeout: Duration,
122	    ) -> Result<CommandOutput, CommandError> {
123	        // `known_credential_env_values` is scanned here, at the trait-method
124	        // call site, rather than inside `run_with_timeout_impl` itself: this
125	        // keeps the impl fn pure and directly unit-testable with a synthetic
126	        // secrets list (no process-env mutation, which would race against
127	        // other tests running in parallel in this binary).
128	        let remove = unrelated_credentials(program);
129	        run_with_timeout_impl(
130	            program,
131	            args,
132	            cwd,
133	            timeout,
134	            StderrMode::Live,
135	            known_credential_env_values(std::env::vars()),
136	            ChildEnvironment {
137	                remove: &remove,
138	                set: &[],
139	            },
140	        )
141	    }
142	
143	    fn run_with_timeout_env_filtered(
144	        &self,
145	        program: &str,
146	        args: &[&str],
147	        cwd: &Path,
148	        timeout: Duration,
149	        removed: &[&str],
150	    ) -> Result<CommandOutput, CommandError> {
151	        let remove = unrelated_credentials(program)
152	            .into_iter()
153	            .chain(removed.iter().copied())
154	            .collect::<Vec<_>>();
155	        run_with_timeout_impl(
156	            program,
157	            args,
158	            cwd,
159	            timeout,
160	            StderrMode::Live,
161	            known_credential_env_values(std::env::vars()),
162	            ChildEnvironment {
163	                remove: &remove,
164	                set: &[],
165	            },
166	        )
167	    }
168	
169	    fn run_with_timeout_publisher(
170	        &self,
171	        program: &str,
172	        args: &[&str],
173	        cwd: &Path,
174	        timeout: Duration,
175	        env: &[(&str, &str)],
176	    ) -> Result<CommandOutput, CommandError> {
177	        let remove = unrelated_credentials(program)
178	            .into_iter()
179	            .chain(ACTION_SECRET_INPUTS.iter().copied())
180	            .collect::<Vec<_>>();
181	        run_with_timeout_impl(
182	            program,
183	            args,
184	            cwd,
185	            timeout,
186	            StderrMode::Live,
187	            known_credential_env_values(std::env::vars()),
188	            ChildEnvironment {
189	                remove: &remove,
190	                set: env,
191	            },
192	        )
193	    }
194	
195	    fn run_quiet(
196	        &self,
197	        program: &str,
198	        args: &[&str],
199	        cwd: &Path,
200	        timeout: Duration,
201	    ) -> Result<CommandOutput, CommandError> {
202	        // Quiet mode never echoes stderr live (see `StderrMode::Quiet`
203	        // below), so there's nothing to redact -- pass an empty secrets
204	        // list rather than paying for an env scan that can only go unused.
205	        let remove = unrelated_credentials(program);
206	        run_with_timeout_impl(
207	            program,
208	            args,
209	            cwd,
210	            timeout,
211	            StderrMode::Quiet,
212	            Vec::new(),
213	            ChildEnvironment {
214	                remove: &remove,
215	                set: &[],
216	            },
217	        )
218	    }
219	
220	    fn run_with_stdin(
221	        &self,
222	        program: &str,
223	        args: &[&str],
224	        cwd: &Path,
225	        stdin: &[u8],
226	    ) -> Result<CommandOutput, CommandError> {
227	        let mut command = std::process::Command::new(program);
228	        command.args(args).current_dir(cwd);
229	        remove_env(&mut command, &unrelated_credentials(program));
230	        let mut child = command
231	            .stdin(Stdio::piped())
232	            .stdout(Stdio::piped())
233	            .stderr(Stdio::piped())
234	            .spawn()
235	            .map_err(|e| {
236	                if e.kind() == std::io::ErrorKind::NotFound {
237	                    CommandError::NotFound {
238	                        program: program.to_string(),
239	                    }
240	                } else {
241	                    CommandError::Io {
242	                        program: program.to_string(),
243	                        message: e.to_string(),
244	                    }
245	                }
246	            })?;
247	
248	        // Write the payload on its own thread, concurrently with this
249	        // thread draining stdout/stderr via `wait_with_output` below.
250	        // A protocol like `git cat-file --batch` replies to each stdin
251	        // line as it arrives, so writing everything up front on the same
252	        // thread that also has to read the reply back could deadlock once
253	        // either the stdin or the stdout pipe buffer fills -- exactly the
254	        // hazard `run_with_timeout_impl` above uses dedicated reader
255	        // threads to avoid, mirrored here for the write side.
256	        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
257	        let payload = stdin.to_vec();
258	        let writer = std::thread::spawn(move || {
259	            // A closed read end (the child exited early, e.g. on a bad
260	            // invocation) would otherwise surface as a `BrokenPipe` write
261	            // error here; the child's actual exit code/stderr, captured by
262	            // `wait_with_output` below, is the caller-facing signal for
263	            // that failure, so a write error on this thread is dropped
264	            // rather than reported.
265	            drop(stdin_pipe.write_all(&payload));
266	            drop(stdin_pipe.flush());
267	        });
268	
269	        let output = child.wait_with_output();
270	        // The writer thread only writes then drops its handle, so it must
271	        // already be finished (or about to finish) by the time the child
272	        // has exited and `wait_with_output` has drained its output --
273	        // joining here can't block indefinitely.
274	        drop(writer.join());
275	
276	        match output {
277	            Ok(o) => {
278	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
279	                if !stderr.is_empty() {
280	                    let secrets = known_credential_env_values(std::env::vars());
281	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
282	                }
283	                Ok(CommandOutput {
284	                    exit_code: o.status.code(),
285	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
286	                    stderr,
287	                })
288	            }
289	            Err(e) => Err(CommandError::Io {
290	                program: program.to_string(),
291	                message: e.to_string(),
292	            }),
293	        }
294	    }
295	}
