297	/// Controls whether [`run_with_timeout_impl`]'s stderr reader thread prints
298	/// each line live as it arrives. Captured `CommandOutput.stderr` is
299	/// identical either way -- this only affects what's echoed to the
300	/// terminal while the subprocess runs.
301	#[derive(Clone, Copy, PartialEq, Eq)]
302	enum StderrMode {
303	    Live,
304	    Quiet,
305	}
306	
307	/// `live_secrets`: known-credential values (see
308	/// [`callisto_model::known_credential_env_values`]) to redact from each
309	/// line *before* it's echoed live to the terminal via `eprintln!`. This is
310	/// deliberately separate from -- and does not affect -- the `captured`
311	/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
312	/// stay byte-for-byte raw so downstream classifiers (e.g.
313	/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
314	/// exact upstream text. Callers pass the secrets list in rather than this
315	/// function reading the environment itself, keeping it pure and testable
316	/// with a synthetic list.
317	fn run_with_timeout_impl(
318	    program: &str,
319	    args: &[&str],
320	    cwd: &Path,
321	    timeout: Duration,
322	    stderr_mode: StderrMode,
323	    live_secrets: Vec<String>,
324	    child_env: ChildEnvironment<'_>,
325	) -> Result<CommandOutput, CommandError> {
326	    let mut command = std::process::Command::new(program);
327	    command
328	        .args(args)
329	        .current_dir(cwd)
330	        .stdin(Stdio::null())
331	        .stdout(Stdio::piped())
332	        .stderr(Stdio::piped());
333	    for name in child_env.remove {
334	        command.env_remove(name);
335	    }
336	    for (name, value) in child_env.set {
337	        command.env(name, value);
338	    }
339	    let mut child = command.spawn().map_err(|e| {
340	        if e.kind() == std::io::ErrorKind::NotFound {
341	            CommandError::NotFound {
342	                program: program.to_string(),
343	            }
344	        } else {
345	            CommandError::Io {
346	                program: program.to_string(),
347	                message: e.to_string(),
348	            }
349	        }
350	    })?;
351	
352	    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
353	    // when the child produces output while we wait for it to exit.
354	    let stdout_handle = child.stdout.take().unwrap();
355	    let stderr_handle = child.stderr.take().unwrap();
356	
357	    // The reader threads signal completion over a channel rather than
358	    // being joined directly. Killing (or the natural exit of) the
359	    // direct child does NOT close pipe fds held open by a descendant
360	    // process that inherited them (common for npm/cargo/python publish
361	    // lifecycle scripts spawning subprocesses). If that happens, the
362	    // blocking `read()` inside these threads never returns. Using
363	    // `recv_timeout` below lets us bound how long we wait for them
364	    // without ever blocking the caller indefinitely.
365	    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
366	    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();
367	
368	    std::thread::spawn(move || {
369	        let mut reader = stdout_handle;
370	        let mut captured: Vec<u8> = Vec::new();
371	        let mut truncated = false;
372	        let mut chunk = [0u8; 65536];
373	        loop {
374	            match reader.read(&mut chunk) {
375	                Ok(0) => break,
376	                Ok(n) => {
377	                    // Bytes past the cap are still read (draining the
378	                    // pipe so the child never blocks on a full buffer)
379	                    // but not retained.
380	                    if !truncated {
381	                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
382	                        let take = n.min(remaining);
383	                        captured.extend_from_slice(&chunk[..take]);
384	                        if take < n {
385	                            truncated = true;
386	                        }
387	                    }
388	                }
389	                Err(_) => break,
390	            }
391	        }
392	        let mut text = String::from_utf8_lossy(&captured).into_owned();
393	        if truncated {
394	            text.push_str("\n...[output truncated]\n");
395	        }
396	        drop(stdout_tx.send(text));
397	    });
398	    // Stream stderr line-by-line so publish progress (cargo/npm/twine
399	    // write to stderr) appears in real time rather than after the
400	    // process exits, while capping the accumulated text returned to
401	    // the caller. Deliberately reads raw bytes rather than using
402	    // `BufReader::lines()`: that iterator has no size bound on a
403	    // single line, so a flood with no newlines at all would still
404	    // buffer unboundedly inside it before ever yielding a line to cap.
405	    // `stderr_mode` gates only the live eprintln -- captured output is
406	    // identical either way (Live vs. Quiet).
407	    //
408	    // NOTE: captured output is no longer necessarily byte-identical to
409	    // what was printed live. Each line handed to `eprintln!` is redacted
410	    // via `live_secrets` first (registry CLIs can echo a credential
411	    // verbatim in their own stderr diagnostics), while `captured` -- and
412	    // therefore the returned `CommandOutput.stderr` -- deliberately stays
413	    // raw so error classifiers keep matching exact upstream text. For a
414	    // credential-bearing line, the terminal sees `[REDACTED]`; the
415	    // returned `CommandOutput.stderr` still has the real value.
416	    std::thread::spawn(move || {
417	        let mut reader = stderr_handle;
418	        let mut captured: Vec<u8> = Vec::new();
419	        let mut truncated = false;
420	        let mut pending_line: Vec<u8> = Vec::new();
421	        let mut chunk = [0u8; 65536];
422	        loop {
423	            match reader.read(&mut chunk) {
424	                Ok(0) => break,
425	                Ok(n) => {
426	                    let data = &chunk[..n];
427	                    for &b in data {
428	                        if b == b'\n' {
429	                            if pending_line.last() == Some(&b'\r') {
430	                                pending_line.pop();
431	                            }
432	                            if stderr_mode == StderrMode::Live {
433	                                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
434	                                eprintln!("{line}");
435	                            }
436	                            pending_line.clear();
437	                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
438	                            pending_line.push(b);
439	                        }
440	                    }
441	                    if !truncated {
442	                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
443	                        let take = data.len().min(remaining);
444	                        captured.extend_from_slice(&data[..take]);
445	                        if take < data.len() {
446	                            truncated = true;
447	                        }
448	                    }
449	                }
450	                Err(_) => break,
451	            }
452	        }
453	        if !pending_line.is_empty() {
454	            if pending_line.last() == Some(&b'\r') {
455	                pending_line.pop();
456	            }
457	            if stderr_mode == StderrMode::Live {
458	                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
459	                eprintln!("{line}");
460	            }
461	        }
462	        let mut text = String::from_utf8_lossy(&captured).into_owned();
463	        if truncated {
464	            text.push_str("\n...[output truncated]\n");
465	        }
466	        drop(stderr_tx.send(text));
467	    });
468	
469	    // Grace period to wait for the reader threads after the direct
