1	//! Artifact-byte and GitHub-attestation verification for durable releases.
2	//!
3	//! A manifest is only a claim. This module verifies the actual on-disk bytes
4	//! and asks GitHub to validate the signing certificate against the policy
5	//! embedded in the immutable release intent before an executor can upload an
6	//! asset. It intentionally owns no upload side effect.
7	
8	use std::{
9	    fs::{self, File},
10	    path::{Component, Path, PathBuf},
11	};
12	
13	use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};
14	
15	use crate::GraphError;
16	
17	use super::release::provider::policy::{self, retry_observation, run_observation, Attempt};
18	use super::release::{programs, timeouts};
19	
20	/// The sealed file set of every Python publish in `intent`, from the build output in `dir`.
21	pub fn seal_python_distributions(
22	    intent: &ReleaseIntentV1,
23	    dir: &Path,
24	) -> Result<Vec<callisto_model::DistributionSetV1>, GraphError> {
25	    let root = canonical_artifact_root(dir)?;
26	    super::release::provider::seal_distributions(intent, &root)
27	}
28	
29	/// One verified file of a sealed Python release.
30	#[derive(Debug)]
31	pub(crate) struct SealedFile {
32	    pub(crate) filename: String,
33	    pub(crate) path: PathBuf,
34	    pub(crate) sha256: String,
35	}
36	
37	/// A manifest whose exact local bytes and GitHub provenance have been checked.
38	///
39	/// The constructor is private: callers can obtain this capability only with
40	/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
41	/// silently substitute a different manifest after verification.
42	#[derive(Debug)]
43	pub struct VerifiedArtifactManifest<'a> {
44	    manifest: &'a ArtifactManifestV1,
45	    root: PathBuf,
46	}
47	
48	impl<'a> VerifiedArtifactManifest<'a> {
49	    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
50	        self.manifest
51	    }
52	
53	    /// Test-only pairing of a manifest with a root, for simulators whose
54	    /// providers issue no real upload and read no local asset bytes.
55	    #[cfg(test)]
56	    pub(crate) fn for_tests(manifest: &'a ArtifactManifestV1, root: PathBuf) -> Self {
57	        Self { manifest, root }
58	    }
59	
60	    pub(crate) fn path_for(&self, slot: &callisto_model::ArtifactSlotId) -> Result<PathBuf, GraphError> {
61	        resolve_asset_path(&self.root, &slot.asset_name)
62	    }
63	
64	    /// The sealed files of one Python release, or `None` when the manifest seals none.
65	    pub(crate) fn sealed_files(
66	        &self,
67	        package: &callisto_model::ReleasePackageId,
68	        version: &callisto_model::Version,
69	    ) -> Option<Vec<SealedFile>> {
70	        let rendered = version.render();
71	        let set = self
72	            .manifest
73	            .distributions
74	            .iter()
75	            .find(|set| set.package == *package && set.version == rendered)?;
76	        Some(
77	            set.files
78	                .iter()
79	                .map(|file| SealedFile {
80	                    filename: file.filename.clone(),
81	                    path: self.root.join(&file.filename),
82	                    sha256: file.digest.as_str().to_owned(),
83	                })
84	                .collect(),
85	        )
86	    }
87	
88	    /// Returns the already intent-bound manifest entry for `slot`.
89	    pub(crate) fn entry_for(
90	        &self,
91	        slot: &callisto_model::ArtifactSlotId,
92	    ) -> Result<&callisto_model::ArtifactManifestEntryV1, GraphError> {
93	        self.manifest
94	            .entries
95	            .iter()
96	            .find(|entry| entry.slot == *slot)
97	            .ok_or_else(|| GraphError::ReleaseInvariant {
98	                detail: format!("verified artifact manifest has no entry for `{}`", slot.asset_name),
99	            })
100	    }
101	}
102	
103	/// Verifies every manifest entry against the exact artifact directory.
104	///
105	/// The artifact directory and every candidate are canonicalized, and symbolic
106	/// links are rejected, so a manifest asset name cannot escape the supplied
107	/// build-output directory. Each asset is streamed once for a bounded-memory
108	/// SHA-256 and size comparison. `gh attestation verify` then validates the
109	/// repository, workflow path and commit, source commit, and hosted-runner
110	/// policy declared by the immutable artifact slot.
111	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
112	    intent: &ReleaseIntentV1,
113	    manifest: &'a ArtifactManifestV1,
114	    artifact_root: &Path,
115	    runner: &R,
116	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
117	    manifest
118	        .validate_for_intent(intent)
119	        .map_err(|source| GraphError::ArtifactManifest { source })?;
120	
121	    let root = canonical_artifact_root(artifact_root)?;
122	    for entry in &manifest.entries {
123	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
124	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
125	            path: path.clone(),
126	            message: error.to_string(),
127	        })?;
128	        let (digest, length) =
129	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
130	                path: path.clone(),
131	                message: error.to_string(),
132	            })?;
133	        if digest != entry.digest || length != entry.byte_length {
134	            return Err(GraphError::ArtifactBytesMismatch { path });
135	        }
136	
137	        verify_github_attestation(&path, entry, runner)?;
138	    }
139	    for file in manifest.distributions.iter().flat_map(|set| &set.files) {
140	        let path = resolve_asset_path(&root, &file.filename)?;
141	        let opened = File::open(&path).map_err(|error| GraphError::ArtifactRead {
142	            path: path.clone(),
143	            message: error.to_string(),
144	        })?;
145	        let (digest, length) =
146	            callisto_model::ArtifactDigest::from_reader(opened).map_err(|error| GraphError::ArtifactRead {
147	                path: path.clone(),
148	                message: error.to_string(),
149	            })?;
150	        if digest != file.digest || length != file.byte_length {
151	            return Err(GraphError::ArtifactBytesMismatch { path });
152	        }
153	    }
154	    Ok(VerifiedArtifactManifest { manifest, root })
155	}
156	
157	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
158	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
159	        path: artifact_root.to_path_buf(),
160	        message: error.to_string(),
161	    })?;
162	    if !metadata.is_dir() {
163	        return Err(GraphError::UnsafeArtifactPath {
164	            path: artifact_root.to_path_buf(),
165	            reason: "artifact root is not a directory",
166	        });
167	    }
168	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
169	        path: artifact_root.to_path_buf(),
170	        message: error.to_string(),
171	    })
172	}
173	
174	fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
175	    let relative = Path::new(asset_name);
176	    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
177	        return Err(GraphError::UnsafeArtifactPath {
178	            path: relative.to_path_buf(),
179	            reason: "asset name is not a single relative file name",
180	        });
181	    }
182	    let candidate = root.join(relative);
183	    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
184	        path: candidate.clone(),
185	        message: error.to_string(),
186	    })?;
187	    if metadata.file_type().is_symlink() {
188	        return Err(GraphError::UnsafeArtifactPath {
189	            path: candidate,
190	            reason: "symbolic links are not accepted as artifacts",
191	        });
192	    }
193	    if !metadata.is_file() {
194	        return Err(GraphError::UnsafeArtifactPath {
195	            path: candidate,
196	            reason: "artifact is not a regular file",
197	        });
198	    }
199	    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
200	        path: candidate.clone(),
201	        message: error.to_string(),
202	    })?;
203	    if !canonical.starts_with(root) {
204	        return Err(GraphError::UnsafeArtifactPath {
205	            path: canonical,
206	            reason: "artifact resolves outside artifact root",
207	        });
208	    }
209	    Ok(canonical)
210	}
211	
212	fn verify_github_attestation<R: CommandRunner>(
213	    path: &Path,
214	    entry: &callisto_model::ArtifactManifestEntryV1,
215	    runner: &R,
216	) -> Result<(), GraphError> {
217	    let attestation_policy = &entry.slot.attestation_policy;
218	    let repository_slug = attestation_policy.repository.as_slug();
219	    let workflow = format!("{repository_slug}/{}", attestation_policy.workflow_path);
220	    let path_argument = path.to_string_lossy();
221	    let source_commit = entry.attestation.source_commit.as_str();
222	    let args = [
223	        "attestation",
224	        "verify",
225	        path_argument.as_ref(),
226	        "--repo",
227	        repository_slug.as_str(),
228	        "--signer-workflow",
229	        workflow.as_str(),
230	        "--signer-digest",
231	        attestation_policy.workflow_commit.as_str(),
232	        "--source-digest",
233	        source_commit,
234	        "--deny-self-hosted-runners",
235	    ];
236	    let cwd = path.parent().unwrap_or_else(|| Path::new("."));
237	    let sleeper = policy::ThreadSleeper;
238	    let succeeded = retry_observation(&sleeper, || attempt_attestation_verify(runner, &args, cwd))?;
239	    if succeeded {
240	        Ok(())
241	    } else {
242	        Err(GraphError::ArtifactAttestation {
243	            path: path.to_path_buf(),
244	            message: "GitHub attestation verification failed".to_owned(),
245	        })
246	    }
247	}
248	
249	/// A timed-out `gh attestation verify` is a transient observation, not a hard failure that aborts the release.
250	fn attempt_attestation_verify<R: CommandRunner>(
251	    runner: &R,
252	    args: &[&str],
253	    cwd: &Path,
254	) -> Result<Attempt<bool>, GraphError> {
255	    let observed = match run_observation(runner, programs::GH, args, cwd, timeouts::ATTESTATION_VERIFY, false)? {
256	        Ok(output) => output,
257	        Err(_unavailable) => {
258	            return Ok(Attempt::Transient {
259	                value: false,
260	                retry_after: None,
261	            })
262	        }
263	    };
264	    Ok(Attempt::Settled(observed.success()))
265	}
