use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};

use crate::GraphError;

use super::release::provider::policy::{self, retry_observation, run_observation, Attempt};
use super::release::{programs, timeouts};

/// The sealed file set of every Python publish in `intent`, from the build output in `dir`.
pub fn seal_python_distributions(
    intent: &ReleaseIntentV1,
    dir: &Path,
) -> Result<Vec<callisto_model::DistributionSetV1>, GraphError> {
    let root = canonical_artifact_root(dir)?;
    super::release::provider::seal_distributions(intent, &root)
}

/// One verified file of a sealed Python release.
#[derive(Debug)]
pub(crate) struct SealedFile {
    pub(crate) filename: String,
    pub(crate) path: PathBuf,
    pub(crate) sha256: String,
}

/// A manifest whose exact local bytes and GitHub provenance have been checked.
///
/// The constructor is private: callers can obtain this capability only with
/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
/// silently substitute a different manifest after verification.
#[derive(Debug)]
pub struct VerifiedArtifactManifest<'a> {
    manifest: &'a ArtifactManifestV1,
    root: PathBuf,
}

impl<'a> VerifiedArtifactManifest<'a> {
    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
        self.manifest
    }

    /// Test-only pairing of a manifest with a root, for simulators whose
    /// providers issue no real upload and read no local asset bytes.
    #[cfg(test)]
    pub(crate) fn for_tests(manifest: &'a ArtifactManifestV1, root: PathBuf) -> Self {
        Self { manifest, root }
    }

    pub(crate) fn path_for(&self, slot: &callisto_model::ArtifactSlotId) -> Result<PathBuf, GraphError> {
        resolve_asset_path(&self.root, &slot.asset_name)
    }

    /// The sealed files of one Python release, or `None` when the manifest seals none.
    pub(crate) fn sealed_files(
        &self,
        package: &callisto_model::ReleasePackageId,
        version: &callisto_model::Version,
    ) -> Option<Vec<SealedFile>> {
        let rendered = version.render();
        let set = self
            .manifest
            .distributions
            .iter()
            .find(|set| set.package == *package && set.version == rendered)?;
        Some(
            set.files
                .iter()
                .map(|file| SealedFile {
                    filename: file.filename.clone(),
                    path: self.root.join(&file.filename),
                    sha256: file.digest.as_str().to_owned(),
                })
                .collect(),
        )
    }

    /// Returns the already intent-bound manifest entry for `slot`.
    pub(crate) fn entry_for(
        &self,
        slot: &callisto_model::ArtifactSlotId,
    ) -> Result<&callisto_model::ArtifactManifestEntryV1, GraphError> {
        self.manifest
            .entries
            .iter()
            .find(|entry| entry.slot == *slot)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("verified artifact manifest has no entry for `{}`", slot.asset_name),
            })
    }
}

/// Verifies every manifest entry against the exact artifact directory.
///
/// The artifact directory and every candidate are canonicalized, and symbolic
/// links are rejected, so a manifest asset name cannot escape the supplied
/// build-output directory. Each asset is streamed once for a bounded-memory
/// SHA-256 and size comparison. `gh attestation verify` then validates the
/// repository, workflow path and commit, source commit, and hosted-runner
/// policy declared by the immutable artifact slot.
pub fn verify_artifact_manifest<'a, R: CommandRunner>(
    intent: &ReleaseIntentV1,
    manifest: &'a ArtifactManifestV1,
    artifact_root: &Path,
    runner: &R,
) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
    manifest
        .validate_for_intent(intent)
        .map_err(|source| GraphError::ArtifactManifest { source })?;

    let root = canonical_artifact_root(artifact_root)?;
    for entry in &manifest.entries {
        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
            path: path.clone(),
            message: error.to_string(),
        })?;
        let (digest, length) =
            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
                path: path.clone(),
                message: error.to_string(),
            })?;
        if digest != entry.digest || length != entry.byte_length {
            return Err(GraphError::ArtifactBytesMismatch { path });
        }

        verify_github_attestation(&path, entry, runner)?;
    }
    for file in manifest.distributions.iter().flat_map(|set| &set.files) {
        let path = resolve_asset_path(&root, &file.filename)?;
        let opened = File::open(&path).map_err(|error| GraphError::ArtifactRead {
            path: path.clone(),
            message: error.to_string(),
        })?;
        let (digest, length) =
            callisto_model::ArtifactDigest::from_reader(opened).map_err(|error| GraphError::ArtifactRead {
                path: path.clone(),
                message: error.to_string(),
            })?;
        if digest != file.digest || length != file.byte_length {
            return Err(GraphError::ArtifactBytesMismatch { path });
        }
    }
    Ok(VerifiedArtifactManifest { manifest, root })
}

fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })?;
    if !metadata.is_dir() {
        return Err(GraphError::UnsafeArtifactPath {
            path: artifact_root.to_path_buf(),
            reason: "artifact root is not a directory",
        });
    }
    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })
}

fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
    let relative = Path::new(asset_name);
    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
        return Err(GraphError::UnsafeArtifactPath {
            path: relative.to_path_buf(),
            reason: "asset name is not a single relative file name",
        });
    }
    let candidate = root.join(relative);
    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
        path: candidate.clone(),
        message: error.to_string(),
    })?;
    if metadata.file_type().is_symlink() {
        return Err(GraphError::UnsafeArtifactPath {
            path: candidate,
            reason: "symbolic links are not accepted as artifacts",
        });
    }
    if !metadata.is_file() {
        return Err(GraphError::UnsafeArtifactPath {
            path: candidate,
            reason: "artifact is not a regular file",
        });
    }
    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
        path: candidate.clone(),
        message: error.to_string(),
    })?;
    if !canonical.starts_with(root) {
        return Err(GraphError::UnsafeArtifactPath {
            path: canonical,
            reason: "artifact resolves outside artifact root",
        });
    }
    Ok(canonical)
}

fn verify_github_attestation<R: CommandRunner>(
    path: &Path,
    entry: &callisto_model::ArtifactManifestEntryV1,
    runner: &R,
) -> Result<(), GraphError> {
    let attestation_policy = &entry.slot.attestation_policy;
    let repository_slug = attestation_policy.repository.as_slug();
    let workflow = format!("{repository_slug}/{}", attestation_policy.workflow_path);
    let path_argument = path.to_string_lossy();
    let source_commit = entry.attestation.source_commit.as_str();
    let args = [
        "attestation",
        "verify",
        path_argument.as_ref(),
        "--repo",
        repository_slug.as_str(),
        "--signer-workflow",
        workflow.as_str(),
        "--signer-digest",
        attestation_policy.workflow_commit.as_str(),
        "--source-digest",
        source_commit,
        "--deny-self-hosted-runners",
    ];
    let cwd = path.parent().unwrap_or_else(|| Path::new("."));
    let sleeper = policy::ThreadSleeper;
    let succeeded = retry_observation(&sleeper, || attempt_attestation_verify(runner, &args, cwd))?;
    if succeeded {
        Ok(())
    } else {
        Err(GraphError::ArtifactAttestation {
            path: path.to_path_buf(),
            message: "GitHub attestation verification failed".to_owned(),
        })
    }
}

/// A timed-out `gh attestation verify` is a transient observation, not a hard failure that aborts the release.
fn attempt_attestation_verify<R: CommandRunner>(
    runner: &R,
    args: &[&str],
    cwd: &Path,
) -> Result<Attempt<bool>, GraphError> {
    let observed = match run_observation(runner, programs::GH, args, cwd, timeouts::ATTESTATION_VERIFY, false)? {
        Ok(output) => output,
        Err(_unavailable) => {
            return Ok(Attempt::Transient {
                value: false,
                retry_after: None,
            })
        }
    };
    Ok(Attempt::Settled(observed.success()))
}

